window.EXTRA = {"1763265164777":{"ex":"오늘은 바람이 아주 시원해요.","exFr":"Aujourd'hui, le vent est très frais.","note":"≠ 시내 (centre-ville), 시다 (acide). Se dit aussi d'une soupe qui soulage","conj":"시원해요 · 시원했어요"},"1764056652259":{"ex":"방이 너무 어두워요. 불을 켜세요.","exFr":"La pièce est trop sombre. Allumez la lumière.","note":"≠ 어렵다 (difficile). ㅂ irrégulier : 어두워요","conj":"어두워요 · 어두웠어요"},"1763264848946":{"ex":"요즘 일이 많아서 너무 피곤해요.","exFr":"Ces temps-ci, j'ai beaucoup de travail, je suis épuisé.","note":"≠ 필요하다 (nécessaire)","conj":"피곤해요 · 피곤했어요"},"1763265607506":{"ex":"가끔 혼자 영화를 봐요.","exFr":"Parfois, je regarde un film seul.","note":"≠ 자주 (souvent), 가격 (prix), 가깝다 (proche)"},"1763265674186":{"ex":"귀여운 강아지가 공원에서 놀아요.","exFr":"Un chiot mignon joue dans le parc.","note":"개 + -아지 (diminutif). ≠ 돼지 (cochon), 잡지 (magazine)"},"1763264080583":{"ex":"그 배우는 너무 말랐어요.","exFr":"Cet acteur est très maigre.","note":"르 irrég. : 말라요, 말랐어요. ≠ 마시다 (boire). Aussi : être sec","conj":"말라요 · 말랐어요"},"1763265361538":{"ex":"혹시 다른 색은 없어요?","exFr":"Vous n'auriez pas une autre couleur ?","note":"déterminant. ≠ 다르다 (être différent), 다리 (jambe)"},"1765642560428":{"ex":"저는 패션 잡지를 자주 읽어요.","exFr":"Je lis souvent des magazines de mode.","note":"雜誌. ≠ 잡다 (attraper), 강아지 (chiot)"},"1763266738564":{"ex":"아이가 장난감을 가지고 놀아요.","exFr":"L'enfant joue avec un jouet.","note":"장난 (espièglerie) + 감. ≠ 장갑 (gants), 장점 (atout)"},"1763264822265":{"ex":"상자 크기가 너무 커요.","exFr":"La taille de la boîte est trop grande.","note":"크다 + -기 (nominalisation). ≠ 고기 (viande), 여기 (ici)"},"1765435052266":{"ex":"모르는 단어는 사전에서 찾아요.","exFr":"Je cherche les mots inconnus dans le dictionnaire.","note":"辭典. ≠ 사진 (photo), 사촌 (cousin)"},"1780695436396":{"ex":"고향 음식이 정말 그리워요.","exFr":"La cuisine de mon pays me manque vraiment.","note":"lieux, passé. Pour une personne : 보고 싶다. ≠ 그리고 (et puis)","conj":"그리워요 · 그리웠어요"},"1780695436392":{"ex":"그 소식을 듣고 정말 놀랐어요.","exFr":"J'ai été très surpris en apprenant la nouvelle.","note":"≠ 놀다 (jouer). Presque toujours au passé : 놀랐어요","conj":"놀라요 · 놀랐어요"},"1780695436394":{"ex":"내일 여행을 가요. 정말 신나요!","exFr":"Demain je pars en voyage. Je suis surexcité !","note":"≠ 신다 (chausser), 신청하다 (s'inscrire), 신선하다 (frais)","conj":"신나요 · 신났어요"},"1763265272638":{"ex":"혼자 살면 가끔 외로워요.","exFr":"Quand on vit seul, on se sent parfois seul.","note":"solitude ressentie ≠ 혼자 (seul, factuel). ㅂ irrég. : 외로워요","conj":"외로워요 · 외로웠어요"},"1780695436393":{"ex":"친구들하고 즐거운 시간을 보냈어요.","exFr":"J'ai passé un bon moment avec mes amis.","note":"≠ 즐기다 (profiter de). ㅂ irrég. : 즐거워요","conj":"즐거워요 · 즐거웠어요"},"1780695436474":{"ex":"제 조카는 다섯 살이에요.","exFr":"Mon neveu a cinq ans.","note":"un seul mot pour neveu et nièce. ≠ 조금 (un peu), 사촌 (cousin)"},"1763107375732":{"ex":"이번 방학에 고향에 돌아가요.","exFr":"Ces vacances, je rentre dans ma ville natale.","note":"故鄕. ≠ 고양이 (chat), 고기 (viande)"},"1763264976938":{"ex":"서점에서 한국어 책을 샀어요.","exFr":"J'ai acheté un livre de coréen à la librairie.","note":"書店. -점 (店) = boutique. ≠ 서류 (documents), 사전 (dictionnaire)"},"1763264935489":{"ex":"오후에 시내에서 친구를 만나요.","exFr":"Cet après-midi, je retrouve un ami en centre-ville.","note":"市內. ≠ 시장 (marché), 시간 (heure)"},"1763264431990":{"ex":"지하철 3번 출구에서 만나요.","exFr":"On se retrouve à la sortie 3 du métro.","note":"出口. 입구 = entrée. ≠ 출발 (départ), 출근 (aller au travail)"},"1764053666655":{"ex":"가수가 드디어 무대에 올라갔어요.","exFr":"Le chanteur est enfin monté sur scène.","note":"舞臺. ≠ 무섭다 (effrayant), 침대 (lit)"},"1763264804067":{"ex":"저녁마다 강아지랑 공원을 산책해요.","exFr":"Chaque soir, je promène mon chien au parc.","note":"散策. ≠ 산 (montagne) tout seul","conj":"산책해요 · 산책했어요"},"1779724539690":{"ex":"이번 여름에 여행을 가요.","exFr":"Cet été, je pars en voyage.","note":"旅行. ≠ 여권 (passeport), 여름 (été)"},"1779724539693":{"ex":"저는 춤을 잘 못 춰요.","exFr":"Je ne danse pas très bien.","note":"춤을 추다 = danser (verbe de la même famille)"},"1763265002926":{"ex":"우유는 냉장고 안에 있어요.","exFr":"Le lait est dans le réfrigérateur.","note":"冷藏庫 : 냉 (froid) + 장 (conserver) + 고 (entrepôt)"},"1763265586739":{"ex":"저는 주말마다 빨래를 해요.","exFr":"Je fais la lessive chaque week-end.","note":"≠ 빨리 (vite), 빨간색 (rouge). 설거지하다 = faire la vaisselle","conj":"빨래해요 · 빨래했어요"},"1780695436503":{"ex":"우리 형은 시청 공무원이에요.","exFr":"Mon grand frère est fonctionnaire à la mairie.","note":"公務員. -원 (員) = membre : 회사원, 직원. ≠ 공원 (parc)"},"1763266237900":{"ex":"수업 후에 교수님께 질문했어요.","exFr":"Après le cours, j'ai posé une question au professeur.","note":"敎授. Toujours 교수님 face à lui. ≠ 가수 (chanteur), 선수 (athlète)"},"1763107175562":{"ex":"그 선수는 정말 빨라요.","exFr":"Cet athlète est vraiment rapide.","note":"選手. -수 (手) = personne. ≠ 가수 (chanteur), 교수 (prof)"},"1763107259609":{"ex":"이 소설의 작가를 좋아해요.","exFr":"J'aime l'auteur de ce roman.","note":"作家. -가 (家) = expert. ≠ 작다 (petit), 가수 (chanteur)"},"1764056242442":{"ex":"오후 세 시에 간식을 먹어요.","exFr":"À 15 h, je prends un goûter.","note":"間食 : nourriture « entre » les repas. ≠ 음식 (nourriture)"},"1763265850560":{"ex":"아이들은 단 과자를 좋아해요.","exFr":"Les enfants aiment les biscuits sucrés.","note":"菓子. ≠ 과일 (fruit), 감자 (pomme de terre)"},"1780695436443":{"ex":"여름에는 복숭아가 제일 맛있어요.","exFr":"En été, les pêches sont les meilleures.","note":"≠ 복잡하다 (compliqué)"},"1763264884004":{"ex":"어제 가족과 같이 식사했어요.","exFr":"Hier, j'ai pris un repas en famille.","note":"食事. 식사하셨어요? = avez-vous mangé ? ≠ 인사하다 (saluer)","conj":"식사해요 · 식사했어요"},"1763265766465":{"ex":"이 국은 조금 짜요.","exFr":"Cette soupe est un peu salée.","note":"≠ 짜증나다 (agacé), 싸다 (bon marché)","conj":"짜요 · 짰어요"},"1763263748305":{"ex":"동생은 사람들 앞에서 수줍어해요.","exFr":"Ma petite sœur est timide devant les gens.","note":"≠ 수영하다 (nager). 수줍음 = timidité","conj":"수줍어해요 · 수줍어했어요"},"1763263674596":{"ex":"제 친구는 정말 착해요.","exFr":"Mon ami est vraiment gentil.","note":"bon de cœur ≠ 친절하다 (aimable en surface)","conj":"착해요 · 착했어요"},"1763263855904":{"ex":"그 가게 직원이 아주 친절해요.","exFr":"L'employé de ce magasin est très aimable.","note":"親切. ≠ 착하다 (bon cœur), 친하다 (être proche de qqn)","conj":"친절해요 · 친절했어요"},"1780695436423":{"ex":"테이블 가운데에 꽃이 있어요.","exFr":"Il y a des fleurs au milieu de la table.","note":"≠ 사이에 (entre deux choses)"},"1779724539687":{"ex":"매달 25일에 월급을 받아요.","exFr":"Je touche mon salaire le 25 de chaque mois.","note":"月給 : paie du mois. ≠ 월요일 (lundi)"},"1763264391869":{"ex":"저는 부모님과 자주 대화해요.","exFr":"Je discute souvent avec mes parents.","note":"對話. ≠ 대학교 (université). 대화 = conversation","conj":"대화해요 · 대화했어요"},"1780695436519":{"ex":"이 앱을 매일 사용해요.","exFr":"J'utilise cette appli tous les jours.","note":"使用. Synonyme courant : 쓰다. ≠ 사다 (acheter)","conj":"사용해요 · 사용했어요"},"1764058494040":{"ex":"주말에 책상을 깨끗하게 정리했어요.","exFr":"Ce week-end, j'ai bien rangé mon bureau.","note":"整理. ≠ 정류장 (arrêt), 정말 (vraiment)","conj":"정리해요 · 정리했어요"},"1764053571988":{"ex":"커피 두 잔을 주문했어요.","exFr":"J'ai commandé deux cafés.","note":"注文. ≠ 주다 (donner), 질문 (question)","conj":"주문해요 · 주문했어요"},"1780695436378":{"ex":"겨울에는 따뜻한 목도리를 해요.","exFr":"En hiver, je porte une écharpe chaude.","note":"목 (cou) + 도리. 목도리를 하다. ≠ 목요일 (jeudi), 목적 (but)"},"1780695436376":{"ex":"안경을 안 쓰면 잘 안 보여요.","exFr":"Sans lunettes, je ne vois pas bien.","note":"眼鏡. 안경을 쓰다 = porter des lunettes. ≠ 환경 (environnement)"},"1780695436377":{"ex":"날씨가 추워서 장갑을 꼈어요.","exFr":"Comme il fait froid, j'ai mis des gants.","note":"장갑을 끼다. ≠ 지갑 (portefeuille), 장난감 (jouet)"},"1781435310408":{"ex":"오늘 시험 결과가 나왔어요.","exFr":"Les résultats de l'examen sont sortis aujourd'hui.","note":"結果. ≠ 사과 (pomme), 결정 (décision)"},"1781435310413":{"ex":"매일 노력하면 한국어가 늘어요.","exFr":"Avec des efforts quotidiens, le coréen progresse.","note":"努力. ≠ 능력 (capacité), 경력 (carrière)"},"1781435310285":{"ex":"시간이 부족해서 못 끝냈어요.","exFr":"Je n'ai pas fini, faute de temps.","note":"不足. ≠ 가족 (famille), 만족하다 (être satisfait)","conj":"부족해요 · 부족했어요"},"1781435310296":{"ex":"그는 항상 신중하게 결정해요.","exFr":"Il décide toujours avec prudence.","note":"愼重. ≠ 소중하다 (précieux), 신청하다 (s'inscrire)","conj":"신중해요 · 신중했어요"},"1781435310291":{"ex":"벌써 가요? 정말 아쉬워요.","exFr":"Vous partez déjà ? Quel dommage.","note":"regret léger ≠ 후회하다 (remords). ㅂ irrég. : 아쉬워요","conj":"아쉬워요 · 아쉬웠어요"},"1781435310289":{"ex":"이제 한국 음식에 익숙해요.","exFr":"Je suis maintenant habitué à la cuisine coréenne.","note":"N에 익숙하다 = être habitué à N","conj":"익숙해요 · 익숙했어요"},"1781435310284":{"ex":"그 정보는 정확하지 않아요.","exFr":"Cette information n'est pas exacte.","note":"正確. ≠ 정직하다 (honnête), 확실하다 (certain)","conj":"정확해요 · 정확했어요"},"1781435310286":{"ex":"시간은 한 시간이면 충분해요.","exFr":"Une heure, c'est suffisant.","note":"充分. Contraire : 부족하다 (insuffisant)","conj":"충분해요 · 충분했어요"},"1763266180475":{"ex":"무대 옷이 정말 화려해요.","exFr":"Le costume de scène est vraiment somptueux.","note":"華麗. ≠ 화나다 (fâché), 화장실 (toilettes)","conj":"화려해요 · 화려했어요"},"1781435310310":{"ex":"두 사람은 좋은 관계예요.","exFr":"Ces deux personnes ont une bonne relation.","note":"關係. ≠ 관심 (intérêt), 관광 (tourisme)"},"1781435310314":{"ex":"일찍 일어나는 습관이 있어요.","exFr":"J'ai l'habitude de me lever tôt.","note":"習慣. ≠ 도서관 (bibliothèque), 시간 (heure)"},"1781435310316":{"ex":"그 사람은 정직해서 믿을 수 있어요.","exFr":"Il est honnête, on peut lui faire confiance.","note":"正直. ≠ 정확하다 (exact), 솔직하다 (franc)","conj":"정직해요 · 정직했어요"},"1781435310300":{"ex":"면접 전에 너무 긴장했어요.","exFr":"J'étais très stressé avant l'entretien.","note":"緊張. stress ponctuel avant un événement. ≠ 시장 (marché)","conj":"긴장해요 · 긴장했어요"},"1781435310302":{"ex":"시험 결과 때문에 불안해요.","exFr":"Je suis anxieux à cause des résultats d'examen.","note":"不安. Contraire : 편안하다 (tranquille). 불- (不) = négation","conj":"불안해요 · 불안했어요"},"1781435310298":{"ex":"영화가 재미없어서 좀 실망했어요.","exFr":"Le film était nul, j'ai été un peu déçu.","note":"失望 « perdre l'espoir ». ≠ 실패하다 (échouer)","conj":"실망해요 · 실망했어요"},"1765435504176":{"ex":"회사가 작은 사무실을 임차했어요.","exFr":"L'entreprise a loué un petit bureau.","note":"賃借 = prendre en location ≠ 임대하다 (mettre en location)","conj":"임차해요 · 임차했어요"},"1781435310379":{"ex":"제주도는 자연이 정말 아름다워요.","exFr":"À Jeju, la nature est vraiment magnifique.","note":"自然. 자연스럽다 = naturel. ≠ 자유 (liberté), 자주 (souvent)"},"1781435310338":{"ex":"감기에 걸려서 기침이 나요.","exFr":"J'ai attrapé un rhume, je tousse.","note":"기침이 나다 / 기침을 하다 = tousser. ≠ 아침 (matin)"},"1781435310344":{"ex":"지금 어떤 증상이 있어요?","exFr":"Quels symptômes avez-vous en ce moment ?","note":"症狀. Question type chez le médecin. ≠ 증가 (augmentation)"},"1781435310368":{"ex":"월급에서 세금을 많이 내요.","exFr":"Je paie beaucoup d'impôts sur mon salaire.","note":"稅金. -금 (金) = argent : 현금, 장학금. 세금을 내다 = payer l'impôt"},"1781435310371":{"ex":"한국 역사에 관심이 있어요.","exFr":"Je m'intéresse à l'histoire de la Corée.","note":"歷史. ≠ 역시 (comme prévu). 이야기 = histoire (récit)"},"1781435310365":{"ex":"우리는 환경을 보호해야 해요.","exFr":"Nous devons protéger l'environnement.","note":"環境. ≠ 안경 (lunettes), 환전 (change de devises)"},"1781435310325":{"ex":"그분은 경력이 십 년이에요.","exFr":"Il a dix ans d'expérience professionnelle.","note":"經歷. ≠ 경험 (expérience vécue), 능력 (capacité)"},"1781435310333":{"ex":"이번 학기 성적이 좋아요.","exFr":"Mes notes de ce semestre sont bonnes.","note":"成績. ≠ 성격 (caractère), 성공 (réussite). 成 = accomplir"},"1781435310326":{"ex":"아버지가 올해 부장으로 승진했어요.","exFr":"Mon père a été promu directeur cette année.","note":"昇進 « monter, avancer ». ≠ 사진 (photo), 지진 (séisme)"},"1781435310332":{"ex":"전공이 뭐예요? 저는 역사예요.","exFr":"Ta spécialité ? Moi, c'est histoire.","note":"專攻. 전공하다 = se spécialiser. ≠ 성공 (réussite), 전혀 (pas du tout)"},"1781435310275":{"ex":"미안하지만 그 제안을 거절했어요.","exFr":"Désolé, mais j'ai refusé cette proposition.","note":"拒絶. ≠ 거짓말 (mensonge). Contraire : 받아들이다","conj":"거절해요 · 거절했어요"},"1781435310267":{"ex":"형은 새 사업에 성공했어요.","exFr":"Mon frère a réussi dans sa nouvelle affaire.","note":"成功. ≠ 성격 (caractère), 성적 (notes), 전공 (spécialité)","conj":"성공해요 · 성공했어요"},"1781435310262":{"ex":"어제 한국어 수업을 신청했어요.","exFr":"Hier, je me suis inscrit au cours de coréen.","note":"申請. ≠ 신중하다 (prudent), 신선하다 (frais)","conj":"신청해요 · 신청했어요"},"1781435310357":{"ex":"서울에서 관광을 많이 했어요.","exFr":"J'ai fait beaucoup de tourisme à Séoul.","note":"觀光. ≠ 관심 (intérêt), 관계 (relation)"},"1781435310412":{"ex":"외국 생활은 좋은 경험이에요.","exFr":"La vie à l'étranger est une bonne expérience.","note":"經驗. ≠ 경력 (carrière pro), 경제 (économie)"},"1781435310416":{"ex":"요즘 요리에 관심이 많아요.","exFr":"En ce moment, la cuisine m'intéresse beaucoup.","note":"關心. N에 관심이 있다. ≠ 관계 (relation), 관광 (tourisme)"},"1781435310411":{"ex":"좋은 기회를 놓치지 마세요.","exFr":"Ne ratez pas cette belle occasion.","note":"機會. ≠ 기억 (souvenir), 회의 (réunion)"},"1781435310414":{"ex":"그 사람은 능력이 뛰어나요.","exFr":"Cette personne est très compétente.","note":"能力. ≠ 노력 (effort). -력 (力) = force : 경력, 실력"},"1781435310421":{"ex":"이 집의 단점은 위치예요.","exFr":"Le point faible de cette maison, c'est l'emplacement.","note":"短點 « point court ». Contraire : 장점 (point fort)"},"1781435310409":{"ex":"이번 여행의 목적이 뭐예요?","exFr":"Quel est le but de ce voyage ?","note":"目的. ≠ 목도리 (écharpe), 목 (cou). 목표 = objectif visé"},"1781435310410":{"ex":"더 좋은 방법을 찾았어요.","exFr":"J'ai trouvé une meilleure méthode.","note":"方法. ≠ 방 (chambre), 법 (loi). 요리법 = recette"},"1779641631017":{"ex":"그건 오해예요. 제가 설명할게요.","exFr":"C'est un malentendu. Je vais expliquer.","note":"誤解. ≠ 이해하다 (comprendre). 오해하지 마세요 = ne vous méprenez pas"},"1781435310407":{"ex":"제 의견을 말해도 돼요?","exFr":"Puis-je donner mon avis ?","note":"意見. ≠ 의미 (sens), 의사 (médecin)"},"1781435310419":{"ex":"이 단어의 의미를 몰라요.","exFr":"Je ne connais pas le sens de ce mot.","note":"意味. ≠ 의견 (opinion). Synonyme courant : 뜻"},"1781435310417":{"ex":"발표할 때 자신감이 필요해요.","exFr":"Pour présenter, il faut de la confiance en soi.","note":"自信感. ≠ 자연 (nature). 자신 = soi-même"},"1781435310420":{"ex":"이 휴대폰의 장점은 가격이에요.","exFr":"L'atout de ce téléphone, c'est son prix.","note":"長點. Contraire : 단점. ≠ 장난감 (jouet), 장갑 (gants)"},"1781435310415":{"ex":"두 단어는 의미 차이가 있어요.","exFr":"Ces deux mots ont une différence de sens.","note":"差異. ≠ 차 (thé, voiture), 차라리 (plutôt)"},"1781435310418":{"ex":"그 일은 제 책임이에요.","exFr":"C'est ma responsabilité.","note":"責任. 책임을 지다 = assumer. ≠ 책 (livre)"},"1781435310292":{"ex":"오늘은 설거지하기가 너무 귀찮아요.","exFr":"Aujourd'hui, faire la vaisselle me pèse vraiment.","note":"corvée, flemme. ≠ 귀엽다 (mignon). Prononcé [귀찬타]","conj":"귀찮아요 · 귀찮았어요"},"1781435310295":{"ex":"이 강은 물이 깊어요.","exFr":"Cette rivière est profonde.","note":"aussi figuré : 깊은 의미 (sens profond), 깊은 밤 (nuit avancée)","conj":"깊어요 · 깊었어요"},"1781435310280":{"ex":"이 문제는 생각보다 단순해요.","exFr":"Ce problème est plus simple que prévu.","note":"單純. ≠ 단점 (défaut). Contraire : 복잡하다","conj":"단순해요 · 단순했어요"},"1781435310290":{"ex":"방에 창문이 없어서 답답해요.","exFr":"Sans fenêtre, la chambre est étouffante.","note":"physique (air) ou moral (frustration). ≠ 답 (réponse)","conj":"답답해요 · 답답했어요"},"1781435310294":{"ex":"친구를 돕는 건 당연해요.","exFr":"Aider un ami, c'est normal.","note":"當然. 당연하지! = évidemment ! ≠ 당근 (carotte)","conj":"당연해요 · 당연했어요"},"1781435310279":{"ex":"서울 지하철은 좀 복잡해요.","exFr":"Le métro de Séoul est un peu compliqué.","note":"複雜. aussi : bondé. Contraire : 단순하다","conj":"복잡해요 · 복잡했어요"},"1781435310282":{"ex":"그건 아주 분명한 사실이에요.","exFr":"C'est un fait tout à fait évident.","note":"分明. 분명히 = clairement. ≠ 유명하다 (célèbre)","conj":"분명해요 · 분명했어요"},"1781435310293":{"ex":"가족은 저에게 가장 소중해요.","exFr":"Ma famille est ce que j'ai de plus précieux.","note":"所重. ≠ 신중하다 (prudent)","conj":"소중해요 · 소중했어요"},"1781435310281":{"ex":"지금 상황이 생각보다 심각해요.","exFr":"La situation est plus grave que prévu.","note":"深刻. ≠ 심심하다 (s'ennuyer), 생각하다 (penser)","conj":"심각해요 · 심각했어요"},"1781435310287":{"ex":"주말에는 제 시간이 자유로워요.","exFr":"Le week-end, mon temps est libre.","note":"自由 + -롭다. ㅂ irrég. : 자유로워요. ≠ 자주 (souvent)","conj":"자유로워요 · 자유로웠어요"},"1781435310288":{"ex":"저는 아주 평범한 회사원이에요.","exFr":"Je suis un employé de bureau tout à fait ordinaire.","note":"平凡. Contraire : 특별하다 (spécial)","conj":"평범해요 · 평범했어요"},"1781435310283":{"ex":"내일까지 확실한 답을 주세요.","exFr":"Donnez-moi une réponse sûre d'ici demain.","note":"確實. 확실히 = certainement. ≠ 정확하다 (précis)","conj":"확실해요 · 확실했어요"},"1781435310432":{"ex":"오후에 갑자기 비가 왔어요.","exFr":"L'après-midi, il s'est mis à pleuvoir d'un coup.","note":"≠ 자주 (souvent). Le mot des imprévus"},"1781435310425":{"ex":"날씨가 춥고 게다가 비도 와요.","exFr":"Il fait froid, et en plus il pleut.","note":"ajoute un argument dans le même sens. ≠ 게으르다 (paresseux)"},"1781435310422":{"ex":"피곤해요. 그래도 매일 운동해요.","exFr":"Je suis fatigué. Je fais quand même du sport.","note":"concession. ≠ 그래서 (donc), 그런데 (mais)"},"1781435310423":{"ex":"바빠요? 그러면 내일 만나요.","exFr":"Occupé ? Alors on se voit demain.","note":"si c'est le cas → conséquence. Abrégé : 그럼"},"1781435310424":{"ex":"그런데 지금 몇 시예요?","exFr":"Au fait, quelle heure est-il ?","note":"change de sujet ou oppose. Abrégé : 근데. ≠ 그래서 (donc)"},"1781435310431":{"ex":"시험이 드디어 다 끝났어요!","exFr":"Les examens sont enfin tous finis !","note":"attente enfin récompensée. ≠ 드라마 (série)"},"1781435310427":{"ex":"표가 없어요. 따라서 못 가요.","exFr":"Pas de billet. Par conséquent, on ne peut pas y aller.","note":"registre formel, écrit. ≠ 따로 (séparément), 따라 하다 (imiter)"},"1781435310430":{"ex":"마치 꿈을 꾸는 것 같아요.","exFr":"C'est comme si je rêvais.","note":"toujours avec ~같다 ou ~처럼. ≠ 마침 (justement)"},"1781435310436":{"ex":"만약 비가 오면 집에 있을 거예요.","exFr":"S'il pleut, je resterai à la maison.","note":"萬若. annonce la condition, exige -(으)면 ensuite"},"1781435310426":{"ex":"형은 키가 커요. 반면에 저는 작아요.","exFr":"Mon frère est grand. Moi, en revanche, je suis petit.","note":"反面 « face opposée ». Contraste deux faits"},"1781435310435":{"ex":"아마 내일 도착할 거예요.","exFr":"Ça arrivera probablement demain.","note":"va avec le futur -(으)ㄹ 거예요. ≠ 아직 (pas encore)"},"1781435310434":{"ex":"역시 이 식당이 최고예요.","exFr":"Décidément, ce restaurant est le meilleur.","note":"亦是 « je le savais ». ≠ 역사 (histoire)"},"1781435310433":{"ex":"날씨가 점점 더 추워져요.","exFr":"Il fait de plus en plus froid.","note":"漸漸. souvent avec -아/어지다 (devenir). ≠ 점심 (midi)"},"1781435310428":{"ex":"내일, 즉 금요일에 만나요.","exFr":"On se voit demain, c'est-à-dire vendredi.","note":"卽. reformule. Registre plutôt écrit"},"1781435310437":{"ex":"차라리 집에 있는 게 나아요.","exFr":"Autant rester à la maison, plutôt.","note":"la moins pire de deux options. ≠ 차이 (différence)"},"1781435310429":{"ex":"과일, 특히 사과를 좋아해요.","exFr":"J'aime les fruits, surtout les pommes.","note":"特-. Prononcé [트키]. ≠ 특별하다 (spécial)"},"1781435310319":{"ex":"그건 거짓말이에요. 믿지 마세요.","exFr":"C'est un mensonge. N'y croyez pas.","note":"거짓말하다 = mentir. ≠ 거절하다 (refuser)"},"1781435310311":{"ex":"저는 그 친구를 믿어요.","exFr":"Je fais confiance à cet ami.","note":"croire qqn, faire confiance. 믿음 = confiance, foi","conj":"믿어요 · 믿었어요"},"1781435310309":{"ex":"제 동생은 성격이 밝아요.","exFr":"Ma petite sœur a un caractère enjoué.","note":"性格. ≠ 성적 (notes), 성공 (réussite), 가격 (prix)"},"1781435310315":{"ex":"그 학생은 아주 성실해요.","exFr":"Cet étudiant est très consciencieux.","note":"誠實. ≠ 성공하다 (réussir), 성격 (caractère)","conj":"성실해요 · 성실했어요"},"1781435310318":{"ex":"예의를 지키는 게 중요해요.","exFr":"Respecter la politesse, c'est important.","note":"禮儀. 예의가 없다 = mal élevé. ≠ 예약 (réservation)"},"1781435310317":{"ex":"그 사람은 좀 이기적이에요.","exFr":"Cette personne est un peu égoïste.","note":"利己的 « pour son propre profit ». Contraire : 이타적","conj":"이기적이에요 · 이기적이었어요"},"1781435310320":{"ex":"그는 새 차를 자랑했어요.","exFr":"Il a frimé avec sa nouvelle voiture.","note":"≠ 사랑하다 (aimer). 자랑스럽다 = être fier (positif)","conj":"자랑해요 · 자랑했어요"},"1781435310312":{"ex":"저는 우리 할아버지를 존경해요.","exFr":"J'ai un profond respect pour mon grand-père.","note":"尊敬. ≠ 안경 (lunettes), 환경 (environnement)","conj":"존경해요 · 존경했어요"},"1781435310313":{"ex":"그 학생은 수업 태도가 좋아요.","exFr":"Cet élève a une bonne attitude en cours.","note":"態度. ≠ 태양 (soleil), 태풍 (typhon)"},"1781435310398":{"ex":"저녁에 라면을 끓여서 먹었어요.","exFr":"Le soir, je me suis fait des ramyeon.","note":"물을 끓이다 = faire bouillir l'eau. 끓다 = bouillir (intransitif)","conj":"끓여요 · 끓였어요"},"1781435310403":{"ex":"소스 맛을 좀 보세요.","exFr":"Goûtez un peu la sauce.","note":"litt. « voir le goût ». S'écrit aussi 맛보다","conj":"맛을 봐요 · 맛을 봤어요"},"1781435310397":{"ex":"먼저 야채를 기름에 볶아요.","exFr":"D'abord, faites revenir les légumes dans l'huile.","note":"볶음밥 = riz sauté. ≠ 섞다 (mélanger)","conj":"볶아요 · 볶았어요"},"1781435310401":{"ex":"밥에 야채를 잘 섞어요.","exFr":"Mélangez bien les légumes au riz.","note":"≠ 썰다 (émincer), 볶다 (faire sauter). Prononcé [석따]","conj":"섞어요 · 섞었어요"},"1781435310404":{"ex":"요즘 식욕이 별로 없어요.","exFr":"Ces temps-ci, je n'ai pas trop d'appétit.","note":"食慾. 식 (食) comme 식당, 식사. ≠ 식탁 (table)"},"1781435310402":{"ex":"이 생선은 아주 신선해요.","exFr":"Ce poisson est très frais.","note":"新鮮. pour les aliments ≠ 시원하다 (air frais), 신나다 (excité)","conj":"신선해요 · 신선했어요"},"1781435310400":{"ex":"먼저 양파를 얇게 썰어요.","exFr":"D'abord, émincez finement l'oignon.","note":"≠ 섞다 (mélanger). 썰어 주세요 = coupez-le-moi, svp","conj":"썰어요 · 썰었어요"},"1781435310396":{"ex":"이 양념이 진짜 맛있어요.","exFr":"Cette sauce est vraiment délicieuse.","note":"양념치킨 = poulet frit en sauce. ≠ 양파 (oignon)"},"1781435310405":{"ex":"이 음식은 영양이 많아요.","exFr":"Cet aliment est très nutritif.","note":"營養. ≠ 영향 (influence) — une seule lettre d'écart !"},"1781435310406":{"ex":"인터넷에서 김치찌개 요리법을 찾았어요.","exFr":"J'ai trouvé la recette du kimchi-jjigae sur Internet.","note":"요리 + 법 (méthode). Synonyme : 레시피"},"1781435310395":{"ex":"요리 전에 재료를 준비하세요.","exFr":"Avant de cuisiner, préparez les ingrédients.","note":"材料. ≠ 동료 (collègue), 치료 (soin). Aussi : matériau"},"1781435310399":{"ex":"치킨은 뜨거운 기름에 튀겨요.","exFr":"Le poulet, on le frit dans l'huile chaude.","note":"튀김 = friture, beignet. ≠ 튀다 (rebondir, gicler)","conj":"튀겨요 · 튀겼어요"},"1781435310297":{"ex":"그 영화를 보고 정말 감동했어요.","exFr":"Ce film m'a vraiment ému.","note":"感動 « cœur mis en mouvement ». 감동적이다 = émouvant","conj":"감동해요 · 감동했어요"},"1781435310307":{"ex":"저는 실패하는 게 두려워요.","exFr":"J'ai peur d'échouer.","note":"peur profonde ≠ 무섭다 (peur concrète). ㅂ irrég. : 두려워요","conj":"두려워요 · 두려웠어요"},"1781435310305":{"ex":"저는 결과에 아주 만족해요.","exFr":"Je suis très satisfait du résultat.","note":"滿足. N에 만족하다. ≠ 부족하다 (manquer)","conj":"만족해요 · 만족했어요"},"1781435310301":{"ex":"너무 비싼 선물은 부담스러워요.","exFr":"Un cadeau trop cher, ça met mal à l'aise.","note":"負擔 = fardeau. ≠ 부럽다 (envieux), 부끄럽다 (gêné)","conj":"부담스러워요 · 부담스러웠어요"},"1781435310304":{"ex":"너무 부러워요! 저도 가고 싶어요.","exFr":"Je t'envie ! Moi aussi je veux y aller.","note":"envie sans hostilité ≠ 부끄럽다 (gêné). 질투 = jalousie","conj":"부러워요 · 부러웠어요"},"1781435310308":{"ex":"엄마 연락을 받고 안심했어요.","exFr":"Le message de maman m'a rassuré.","note":"安心 « cœur en paix ». ≠ 조심하다 (faire attention)","conj":"안심해요 · 안심했어요"},"1781435310306":{"ex":"오늘 수업은 길고 지루했어요.","exFr":"Le cours d'aujourd'hui était long et ennuyeux.","note":"une chose est 지루하다 ; une personne s'ennuie : 심심하다","conj":"지루해요 · 지루했어요"},"1781435310299":{"ex":"버스를 또 놓쳐서 짜증나요.","exFr":"J'ai encore raté le bus, ça m'énerve.","note":"≠ 짜다 (salé). 짜증 = agacement","conj":"짜증나요 · 짜증났어요"},"1781435310303":{"ex":"이 소파는 정말 편안해요.","exFr":"Ce canapé est vraiment confortable.","note":"便安. Contraire : 불안하다 (anxieux). 편하다 = pratique","conj":"편안해요 · 편안했어요"},"1765435572463":{"ex":"주인이 학생들에게 방을 임대해요.","exFr":"Le propriétaire loue des chambres aux étudiants.","note":"賃貸 = mettre en location ≠ 임차하다 (prendre en location)","conj":"임대해요 · 임대했어요"},"1781435310386":{"ex":"주말에 한강에서 자전거를 타요.","exFr":"Le week-end, je fais du vélo au bord du fleuve Han.","note":"江. 한강 = le fleuve Han. ≠ 강아지 (chiot)"},"1781435310389":{"ex":"산 공기가 맑고 좋아요.","exFr":"L'air de la montagne est pur et agréable.","note":"空氣. ≠ 고기 (viande). 공기밥 = bol de riz !"},"1781435310391":{"ex":"제주도는 기후가 아주 따뜻해요.","exFr":"Le climat de Jeju est très doux.","note":"氣候. durable ≠ 날씨 (météo du jour). ≠ 기분 (humeur)"},"1781435310387":{"ex":"마당에 큰 나무가 있어요.","exFr":"Il y a un grand arbre dans la cour.","note":"aussi : bois (matériau). 나무젓가락 = baguettes en bois"},"1781435310382":{"ex":"오늘 밤 달이 정말 밝아요.","exFr":"Ce soir, la lune est vraiment claire.","note":"aussi : mois (한 달 = un mois). ≠ 달다 (sucré)"},"1781435310388":{"ex":"이 길에는 돌이 많아요.","exFr":"Il y a beaucoup de pierres sur ce chemin.","note":"돌 = aussi le 1er anniversaire d'un bébé (돌잔치)"},"1781435310385":{"ex":"여름마다 가족과 바다에 가요.","exFr":"Chaque été, je vais à la mer en famille.","note":"≠ 바닥 (sol), 바라다 (souhaiter). 바닷가 = plage"},"1781435310381":{"ex":"시골에서는 별이 잘 보여요.","exFr":"À la campagne, on voit bien les étoiles.","note":"≠ 별로 (pas vraiment). 별명 = surnom"},"1781435310384":{"ex":"지난 주말에 산에 올라갔어요.","exFr":"Le week-end dernier, j'ai gravi la montagne.","note":"山. 등산 = randonnée. ≠ 산책 (promenade)"},"1781435310390":{"ex":"요즘 공기 오염이 심해요.","exFr":"En ce moment, la pollution de l'air est grave.","note":"汚染. 환경 오염 = pollution de l'environnement. ≠ 오해 (malentendu)"},"1781435310394":{"ex":"저는 아침마다 일기예보를 확인해요.","exFr":"Je vérifie la météo tous les matins.","note":"日氣豫報. Attention : 일기 = aussi journal intime !"},"1781435310392":{"ex":"어제 작은 지진이 났어요.","exFr":"Hier, il y a eu un petit séisme.","note":"地震. 지 (地) = terre. ≠ 사진 (photo), 승진 (promotion)"},"1781435310383":{"ex":"태양이 구름 뒤에 있어요.","exFr":"Le soleil est derrière les nuages.","note":"太陽. Mot courant : 해. ≠ 태풍 (typhon), 태도 (attitude)"},"1781435310393":{"ex":"태풍 때문에 비행기가 취소됐어요.","exFr":"Le vol a été annulé à cause du typhon.","note":"颱風. 풍 (風) = vent. ≠ 태양 (soleil)"},"1781435310380":{"ex":"가을 하늘이 정말 파래요.","exFr":"Le ciel d'automne est vraiment bleu.","note":"≠ 하늘색 (bleu ciel), 하나 (un). 하늘나라 = paradis"},"1781435310336":{"ex":"건강이 돈보다 더 중요해요.","exFr":"La santé est plus importante que l'argent.","note":"健康. 건강하세요! = portez-vous bien !"},"1781435310349":{"ex":"감기가 이제 다 나았어요.","exFr":"Mon rhume est maintenant complètement guéri.","note":"ㅅ irrég. : 나아요, 나았어요. Aussi : être mieux (A가 낫다)","conj":"나아요 · 나았어요"},"1781435310337":{"ex":"축구를 하다가 다리를 다쳤어요.","exFr":"Je me suis blessé à la jambe en jouant au foot.","note":"≠ 다르다 (différent), 가르치다 (enseigner)","conj":"다쳐요 · 다쳤어요"},"1781435310343":{"ex":"운동으로 살을 많이 뺐어요.","exFr":"J'ai perdu beaucoup de poids grâce au sport.","note":"litt. « retirer la chair ». Contraire : 살이 찌다","conj":"살을 빼요 · 살을 뺐어요"},"1781435310342":{"ex":"겨울 동안 살이 좀 쪘어요.","exFr":"J'ai pris un peu de poids pendant l'hiver.","note":"살 = chair. Contraire : 살을 빼다 (maigrir)","conj":"살이 쪄요 · 살이 쪘어요"},"1781435310340":{"ex":"갑자기 일어나면 좀 어지러워요.","exFr":"Quand je me lève d'un coup, j'ai le vertige.","note":"≠ 어렵다 (difficile), 어둡다 (sombre). ㅂ irrég.","conj":"어지러워요 · 어지러웠어요"},"1781435310339":{"ex":"아이가 어젯밤부터 열이 나요.","exFr":"L'enfant a de la fièvre depuis hier soir.","note":"열 (熱) = chaleur, fièvre — le même 열 que 열심히 !","conj":"열이 나요 · 열이 났어요"},"1781435310346":{"ex":"할머니가 지난주에 병원에 입원하셨어요.","exFr":"Ma grand-mère a été hospitalisée la semaine dernière.","note":"入院 « entrer à l'hôpital ». Contraire : 퇴원하다","conj":"입원해요 · 입원했어요"},"1781435310348":{"ex":"의사 선생님이 처방전을 줬어요.","exFr":"Le médecin m'a donné une ordonnance.","note":"處方箋. Ensuite direction 약국 (pharmacie). ≠ 사전 (dictionnaire)"},"1781435310347":{"ex":"이가 아파서 치과에 갔어요.","exFr":"J'avais mal aux dents, je suis allé chez le dentiste.","note":"齒科 « section dents ». ≠ 치료 (soin), 사과 (pomme)"},"1781435310345":{"ex":"병원에서 치료를 잘 받았어요.","exFr":"J'ai été bien soigné à l'hôpital.","note":"治療. 치료를 받다 = se faire soigner. ≠ 치과 (dentiste)","conj":"치료해요 · 치료했어요"},"1781435310341":{"ex":"속이 안 좋아서 토했어요.","exFr":"J'avais mal au cœur, j'ai vomi.","note":"속이 안 좋다 = avoir mal au cœur. ≠ 토요일 (samedi)","conj":"토해요 · 토했어요"},"1781435310372":{"ex":"요즘 경제가 아주 어려워요.","exFr":"En ce moment, l'économie va très mal.","note":"經濟. ≠ 경험 (expérience), 경력 (carrière)"},"1781435310374":{"ex":"저는 아침마다 뉴스를 봐요.","exFr":"Je regarde les infos tous les matins.","note":"de l'anglais news. 신문 = journal papier"},"1781435310370":{"ex":"두 나라는 문화가 달라요.","exFr":"Les deux pays ont des cultures différentes.","note":"文化. ≠ 문제 (problème), 문 (porte)"},"1781435310367":{"ex":"모든 사람은 법을 지켜야 해요.","exFr":"Tout le monde doit respecter la loi.","note":"法. Le même 법 que dans 방법 (méthode), 요리법 (recette)"},"1781435310375":{"ex":"어젯밤에 큰 사건이 있었어요.","exFr":"Il y a eu une grosse affaire hier soir.","note":"事件. ≠ 사고 (accident), 사진 (photo). Fréquent aux infos"},"1781435310364":{"ex":"우리 사회에는 문제가 많아요.","exFr":"Notre société a beaucoup de problèmes.","note":"社會. ≠ 회사 (entreprise) — syllabes inversées !"},"1781435310378":{"ex":"날씨가 기분에 영향을 줘요.","exFr":"La météo influence l'humeur.","note":"影響. 영향을 주다/받다. ≠ 영양 (nutrition) !"},"1781435310369":{"ex":"서울은 인구가 아주 많아요.","exFr":"Séoul a une très grande population.","note":"人口 « bouches humaines ». ≠ 인기 (popularité), 입구 (entrée)"},"1781435310366":{"ex":"정부가 새 법을 만들었어요.","exFr":"Le gouvernement a créé une nouvelle loi.","note":"政府. ≠ 정치 (politique), 부자 (riche)"},"1781435310373":{"ex":"아버지는 정치에 관심이 많아요.","exFr":"Mon père s'intéresse beaucoup à la politique.","note":"政治. ≠ 정부 (gouvernement), 정리 (rangement)"},"1781435310377":{"ex":"주말에 봉사 활동에 참여했어요.","exFr":"Ce week-end, j'ai participé à du bénévolat.","note":"參與. N에 참여하다. ≠ 참다 (endurer)","conj":"참여해요 · 참여했어요"},"1781435310376":{"ex":"우리는 문제를 빨리 해결했어요.","exFr":"Nous avons vite résolu le problème.","note":"解決. ≠ 결정하다 (décider). 해결책 = solution","conj":"해결해요 · 해결했어요"},"1781435310331":{"ex":"회사 동료와 점심을 먹어요.","exFr":"Je déjeune avec un collègue de travail.","note":"同僚. 동 (同) = même. ≠ 재료 (ingrédient), 치료 (soin)"},"1781435310324":{"ex":"내일 회사 면접이 있어요.","exFr":"J'ai un entretien d'embauche demain.","note":"面接. 면접을 보다 = passer un entretien"},"1781435310321":{"ex":"오늘 회의에서 발표를 했어요.","exFr":"J'ai fait une présentation à la réunion.","note":"發表. 발표하다 = présenter, annoncer. ≠ 표 (billet)"},"1781435310322":{"ex":"보고서를 금요일까지 내야 해요.","exFr":"Je dois rendre le rapport avant vendredi.","note":"報告書. -서 (書) = écrit : 신청서, 계획서"},"1781435310323":{"ex":"필요한 서류를 준비해서 보냈어요.","exFr":"J'ai préparé et envoyé les documents demandés.","note":"書類. ≠ 서점 (librairie), 종류 (sorte)"},"1781435310327":{"ex":"이번 주에 야근을 많이 했어요.","exFr":"Cette semaine, j'ai fait beaucoup d'heures sup.","note":"夜勤 « travail de nuit ». ≠ 출근 (aller au travail)"},"1781435310334":{"ex":"성적이 좋아서 장학금을 받았어요.","exFr":"J'ai eu une bourse grâce à mes bonnes notes.","note":"奬學金. -금 = argent : 세금, 현금. ≠ 장갑 (gants)"},"1781435310335":{"ex":"저는 내년에 대학교를 졸업해요.","exFr":"Je finis l'université l'année prochaine.","note":"卒業. Contraire : 입학하다 (entrer à l'école)","conj":"졸업해요 · 졸업했어요"},"1781435310328":{"ex":"매일 여덟 시에 출근해요.","exFr":"Je vais au travail tous les jours à 8 h.","note":"出勤. Contraire : 퇴근하다. ≠ 출발하다 (partir)","conj":"출근해요 · 출근했어요"},"1781435310329":{"ex":"보통 여섯 시에 퇴근해요.","exFr":"D'habitude, je quitte le travail à 18 h.","note":"退勤. 퇴 (退) = se retirer : 퇴원 (quitter l'hôpital)","conj":"퇴근해요 · 퇴근했어요"},"1781435310330":{"ex":"다음 주에 휴가를 가요.","exFr":"Je pars en congé la semaine prochaine.","note":"休暇. 휴 (休) = repos : 휴일, 휴게소. ≠ 휴지 (mouchoir)"},"1781435310259":{"ex":"한국에 유학을 가기로 결정했어요.","exFr":"J'ai décidé de partir étudier en Corée.","note":"決定. -기로 결정하다 = décider de. ≠ 걱정하다 (s'inquiéter)","conj":"결정해요 · 결정했어요"},"1781435310278":{"ex":"뭘 살지 고민하고 있어요.","exFr":"J'hésite sur quoi acheter.","note":"苦悶. réflexion qui tracasse. ≠ 고향 (ville natale)","conj":"고민해요 · 고민했어요"},"1781435310270":{"ex":"한국어 실력이 많이 늘었어요.","exFr":"Mon niveau de coréen a beaucoup progressé.","note":"≠ 줄다 (diminuer). 늘 = aussi « toujours »","conj":"늘어요 · 늘었어요"},"1781435310269":{"ex":"제 전화번호가 최근에 바뀌었어요.","exFr":"Mon numéro de téléphone a changé récemment.","note":"passif de 바꾸다 (changer qqch). ≠ 바쁘다 (occupé)","conj":"바뀌어요 · 바뀌었어요"},"1781435310272":{"ex":"한국 경제는 아주 빨리 발전했어요.","exFr":"L'économie coréenne s'est développée très vite.","note":"發展. ≠ 발표하다 (présenter), 출발 (départ)","conj":"발전해요 · 발전했어요"},"1781435310277":{"ex":"그는 음식에 대해 불평했어요.","exFr":"Il s'est plaint de la nourriture.","note":"不平. ≠ 불안하다 (anxieux). 불- (不) = négation","conj":"불평해요 · 불평했어요"},"1781435310273":{"ex":"가격을 잘 비교하고 샀어요.","exFr":"J'ai bien comparé les prix avant d'acheter.","note":"比較. A와 B를 비교하다. ≠ 비싸다 (cher)","conj":"비교해요 · 비교했어요"},"1781435310260":{"ex":"선생님이 문법을 쉽게 설명해요.","exFr":"Le professeur explique la grammaire simplement.","note":"說明. ≠ 설거지 (vaisselle), 유명하다 (célèbre)","conj":"설명해요 · 설명했어요"},"1781435310276":{"ex":"그 사람이 저를 속였어요.","exFr":"Cette personne m'a trompé.","note":"≠ 속 (intérieur, ventre). 속임수 = tromperie","conj":"속여요 · 속였어요"},"1781435310263":{"ex":"남의 말에 신경 쓰지 마세요.","exFr":"Ne faites pas attention à ce que disent les gens.","note":"神經 = nerfs, litt. « user ses nerfs ». ≠ 신청하다 (s'inscrire)","conj":"신경 써요 · 신경 썼어요"},"1781435310268":{"ex":"한 번 실패해도 괜찮아요.","exFr":"Échouer une fois, ce n'est pas grave.","note":"失敗. ≠ 실망하다 (être déçu). Contraire : 성공하다","conj":"실패해요 · 실패했어요"},"1781435310271":{"ex":"요즘 손님이 많이 줄었어요.","exFr":"Ces temps-ci, la clientèle a beaucoup baissé.","note":"≠ 늘다 (augmenter). 줄이다 = réduire (transitif)","conj":"줄어요 · 줄었어요"},"1781435310264":{"ex":"저는 아파도 참고 일했어요.","exFr":"Même malade, j'ai tenu bon au travail.","note":"≠ 참여하다 (participer). 참을 수 없다 = insupportable","conj":"참아요 · 참았어요"},"1781435310274":{"ex":"맛있는 식당을 추천해 주세요.","exFr":"Recommandez-moi un bon restaurant.","note":"推薦. 추천 = recommandation. ≠ 축하하다 (féliciter)","conj":"추천해요 · 추천했어요"},"1781435310266":{"ex":"힘들어도 끝까지 포기하지 마세요.","exFr":"Même si c'est dur, n'abandonnez pas.","note":"抛棄. ≠ 포도 (raisin). 포기하지 마! = lâche pas !","conj":"포기해요 · 포기했어요"},"1781435310261":{"ex":"감정을 말로 표현하기 어려워요.","exFr":"C'est dur d'exprimer ses émotions par des mots.","note":"表現. 표현 = expression. ≠ 표 (billet), 발표 (exposé)","conj":"표현해요 · 표현했어요"},"1781435310265":{"ex":"공부 안 한 것을 후회해요.","exFr":"Je regrette de ne pas avoir étudié.","note":"後悔 « remords après coup ». ≠ 아쉽다 (dommage, plus léger)","conj":"후회해요 · 후회했어요"},"1763266415792":{"ex":"친구가 소개팅을 해 줬어요.","exFr":"Un ami m'a arrangé un rendez-vous.","note":"소개 (présentation) + -팅 (meeting). Institution coréenne !"},"1781435310353":{"ex":"공항에 두 시간 전에 도착하세요.","exFr":"Arrivez à l'aéroport deux heures avant.","note":"空港 « port du ciel ». ≠ 공원 (parc), 고향 (ville natale)"},"1781435310358":{"ex":"여행 중에 길을 잃었어요.","exFr":"Je me suis perdu pendant le voyage.","note":"잃다 = perdre. Renforcé : 길을 잃어버렸어요","conj":"길을 잃어요 · 길을 잃었어요"},"1781435310352":{"ex":"도착 시간이 몇 시예요?","exFr":"À quelle heure est l'arrivée ?","note":"到着. 도착하다 = arriver. Contraire : 출발 (départ)"},"1781435310359":{"ex":"퇴근 시간에는 길이 막혀요.","exFr":"Aux heures de pointe, ça bouchonne.","note":"passif de 막다 (boucher). 코가 막히다 = nez bouché","conj":"막혀요 · 막혔어요"},"1781435310362":{"ex":"어제 고속도로에서 사고가 났어요.","exFr":"Hier, il y a eu un accident sur l'autoroute.","note":"事故. 사고가 나다 = un accident survient. ≠ 사건 (affaire)"},"1781435310356":{"ex":"여행 숙소를 미리 예약했어요.","exFr":"J'ai réservé l'hébergement du voyage à l'avance.","note":"宿所. 숙 (宿) = dormir : 기숙사 (dortoir). ≠ 채소 (légume)"},"1781435310355":{"ex":"어제 공항에서 여권을 잃어버렸어요.","exFr":"Hier, j'ai perdu mon passeport à l'aéroport.","note":"旅券. 여 (旅) = voyage, comme 여행. ≠ 여름 (été)"},"1781435310350":{"ex":"호텔 예약을 벌써 했어요.","exFr":"J'ai déjà fait la réservation d'hôtel.","note":"豫約. hôtel, resto ≠ 예매 (billets de spectacle, train)"},"1781435310360":{"ex":"밤에 운전하는 게 힘들어요.","exFr":"Conduire de nuit, c'est fatigant.","note":"運轉. 운전사 = chauffeur. ≠ 운동하다 (faire du sport)","conj":"운전해요 · 운전했어요"},"1781435310361":{"ex":"이 앞에 주차해도 돼요?","exFr":"Je peux me garer juste devant ?","note":"駐車. 주차장 = parking. ≠ 주문하다 (commander)","conj":"주차해요 · 주차했어요"},"1781435310354":{"ex":"여행 짐이 너무 무거워요.","exFr":"Mes bagages de voyage sont trop lourds.","note":"짐을 싸다 = faire ses valises ; 짐을 풀다 = les défaire"},"1781435310351":{"ex":"기차 출발 시간을 확인하세요.","exFr":"Vérifiez l'heure de départ du train.","note":"出發. Contraire : 도착. ≠ 출구 (sortie), 출근 (aller bosser)"},"1781435310363":{"ex":"호텔 예약을 취소하고 싶어요.","exFr":"Je voudrais annuler ma réservation d'hôtel.","note":"取消. ≠ 청소하다 (nettoyer), 숙소 (hébergement)","conj":"취소해요 · 취소했어요"},"1763266194551":{"ex":"이 가방은 가격이 얼마예요?","exFr":"Quel est le prix de ce sac ?","note":"價格. ≠ 성격 (caractère), 가족 (famille). Syn. : 값"},"1779706066057":{"ex":"가게 아저씨가 거스름돈을 줬어요.","exFr":"Le commerçant m'a rendu la monnaie.","note":"거스름돈 = monnaie rendue. 잔돈 = petite monnaie","conj":"거스름돈을 줘요 · 거스름돈을 줬어요"},"1779706066054":{"ex":"더 큰 사이즈 있어요?","exFr":"Vous avez une taille au-dessus ?","note":"anglais size (vêtements). 크기 = taille d'un objet"},"1779706066058":{"ex":"이거 주세요. 모두 얼마예요?","exFr":"Je prends ça. Ça fait combien en tout ?","note":"이거 = 이것 (ceci) à l'oral. Phrase de survie n°1"},"1764055523116":{"ex":"우리 집에서 역까지 아주 가까워요.","exFr":"De chez moi, la gare est toute proche.","note":"ㅂ irrég. : 가까워요. ≠ 가끔 (parfois), 가격 (prix)","conj":"가까워요 · 가까웠어요"},"1779706066134":{"ex":"거짓말은 아주 나쁜 습관이에요.","exFr":"Mentir est une très mauvaise habitude.","note":"ㅡ irrég. : 나빠요. ≠ 바쁘다 (occupé) — n/b !","conj":"나빠요 · 나빴어요"},"1779706066144":{"ex":"요즘 일 때문에 너무 바빠요.","exFr":"En ce moment, le travail me déborde.","note":"ㅡ irrég. : 바빠요. ≠ 나쁘다 (mauvais), 바다 (mer)","conj":"바빠요 · 바빴어요"},"1779706066143":{"ex":"한국어 문법은 좀 어려워요.","exFr":"La grammaire coréenne est un peu difficile.","note":"ㅂ irrég. : 어려워요. ≠ 어둡다 (sombre), 어리다 (jeune)","conj":"어려워요 · 어려웠어요"},"1763265629924":{"ex":"이 우유 맛이 좀 이상해요.","exFr":"Ce lait a un goût un peu bizarre.","note":"異常. ≠ 이상 (plus de : 10개 이상). 이상형 = type idéal","conj":"이상해요 · 이상했어요"},"1780695436453":{"ex":"숙제를 거의 다 했어요.","exFr":"J'ai presque fini mes devoirs.","note":"거의 다 = presque tout. ≠ 거리 (rue), 거기 (là-bas)"},"1780695436456":{"ex":"이 김치는 아주 매워요.","exFr":"Ce kimchi est très épicé.","note":"≠ 자주 (souvent) ! Syn. : 매우, 정말"},"1780695436462":{"ex":"내일은 일찍 일어나야 해요.","exFr":"Demain, je dois me lever tôt.","note":"Contraire : 늦게 (tard). ≠ 일 (travail, un)"},"1780695436451":{"ex":"저는 카페에 자주 가요.","exFr":"Je vais souvent au café.","note":"fréquence ≠ 아주 (très, intensité)"},"1763264604617":{"ex":"제주도 경치가 정말 아름다워요.","exFr":"Les paysages de Jeju sont vraiment magnifiques.","note":"ㅂ irrég. : 아름다워요. Plus littéraire que 예쁘다","conj":"아름다워요 · 아름다웠어요"},"1763264129866":{"ex":"그 원피스 정말 예뻐요.","exFr":"Cette robe est vraiment jolie.","note":"ㅡ irrég. : 예뻐요. ≠ 예의 (politesse), 예약 (réservation)","conj":"예뻐요 · 예뻤어요"},"1779706066155":{"ex":"밥 먹고 그다음에 뭐 해요?","exFr":"Après manger, on fait quoi ensuite ?","note":"그 + 다음 (suivant) + 에. Enchaîne les étapes"},"1779706066150":{"ex":"비가 와요. 그래서 집에 있어요.","exFr":"Il pleut. Donc je reste à la maison.","note":"cause → conséquence. ≠ 그런데 (mais), 그래도 (quand même)"},"1779706066151":{"ex":"빵하고 우유, 그리고 과일을 샀어요.","exFr":"J'ai acheté du pain, du lait, et puis des fruits.","note":"relie noms et phrases. ≠ 그래서 (donc), 그립다 (manquer)"},"1779706066157":{"ex":"오늘 날씨가 정말 좋아요.","exFr":"Il fait vraiment beau aujourd'hui.","note":"≠ 정리 (rangement), 정류장 (arrêt). Familier : 진짜"},"1779706066148":{"ex":"주말에 친구하고 영화를 봤어요.","exFr":"Ce week-end, j'ai vu un film avec un ami.","note":"s'attache au nom (빵하고 우유). ≠ 하지만 (mais)"},"1779706066149":{"ex":"피곤해요. 하지만 공부해야 해요.","exFr":"Je suis fatigué. Mais je dois étudier.","note":"en début de phrase. ≠ 하고 (et). Syn. : 그렇지만"},"1779706066099":{"ex":"어제부터 머리가 너무 아파요.","exFr":"J'ai très mal à la tête depuis hier.","note":"ㅡ irrég. : 아파요. ≠ 아파트 (appartement). X가 아프다 = avoir mal à X","conj":"아파요 · 아팠어요"},"1780695436485":{"ex":"어깨가 아파서 병원에 갔어요.","exFr":"J'avais mal à l'épaule, je suis allé à l'hôpital.","note":"≠ 어제 (hier), 아까 (tout à l'heure)"},"1780695436493":{"ex":"이가 아파서 치과에 가요.","exFr":"J'ai mal aux dents, je vais chez le dentiste.","note":"이 = dent / deux / ceci — le contexte décide. Médical : 치아"},"1779706066102":{"ex":"어제 너무 늦게 잤어요.","exFr":"Hier, je me suis couché très tard.","note":"≠ 자주 (souvent), 사다 (acheter). 잘 자요 = bonne nuit","conj":"자요 · 잤어요"},"1780695436531":{"ex":"실례지만 나이가 어떻게 되세요?","exFr":"Excusez-moi, quel âge avez-vous ?","note":"très poli : 연세. ≠ 나 (moi), 아이 (enfant)"},"1780695436532":{"ex":"지금 교실에 사람이 많아요.","exFr":"Il y a beaucoup de monde dans la classe.","note":"≠ 사랑 (amour) — ㅁ vs ㅇ final ! 한국 사람 = un Coréen"},"1780695436530":{"ex":"이름을 여기에 써 주세요.","exFr":"Écrivez votre nom ici, s'il vous plaît.","note":"poli : 성함. ≠ 이유 (raison), 여름 (été)"},"1780695436537":{"ex":"오늘 재미있는 이야기를 들었어요.","exFr":"J'ai entendu une histoire intéressante aujourd'hui.","note":"이야기하다 = discuter. Abrégé : 얘기. ≠ 역사 (l'Histoire)"},"1763266121495":{"ex":"우리 이웃은 아주 친절해요.","exFr":"Nos voisins sont très aimables.","note":"≠ 이유 (raison), 이 (dent, deux). 이웃집 = maison d'à côté"},"1779642569309":{"ex":"학교에 늦은 이유가 뭐예요?","exFr":"Quelle est la raison de ton retard à l'école ?","note":"理由. ≠ 이웃 (voisin), 우유 (lait)"},"1779641148809":{"ex":"오늘 기분이 아주 좋아요.","exFr":"Aujourd'hui, je suis de très bonne humeur.","note":"氣分. ≠ 기억 (souvenir), 부분 (partie)"},"1780695436399":{"ex":"그 말을 듣고 기분이 나빴어요.","exFr":"En entendant ça, ça m'a vexé.","note":"aussi : être vexé, pas seulement de mauvaise humeur","conj":"기분이 나빠요 · 기분이 나빴어요"},"1780695436398":{"ex":"선물을 받아서 기분이 좋아요.","exFr":"J'ai reçu un cadeau, je suis content.","note":"état du moment ; 행복하다 = bonheur plus profond","conj":"기분이 좋아요 · 기분이 좋았어요"},"1780695436386":{"ex":"합격 소식에 정말 기뻤어요.","exFr":"La nouvelle de ma réussite m'a rempli de joie.","note":"ㅡ irrég. : 기뻐요. ≠ 예쁘다 (joli), 바쁘다 (occupé)","conj":"기뻐요 · 기뻤어요"},"1780695436395":{"ex":"실수를 해서 너무 부끄러웠어요.","exFr":"J'avais tellement honte de mon erreur.","note":"≠ 부럽다 (envieux) ! ㅂ irrég. : 부끄러워요","conj":"부끄러워요 · 부끄러웠어요"},"1780695436397":{"ex":"저는 우리 가족을 정말 사랑해요.","exFr":"J'aime vraiment ma famille.","note":"≠ 사람 (personne). 좋아하다 = aimer bien (moins fort)","conj":"사랑해요 · 사랑했어요"},"1779706066025":{"ex":"이 가게는 과일이 싸요.","exFr":"Dans ce magasin, les fruits sont bon marché.","note":"≠ 가격 (prix), 가께 n'existe pas. Grande surface : 마트"},"1779706066027":{"ex":"이 거리에는 카페가 많아요.","exFr":"Dans cette rue, il y a beaucoup de cafés.","note":"≠ 거실 (salon), 다리 (jambe, pont). Aussi : distance"},"1779706066026":{"ex":"일요일에는 공원에서 책을 읽어요.","exFr":"Le dimanche, je lis au parc.","note":"公園. ≠ 공무원 (fonctionnaire), 병원 (hôpital), 학원 (académie)"},"1779706066030":{"ex":"제 사무실은 5층에 있어요.","exFr":"Mon bureau est au 5e étage.","note":"事務室. -실 (室) = salle : 교실, 화장실"},"1779706066023":{"ex":"오늘 시장에서 채소를 샀어요.","exFr":"J'ai acheté des légumes au marché aujourd'hui.","note":"市場. ≠ 시내 (centre-ville), 사장 (patron). Aussi : maire !"},"1779706066029":{"ex":"저는 아파트 10층에 살아요.","exFr":"J'habite au 10e étage d'un immeuble.","note":"= grand immeuble résidentiel coréen. ≠ 아프다 (avoir mal)"},"1779724539695":{"ex":"여행 사진을 많이 찍었어요.","exFr":"J'ai pris beaucoup de photos de voyage.","note":"寫眞. 사진을 찍다 = prendre une photo. ≠ 사전 (dictionnaire)"},"1765226841713":{"ex":"오늘 기온이 많이 내려갔어요.","exFr":"La température a beaucoup baissé aujourd'hui.","note":"氣溫. météo ≠ 체온 (température du corps). ≠ 기분 (humeur)"},"1779706066107":{"ex":"오늘은 바람이 많이 불어요.","exFr":"Aujourd'hui, il y a beaucoup de vent.","note":"바람이 불다 = le vent souffle. ≠ 바다 (mer), 사람 (personne)"},"1764051184975":{"ex":"그 배우는 연기를 잘해요.","exFr":"Cet acteur joue très bien.","note":"俳優. ≠ 배우다 (apprendre) ! 배 = ventre, poire, bateau"},"1780695436476":{"ex":"오늘 아무것도 안 먹었어요.","exFr":"Je n'ai rien mangé aujourd'hui.","note":"toujours avec négation. ≠ 아무도 (personne)"},"1780695436477":{"ex":"지금 교실에 아무도 없어요.","exFr":"Il n'y a personne dans la classe.","note":"toujours + négation. ≠ 아무것도 (rien), 아무나 (n'importe qui)"},"1780695436478":{"ex":"숙제를 아직 안 했어요.","exFr":"Je n'ai pas encore fait mes devoirs.","note":"≠ 벌써 (déjà), 이제 (maintenant). 아직도 = toujours pas"},"1779706066034":{"ex":"서울에서 부산까지 기차로 갔어요.","exFr":"Je suis allé de Séoul à Busan en train.","note":"汽車. ≠ 자동차 (voiture), 기자 (journaliste). KTX = TGV coréen"},"1779706066037":{"ex":"지난달에 새 자동차를 샀어요.","exFr":"Le mois dernier, j'ai acheté une nouvelle voiture.","note":"自動車 « véhicule qui bouge seul ». Abrégé : 차"},"1779706066036":{"ex":"주말마다 공원에서 자전거를 타요.","exFr":"Chaque week-end, je fais du vélo au parc.","note":"自轉車. 타다 = prendre (un véhicule). ≠ 자동차 (voiture)"},"1763264301220":{"ex":"버스 정류장에서 친구를 기다려요.","exFr":"J'attends un ami à l'arrêt de bus.","note":"停留場. ≠ 정리하다 (ranger). Pour le métro : 역"},"1779724539685":{"ex":"사장님은 지금 회의 중이에요.","exFr":"Le patron est en réunion en ce moment.","note":"社長 + 님. ≠ 시장 (marché, maire), 사진 (photo)"},"1779706066114":{"ex":"저는 지금 학교에 가요.","exFr":"Je vais à l'école maintenant.","note":"≠ 오다 (venir). 가져가다 = emporter, 돌아가다 = retourner","conj":"가요 · 갔어요"},"1779706066126":{"ex":"저는 친구에게 한국어를 가르쳐요.","exFr":"J'enseigne le coréen à un ami.","note":"≠ 가리키다 (montrer du doigt), 배우다 (apprendre)","conj":"가르쳐요 · 가르쳤어요"},"1780695436527":{"ex":"내일 그 책을 가져오세요.","exFr":"Apportez ce livre demain.","note":"가지다 + 오다 (venir) ≠ 가져가다 (emporter, avec 가다)","conj":"가져와요 · 가져왔어요"},"1763265381578":{"ex":"도서관에서 세 시간 공부했어요.","exFr":"J'ai étudié trois heures à la bibliothèque.","note":"工夫. ≠ 공무원 (fonctionnaire), 공기 (air)"},"1764057806881":{"ex":"저는 그날을 아직 기억해요.","exFr":"Je me souviens encore de ce jour-là.","note":"記憶. ≠ 기다리다 (attendre). 기억이 안 나요 = ça ne me revient pas","conj":"기억해요 · 기억했어요"},"1779706066121":{"ex":"하루에 물을 많이 마시세요.","exFr":"Buvez beaucoup d'eau dans la journée.","note":"≠ 마르다 (être maigre), 마치 (comme si)","conj":"마셔요 · 마셨어요"},"1764056487960":{"ex":"백화점에서 새 가방을 샀어요.","exFr":"J'ai acheté un nouveau sac au grand magasin.","note":"≠ 싸다 (bon marché) ! 사요 (j'achète) vs 싸요 (c'est pas cher)","conj":"사요 · 샀어요"},"1763264479929":{"ex":"여름마다 바다에서 수영을 해요.","exFr":"Chaque été, je nage dans la mer.","note":"水泳. 수영장 = piscine. ≠ 수업 (cours), 수요일 (mercredi)","conj":"수영해요 · 수영했어요"},"1779706066132":{"ex":"수업이 아홉 시에 시작해요.","exFr":"Le cours commence à neuf heures.","note":"始作. ≠ 시장 (marché), 시간 (heure). Contraire : 끝나다","conj":"시작해요 · 시작했어요"},"1764052983665":{"ex":"영화표 두 장을 미리 예매했어요.","exFr":"J'ai réservé deux places de cinéma à l'avance.","note":"豫買 « acheter à l'avance » (billets) ≠ 예약 (table, chambre)","conj":"예매해요 · 예매했어요"},"1779706066115":{"ex":"친구가 우리 집에 와요.","exFr":"Un ami vient chez moi.","note":"≠ 가다 (aller), 오늘 (aujourd'hui). 비가 오다 = il pleut","conj":"와요 · 왔어요"},"1779706066128":{"ex":"아침 일곱 시에 일어나요.","exFr":"Je me lève à sept heures du matin.","note":"≠ 일하다 (travailler), 태어나다 (naître). Aussi : se produire","conj":"일어나요 · 일어났어요"},"1779706066127":{"ex":"형은 은행에서 일하고 있어요.","exFr":"Mon frère travaille dans une banque.","note":"일 (travail) + 하다. ≠ 일어나다 (se lever), 일찍 (tôt)","conj":"일해요 · 일했어요"},"1763264324537":{"ex":"저는 아침마다 친구들에게 인사해요.","exFr":"Je salue mes amis chaque matin.","note":"人事. 인사 = salutation. 인사를 나누다 = échanger des salutations","conj":"인사해요 · 인사했어요"},"1764055756959":{"ex":"문을 열고 교실에 들어가요.","exFr":"J'ouvre la porte et j'entre dans la classe.","note":"≠ 들어오다 (entrer, vers ici). Contraire : 나가다","conj":"들어가요 · 들어갔어요"},"1764056538221":{"ex":"시장에서 신선한 과일을 팔아요.","exFr":"On vend des fruits frais au marché.","note":"≠ 사다 (acheter). 팔 = bras","conj":"팔아요 · 팔았어요"},"1764057416001":{"ex":"밤에 운전할 때 조심하세요.","exFr":"Faites attention quand vous conduisez la nuit.","note":"操心. 조심하세요! = Faites attention !","conj":"조심해요 · 조심했어요"},"1764058558116":{"ex":"저는 매일 아침 밖에 나가요.","exFr":"Je sors dehors chaque matin.","note":"≠ 나오다 (sortir, vers ici). Contraire : 들어가다","conj":"나가요 · 나갔어요"},"1765435108500":{"ex":"도서관에서 책을 두 권 빌렸어요.","exFr":"J'ai emprunté deux livres à la bibliothèque.","note":"≠ 빌려주다 (prêter)","conj":"빌려요 · 빌렸어요"},"1765435351795":{"ex":"동생에게 돈을 조금 빌려줬어요.","exFr":"J'ai prêté un peu d'argent à mon petit frère.","note":"빌리다 (emprunter) + 주다 (donner)","conj":"빌려줘요 · 빌려줬어요"},"1765435694365":{"ex":"지갑을 한 시간 동안 찾았어요.","exFr":"J'ai cherché mon portefeuille pendant une heure.","note":"돈을 찾다 = retirer de l'argent","conj":"찾아요 · 찾았어요"},"1765436085011":{"ex":"자기 전에 책을 읽어요.","exFr":"Je lis un livre avant de dormir.","note":"Prononcé [익따] ; 읽어요 = [일거요]","conj":"읽어요 · 읽었어요"},"1765436116932":{"ex":"주말에 조용한 카페에서 독서해요.","exFr":"Le week-end, je lis dans un café calme.","note":"讀書. Plus formel que 책을 읽다","conj":"독서해요 · 독서했어요"},"1779561674291":{"ex":"어제 동생과 크게 싸웠어요.","exFr":"Hier, je me suis beaucoup disputé avec mon petit frère.","note":"Aussi : se battre. ≠ 싸다 (bon marché)","conj":"싸워요 · 싸웠어요"},"1779561857731":{"ex":"역 앞에서 택시를 잡았어요.","exFr":"J'ai hélé un taxi devant la gare.","note":"손을 잡다 = se tenir la main","conj":"잡아요 · 잡았어요"},"1779561878830":{"ex":"저는 조용한 방을 원해요.","exFr":"Je veux une chambre calme.","note":"願. Avec un verbe : -고 싶어요, pas 원해요","conj":"원해요 · 원했어요"},"1779561905119":{"ex":"버스를 삼십 분 기다렸어요.","exFr":"J'ai attendu le bus trente minutes.","conj":"기다려요 · 기다렸어요"},"1779641220270":{"ex":"제가 잘못했어요. 정말 미안해요.","exFr":"C'est ma faute. Je suis vraiment désolé.","note":"잘못 (faute) + 하다. ≠ 못하다 (ne pas savoir faire)","conj":"잘못해요 · 잘못했어요"},"1779641774802":{"ex":"어려운 문제를 드디어 풀었어요.","exFr":"J'ai enfin résolu le problème difficile.","note":"스트레스를 풀다 = décompresser","conj":"풀어요 · 풀었어요"},"1779641858012":{"ex":"선생님이 제 발음을 칭찬했어요.","exFr":"Le professeur a complimenté ma prononciation.","note":"稱讚. 칭찬을 받다 = recevoir un compliment","conj":"칭찬해요 · 칭찬했어요"},"1779706066116":{"ex":"주말에 보통 뭐 해요?","exFr":"Que fais-tu d'habitude le week-end ?","conj":"해요 · 했어요"},"1779706066117":{"ex":"어제 친구와 영화를 봤어요.","exFr":"Hier, j'ai vu un film avec un ami.","note":"Aussi : regarder. 시험을 보다 = passer un examen","conj":"봐요 · 봤어요"},"1779706066118":{"ex":"저는 매일 음악을 들어요.","exFr":"J'écoute de la musique tous les jours.","note":"Irrégulier ㄷ : 들어요. Aussi : suivre (un cours)","conj":"들어요 · 들었어요"},"1779706066119":{"ex":"조금 더 천천히 말해 주세요.","exFr":"Parlez un peu plus lentement, s'il vous plaît.","conj":"말해요 · 말했어요"},"1779706066120":{"ex":"친구에게 긴 편지를 썼어요.","exFr":"J'ai écrit une longue lettre à un ami.","note":"Irrégulier 으 : 써요. Aussi : utiliser, porter (lunettes)","conj":"써요 · 썼어요"},"1779706066122":{"ex":"생일에 선물을 많이 받았어요.","exFr":"J'ai reçu beaucoup de cadeaux pour mon anniversaire.","note":"전화를 받다 = répondre au téléphone","conj":"받아요 · 받았어요"},"1779706066123":{"ex":"친구에게 생일 선물을 줬어요.","exFr":"J'ai donné un cadeau d'anniversaire à un ami.","note":"-아/어 주다 = faire (qqch) pour qqn","conj":"줘요 · 줬어요"},"1779706066124":{"ex":"어머니에게 문자를 자주 보내요.","exFr":"J'envoie souvent des SMS à ma mère.","note":"시간을 보내다 = passer du temps","conj":"보내요 · 보냈어요"},"1779706066125":{"ex":"한국어를 이 년 동안 배웠어요.","exFr":"J'ai appris le coréen pendant deux ans.","note":"≠ 가르치다 (enseigner), 배우 (acteur)","conj":"배워요 · 배웠어요"},"1779706066129":{"ex":"기차가 방금 역에 도착했어요.","exFr":"Le train vient d'arriver à la gare.","note":"到着. Contraire : 출발하다 (partir)","conj":"도착해요 · 도착했어요"},"1779706066130":{"ex":"우리는 아침 일찍 출발했어요.","exFr":"Nous sommes partis tôt le matin.","note":"出發. Contraire : 도착하다 (arriver)","conj":"출발해요 · 출발했어요"},"1779706066131":{"ex":"수업이 다섯 시에 끝나요.","exFr":"Le cours finit à cinq heures.","note":"Intransitif. 끝내다 = finir qqch (transitif)","conj":"끝나요 · 끝났어요"},"1780695436514":{"ex":"저는 부모님과 같이 살아요.","exFr":"J'habite avec mes parents.","note":"ㄹ tombe devant ㄴ/ㅅ : 사는 곳 = lieu de résidence","conj":"살아요 · 살았어요"},"1780695436515":{"ex":"네, 저도 그렇게 생각해요.","exFr":"Oui, je pense aussi comme ça.","note":"생각이 나다 = venir à l'esprit","conj":"생각해요 · 생각했어요"},"1780695436516":{"ex":"저는 그 사람을 잘 알아요.","exFr":"Je connais bien cette personne.","note":"알았어요 = d'accord, compris. Contraire : 모르다","conj":"알아요 · 알았어요"},"1780695436517":{"ex":"죄송해요, 길을 잘 몰라요.","exFr":"Désolé, je ne connais pas bien le chemin.","note":"Irrégulier 르 : 몰라요. Contraire : 알다","conj":"몰라요 · 몰랐어요"},"1780695436518":{"ex":"주말에 딸기 케이크를 만들었어요.","exFr":"J'ai fait un gâteau aux fraises ce week-end.","conj":"만들어요 · 만들었어요"},"1780695436520":{"ex":"밥 먹기 전에 손을 씻어요.","exFr":"Je me lave les mains avant de manger.","note":"Régulier : 씻어요. 세수하다 = se laver le visage","conj":"씻어요 · 씻었어요"},"1780695436521":{"ex":"저는 매일 공원에서 걸어요.","exFr":"Je marche tous les jours dans le parc.","note":"Irrégulier ㄷ : 걸어요. ≠ 걸다 (accrocher, appeler)","conj":"걸어요 · 걸었어요"},"1780695436522":{"ex":"늦어서 학교까지 빨리 뛰었어요.","exFr":"J'étais en retard, alors j'ai couru vite jusqu'à l'école.","note":"Aussi : sauter. 달리다 = courir (sport)","conj":"뛰어요 · 뛰었어요"},"1780695436523":{"ex":"아기가 배가 고파서 울어요.","exFr":"Le bébé pleure parce qu'il a faim.","conj":"울어요 · 울었어요"},"1780695436524":{"ex":"그 이야기를 듣고 많이 웃었어요.","exFr":"En entendant cette histoire, j'ai beaucoup ri.","note":"Aussi : sourire. Contraire : 울다 (pleurer)","conj":"웃어요 · 웃었어요"},"1780695436525":{"ex":"제 동생은 부산에서 태어났어요.","exFr":"Mon petit frère est né à Busan.","conj":"태어나요 · 태어났어요"},"1780695436526":{"ex":"저는 집에서 어머니를 도와요.","exFr":"J'aide ma mère à la maison.","note":"Irrégulier ㅂ : 도와요 (pas 도워요). 도와주세요 !","conj":"도와요 · 도왔어요"},"1780695436528":{"ex":"비가 오니까 우산을 가져가세요.","exFr":"Comme il pleut, emportez un parapluie.","note":"≠ 가져오다 (apporter vers ici)","conj":"가져가요 · 가져갔어요"},"1763264632583":{"ex":"이 식당은 아주 유명해요.","exFr":"Ce restaurant est très célèbre.","note":"有名. 유명한 사람 = une personne célèbre","conj":"유명해요 · 유명했어요"},"1763264712809":{"ex":"오늘은 아주 특별한 날이에요.","exFr":"Aujourd'hui, c'est un jour très spécial.","note":"特別. Adverbe : 특별히 / 특히 (surtout)","conj":"특별해요 · 특별했어요"},"1763265731518":{"ex":"저는 흰색 셔츠를 자주 입어요.","exFr":"Je porte souvent une chemise blanche.","note":"De 희다 (être blanc). Synonyme : 하얀색"},"1763266152173":{"ex":"여행 갈 때 여권이 필요해요.","exFr":"Quand on voyage, on a besoin d'un passeport.","note":"N이/가 필요하다 = avoir besoin de N. ≠ 피곤하다 (fatigué)","conj":"필요해요 · 필요했어요"},"1763266512419":{"ex":"늦어도 괜찮아요. 천천히 오세요.","exFr":"Pas grave si tu es en retard. Viens tranquillement.","note":"Aussi : ça va, pas grave. En refus poli = non merci","conj":"괜찮아요 · 괜찮았어요"},"1763266633439":{"ex":"이 신발은 정말 편해요.","exFr":"Ces chaussures sont vraiment confortables.","note":"便. Contraire : 불편하다 (inconfortable)","conj":"편해요 · 편했어요"},"1763266709154":{"ex":"저는 빨간색 가방을 샀어요.","exFr":"J'ai acheté un sac rouge.","note":"De 빨갛다 (être rouge)"},"1779641497033":{"ex":"이 일은 저한테 아주 새로워요.","exFr":"Ce travail est tout nouveau pour moi.","note":"ㅂ irrég. : 새로워요. 새 + nom = nouveau (새 차)","conj":"새로워요 · 새로웠어요"},"1779641551386":{"ex":"이 바지는 저한테 좀 짧아요.","exFr":"Ce pantalon est un peu court pour moi.","conj":"짧아요 · 짧았어요"},"1779641590572":{"ex":"제 방 커튼은 보라색이에요.","exFr":"Les rideaux de ma chambre sont violets."},"1779642738346":{"ex":"저는 진한 커피를 좋아해요.","exFr":"J'aime le café fort.","note":"Café fort, couleur foncée. Contraire : 연하다 (clair/léger)","conj":"진해요 · 진했어요"},"1779706065963":{"ex":"그 검은색 고양이가 정말 귀여워요.","exFr":"Ce chat noir est vraiment mignon.","note":"De 검다. Aussi 까만색"},"1779706065964":{"ex":"오늘 하늘이 회색이고 흐려요.","exFr":"Aujourd'hui, le ciel est gris et couvert."},"1779706065965":{"ex":"저는 파란색 티셔츠를 입었어요.","exFr":"J'ai mis un tee-shirt bleu.","note":"De 파랗다. 파란불 = feu vert (!)"},"1779706065966":{"ex":"봄에는 나무가 초록색이 돼요.","exFr":"Au printemps, les arbres deviennent verts.","note":"Synonyme : 녹색"},"1779706065967":{"ex":"노란색 꽃이 정말 예뻐요.","exFr":"Les fleurs jaunes sont vraiment jolies.","note":"De 노랗다 (être jaune)"},"1779706065968":{"ex":"저는 주황색 모자가 있어요.","exFr":"J'ai un chapeau orange.","note":"Le fruit orange = 오렌지"},"1779706065969":{"ex":"제 동생은 분홍색을 제일 좋아해요.","exFr":"Ma petite sœur préfère le rose.","note":"Synonyme courant : 핑크색"},"1779706065970":{"ex":"제 머리하고 눈은 갈색이에요.","exFr":"Mes cheveux et mes yeux sont marron."},"1779706065971":{"ex":"아버지는 남색 양복을 자주 입으세요.","exFr":"Mon père porte souvent un costume bleu marine.","note":"藍 (indigo). ≠ 남자 (homme)"},"1779706065972":{"ex":"그 하늘색 원피스가 잘 어울려요.","exFr":"Cette robe bleu ciel te va bien.","note":"하늘 (ciel) + 색 (couleur)"},"1779706065973":{"ex":"이 금색 시계는 아주 비싸요.","exFr":"Cette montre dorée est très chère.","note":"金. 금 = or — même hanja que 금요일 (vendredi)"},"1779706065974":{"ex":"우리 아빠 차는 은색이에요.","exFr":"La voiture de mon papa est argentée.","note":"銀. 은 = argent — cf. 은행 (banque, 銀行)"},"1779706065975":{"ex":"무슨 색깔을 제일 좋아해요?","exFr":"Quelle couleur préfères-tu ?","note":"Synonyme : 색"},"1779706066133":{"ex":"오늘 날씨가 정말 좋아요.","exFr":"Il fait vraiment beau aujourd'hui.","note":"≠ 좋아하다 : N이/가 좋다 vs N을/를 좋아하다","conj":"좋아요 · 좋았어요"},"1779706066135":{"ex":"서울에는 사람이 정말 많아요.","exFr":"À Séoul, il y a vraiment beaucoup de monde.","note":"Adverbe : 많이","conj":"많아요 · 많았어요"},"1779706066136":{"ex":"이 가게는 손님이 적어요.","exFr":"Ce magasin a peu de clients.","note":"Quantité. ≠ 작다 (petit, taille). Aussi 적다 = noter","conj":"적어요 · 적었어요"},"1779706066137":{"ex":"우리 집 개는 아주 커요.","exFr":"Notre chien est très grand.","note":"ㅡ irrég. : 커요. 키가 크다 = être grand (taille)","conj":"커요 · 컸어요"},"1779706066138":{"ex":"이 옷은 저한테 너무 작아요.","exFr":"Ce vêtement est trop petit pour moi.","note":"Taille. ≠ 적다 (peu, quantité)","conj":"작아요 · 작았어요"},"1779706066139":{"ex":"겨울에는 밤이 정말 길어요.","exFr":"En hiver, les nuits sont vraiment longues.","note":"길 = aussi 'chemin, route'","conj":"길어요 · 길었어요"},"1779706066140":{"ex":"지하철이 버스보다 더 빨라요.","exFr":"Le métro est plus rapide que le bus.","note":"르 irrég. : 빨라요. Adverbe : 빨리","conj":"빨라요 · 빨랐어요"},"1779706066141":{"ex":"이 컴퓨터는 너무 느려요.","exFr":"Cet ordinateur est trop lent.","conj":"느려요 · 느렸어요"},"1779706066142":{"ex":"이번 시험은 아주 쉬웠어요.","exFr":"Cet examen était très facile.","note":"ㅂ irrég. : 쉬워요. Contraire : 어렵다","conj":"쉬워요 · 쉬웠어요"},"1779706066145":{"ex":"저한테는 가족이 제일 중요해요.","exFr":"Pour moi, la famille est ce qu'il y a de plus important.","conj":"중요해요 · 중요했어요"},"1779706066146":{"ex":"저하고 친구는 나이가 같아요.","exFr":"Mon ami et moi avons le même âge.","note":"N하고 같다 = pareil que N. 같이 = ensemble","conj":"같아요 · 같았어요"},"1779706066147":{"ex":"한국어는 프랑스어하고 많이 달라요.","exFr":"Le coréen est très différent du français.","note":"르 irrég. : 달라요. ≠ 틀리다 (faux)","conj":"달라요 · 달랐어요"},"1763264735091":{"ex":"이 근처에 유명한 맛집이 있어요.","exFr":"Il y a un bon restaurant connu près d'ici.","note":"맛(goût) + 집(maison) : resto réputé, mot très courant."},"1763265025043":{"ex":"엄마가 지금 부엌에서 요리해요.","exFr":"Maman cuisine dans la cuisine en ce moment.","note":"Syn. 주방 (plus courant pour une cuisine moderne ou de resto)."},"1763265058308":{"ex":"저녁 먹고 제가 설거지해요.","exFr":"Après le dîner, c'est moi qui fais la vaisselle.","conj":"설거지해요 · 설거지했어요"},"1763265115177":{"ex":"주말에 집에서 자주 요리해요.","exFr":"Le week-end, je cuisine souvent à la maison.","conj":"요리해요 · 요리했어요"},"1763265221839":{"ex":"제 방은 조금 작아요.","exFr":"Ma chambre est un peu petite.","note":"Pièce ou chambre en général ; 노래방, PC방 = salle de..."},"1763265235188":{"ex":"가족이 거실에서 텔레비전을 봐요.","exFr":"La famille regarde la télévision dans le salon."},"1763265302170":{"ex":"침실에 큰 침대가 있어요.","exFr":"Il y a un grand lit dans la chambre.","note":"침실 = chambre à coucher précise ; 방 = pièce en général."},"1763265318628":{"ex":"책상 위에 컴퓨터가 있어요.","exFr":"Il y a un ordinateur sur le bureau.","note":"Bureau de travail ; ≠ 식탁 (table à manger)."},"1763265345816":{"ex":"토요일마다 제 방을 청소해요.","exFr":"Je nettoie ma chambre tous les samedis.","conj":"청소해요 · 청소했어요"},"1763265540310":{"ex":"샤워 후에 수건으로 몸을 닦아요.","exFr":"Après la douche, je m'essuie avec une serviette."},"1763265557861":{"ex":"매일 아침에 일어나서 샤워해요.","exFr":"Chaque matin, je me lève et je me douche.","conj":"샤워해요 · 샤워했어요"},"1763265650085":{"ex":"마당에서 강아지가 놀고 있어요.","exFr":"Le chiot joue dans la cour."},"1763265830119":{"ex":"날씨가 더워서 창문을 열었어요.","exFr":"Il faisait chaud, alors j'ai ouvert la fenêtre."},"1763266212580":{"ex":"이 김치찌개는 너무 매워요.","exFr":"Ce ragoût de kimchi est trop épicé.","note":"Irrégulier ㅂ : 매워요 ; 매운 음식 = nourriture épicée.","conj":"매워요 · 매웠어요"},"1763266436624":{"ex":"한국 음식을 정말 좋아해요.","exFr":"J'aime beaucoup la nourriture coréenne."},"1763266778551":{"ex":"저는 아침마다 과일을 먹어요.","exFr":"Je mange des fruits tous les matins."},"1763266805543":{"ex":"여름에는 아이스크림을 자주 먹어요.","exFr":"En été, je mange souvent de la glace."},"1763266838131":{"ex":"커피와 초콜릿을 같이 먹어요.","exFr":"Je mange du chocolat avec mon café."},"1763266887926":{"ex":"이 약은 너무 써요.","exFr":"Ce médicament est très amer.","note":"Aussi « écrire » et « utiliser » — le contexte décide.","conj":"써요 · 썼어요"},"1764056139480":{"ex":"아이들이 사탕을 정말 좋아해요.","exFr":"Les enfants adorent les bonbons."},"1764058248068":{"ex":"쓰레기는 저기 쓰레기통에 버리세요.","exFr":"Jetez les déchets dans la poubelle là-bas.","note":"쓰레기 (déchet) + 통 (récipient)."},"1779642794545":{"ex":"저녁에 고기를 구워서 먹었어요.","exFr":"Le soir, on a fait griller de la viande et on l'a mangée.","note":"Irrégulier ㅂ : 구워요 ; 구운 고기 = viande grillée.","conj":"구워요 · 구웠어요"},"1779706066059":{"ex":"아직 밥을 안 먹었어요.","exFr":"Je n'ai pas encore mangé.","note":"밥 먹었어요 ? = salutation courante entre proches."},"1779706066060":{"ex":"물 한 잔 주세요.","exFr":"Un verre d'eau, s'il vous plaît."},"1779706066061":{"ex":"따뜻한 차를 마시고 싶어요.","exFr":"Je voudrais boire un thé chaud.","note":"Homonyme : 차 = aussi « voiture » — le contexte décide."},"1779706066062":{"ex":"매일 아침 우유를 마셔요.","exFr":"Je bois du lait chaque matin."},"1779706066063":{"ex":"저는 고기를 안 먹어요.","exFr":"Je ne mange pas de viande."},"1779706066064":{"ex":"오늘 시장에서 생선을 샀어요.","exFr":"Aujourd'hui, j'ai acheté du poisson au marché.","note":"생선 = poisson (aliment) ; 물고기 = poisson (animal)."},"1779706066065":{"ex":"채소를 많이 먹어야 해요.","exFr":"Il faut manger beaucoup de légumes.","note":"Syn. 야채, très courant à l'oral."},"1779706066066":{"ex":"부산에서 신선한 해산물을 먹었어요.","exFr":"J'ai mangé des fruits de mer frais à Busan."},"1779706066067":{"ex":"아침에 국하고 밥을 먹어요.","exFr":"Le matin, je mange de la soupe avec du riz.","note":"국 = soupe coréenne ; soupe occidentale = 수프."},"1779706066068":{"ex":"빵집에서 맛있는 빵을 샀어요.","exFr":"J'ai acheté du bon pain à la boulangerie."},"1779706066069":{"ex":"아침에 계란을 두 개 먹었어요.","exFr":"J'ai mangé deux œufs ce matin.","note":"Syn. pur coréen : 달걀."},"1779706066070":{"ex":"빵에 치즈를 넣어서 먹어요.","exFr":"Je mets du fromage dans le pain."},"1779706066071":{"ex":"이 케이크는 너무 달아요.","exFr":"Ce gâteau est trop sucré.","note":"단 음식 = aliments sucrés ; ↔ 쓰다 (amer).","conj":"달아요 · 달았어요"},"1779706066072":{"ex":"이 레몬은 정말 셔요.","exFr":"Ce citron est vraiment acide.","note":"시- + -어요 → 셔요.","conj":"셔요 · 셨어요"},"1779706066073":{"ex":"이 식당 음식이 진짜 맛있어요.","exFr":"La nourriture de ce restaurant est vraiment délicieuse.","conj":"맛있어요 · 맛있었어요"},"1779706066074":{"ex":"그 빵은 좀 맛없었어요.","exFr":"Ce pain n'était pas très bon.","note":"Prononcé [마덥따].","conj":"맛없어요 · 맛없었어요"},"1779706066075":{"ex":"점심을 못 먹어서 배고파요.","exFr":"Je n'ai pas pu déjeuner, alors j'ai faim.","note":"배(ventre) + 고프다 ; irrégulier 으 → 배고파요.","conj":"배고파요 · 배고팠어요"},"1779706066076":{"ex":"운동 후에 너무 목말라요.","exFr":"Après le sport, j'ai très soif.","note":"목(gorge) + 마르다 ; irrégulier 르 → 목말라요.","conj":"목말라요 · 목말랐어요"},"1779706066077":{"ex":"자기 전에 침대에서 책을 읽어요.","exFr":"Avant de dormir, je lis au lit."},"1779706066078":{"ex":"여기 의자에 앉아서 기다리세요.","exFr":"Asseyez-vous ici sur la chaise et attendez."},"1779706066079":{"ex":"테이블 위에 컵이 있어요.","exFr":"Il y a une tasse sur la table.","note":"식탁 = table à manger (repas)."},"1779706066080":{"ex":"추우니까 문을 닫아 주세요.","exFr":"Il fait froid, fermez la porte s'il vous plaît."},"1779706066081":{"ex":"바닥에 앉아서 밥을 먹어요.","exFr":"On s'assoit par terre pour manger."},"1779706066082":{"ex":"벽에 가족 사진이 있어요.","exFr":"Il y a une photo de famille sur le mur."},"1779706066083":{"ex":"저기요, 화장실이 어디에 있어요?","exFr":"Excusez-moi, où sont les toilettes ?","note":"Sert pour « toilettes » partout (maison, resto, rue)."},"1779706066084":{"ex":"저는 아침마다 욕실에서 샤워해요.","exFr":"Je me douche dans la salle de bains chaque matin.","note":"욕실 = pièce avec douche/bain ; 화장실 = WC."},"1779706066085":{"ex":"어제 집 열쇠를 잃어버렸어요.","exFr":"Hier, j'ai perdu la clé de la maison."},"1779706066086":{"ex":"어두우니까 불을 켜 주세요.","exFr":"Il fait sombre, allume la lumière s'il te plaît.","note":"Aussi « feu » ; 불을 켜다/끄다 = allumer/éteindre."},"1779706066087":{"ex":"집에 오면 먼저 불을 켜요.","exFr":"En rentrant, j'allume d'abord la lumière.","note":"↔ 끄다 (éteindre).","conj":"켜요 · 켰어요"},"1779706066088":{"ex":"자기 전에 불을 꺼요.","exFr":"Avant de dormir, j'éteins la lumière.","note":"Irrégulier 으 : 꺼요 ; ↔ 켜다 (allumer).","conj":"꺼요 · 껐어요"},"1779706066089":{"ex":"창문을 좀 열어 주세요.","exFr":"Ouvre la fenêtre, s'il te plaît.","note":"↔ 닫다 (fermer) ; impératif : 여세요 (le ㄹ tombe).","conj":"열어요 · 열었어요"},"1779706066090":{"ex":"나갈 때 문을 닫으세요.","exFr":"Fermez la porte en sortant.","note":"ㄷ régulier (≠ 듣다) : 닫아요.","conj":"닫아요 · 닫았어요"},"1780695436436":{"ex":"매일 사과를 하나 먹어요.","exFr":"Je mange une pomme chaque jour.","note":"Homonyme : 사과(하다) = excuses / s'excuser."},"1780695436437":{"ex":"아침에 바나나를 하나 먹었어요.","exFr":"Ce matin, j'ai mangé une banane."},"1780695436438":{"ex":"봄에는 딸기가 정말 맛있어요.","exFr":"Au printemps, les fraises sont vraiment délicieuses."},"1780695436439":{"ex":"포도 한 송이를 샀어요.","exFr":"J'ai acheté une grappe de raisin.","note":"한 송이 = une grappe ; 포도주 = vin."},"1780695436440":{"ex":"여름에는 시원한 수박을 먹어요.","exFr":"En été, on mange de la pastèque bien fraîche."},"1780695436441":{"ex":"아침에 오렌지 주스를 마셔요.","exFr":"Le matin, je bois du jus d'orange."},"1780695436442":{"ex":"한국 배는 크고 달아요.","exFr":"Les poires coréennes sont grosses et sucrées.","note":"Homonyme : 배 = aussi « ventre » et « bateau »."},"1780695436444":{"ex":"토끼는 당근을 아주 좋아해요.","exFr":"Les lapins adorent les carottes."},"1780695436445":{"ex":"양파를 자를 때 눈물이 나요.","exFr":"Quand je coupe des oignons, les larmes coulent."},"1780695436446":{"ex":"오늘 감자로 요리를 만들었어요.","exFr":"Aujourd'hui, j'ai préparé un plat avec des pommes de terre.","note":"감자튀김 = frites."},"1780695436447":{"ex":"겨울에 고구마를 구워 먹어요.","exFr":"En hiver, on mange des patates douces grillées."},"1780695436448":{"ex":"점심에 토마토로 샐러드를 만들었어요.","exFr":"À midi, j'ai fait une salade de tomates."},"1780695436449":{"ex":"오이를 싫어하는 사람이 많아요.","exFr":"Beaucoup de gens n'aiment pas le concombre."},"1780695436450":{"ex":"한국 요리에는 마늘이 많이 들어가요.","exFr":"Il y a beaucoup d'ail dans la cuisine coréenne."},"1780695436540":{"ex":"창문으로 밝은 빛이 들어와요.","exFr":"Une lumière vive entre par la fenêtre.","note":"빛 = clarté/rayon ; 불 = lampe/feu ; 햇빛 = lumière du soleil."},"1763107144967":{"ex":"서울은 아주 큰 도시예요.","exFr":"Séoul est une très grande ville.","note":"≠ 시내 (centre-ville)"},"1763264355212":{"ex":"전철역 앞에서 친구를 만나요.","exFr":"Je retrouve un ami devant la station de métro.","note":"전철 = 지하철 ; 역 = gare/station"},"1763266380080":{"ex":"우리 동네에 공원이 있어요.","exFr":"Il y a un parc dans mon quartier.","note":"우리 동네 = mon quartier (ton familier)"},"1779561735080":{"ex":"주말에 친구하고 극장에 가요.","exFr":"Le week-end, je vais au théâtre avec un ami.","note":"Désigne le théâtre et le cinéma (= 영화관)"},"1779706066013":{"ex":"동생은 아침에 학교에 가요.","exFr":"Mon petit frère va à l'école le matin."},"1779706066014":{"ex":"우리 언니는 대학교에 다녀요.","exFr":"Ma grande sœur va à l'université.","note":"다니다 = fréquenter ; 대학생 = étudiant"},"1779706066015":{"ex":"은행은 오후 네 시에 문을 닫아요.","exFr":"La banque ferme à seize heures."},"1779706066016":{"ex":"머리가 아파서 병원에 갔어요.","exFr":"J'avais mal à la tête, donc je suis allé à l'hôpital.","note":"En Corée, désigne aussi un simple cabinet médical"},"1779706066017":{"ex":"어제 약국에서 감기약을 샀어요.","exFr":"Hier, j'ai acheté un médicament contre le rhume à la pharmacie.","note":"약 = médicament"},"1779706066018":{"ex":"오늘 우체국에서 편지를 보냈어요.","exFr":"Aujourd'hui, j'ai envoyé une lettre à la poste."},"1779706066019":{"ex":"시험 전에 도서관에서 공부해요.","exFr":"Avant un examen, j'étudie à la bibliothèque.","note":"≠ 서점 (librairie, où on achète)"},"1779706066020":{"ex":"어제 영화관에서 영화를 봤어요.","exFr":"Hier, j'ai vu un film au cinéma.","note":"= 극장"},"1779706066021":{"ex":"친구하고 카페에서 커피를 마셔요.","exFr":"Je bois un café avec un ami au café."},"1779706066022":{"ex":"이 식당은 불고기가 맛있어요.","exFr":"Dans ce restaurant, le bulgogi est délicieux.","note":"≠ 레스토랑 (restaurant style occidental)"},"1779706066024":{"ex":"슈퍼마켓에서 우유하고 빵을 샀어요.","exFr":"J'ai acheté du lait et du pain au supermarché.","note":"Souvent abrégé en 슈퍼"},"1779706066028":{"ex":"오늘은 집에서 쉬고 싶어요.","exFr":"Aujourd'hui, je veux me reposer à la maison."},"1779706066031":{"ex":"지하철이 버스보다 더 빨라요.","exFr":"Le métro est plus rapide que le bus.","note":"지하 = sous-sol, 철 = fer"},"1779706066032":{"ex":"학교까지 버스로 삼십 분 걸려요.","exFr":"Jusqu'à l'école, ça prend trente minutes en bus."},"1779706066033":{"ex":"시간이 없어서 택시를 탔어요.","exFr":"Je n'avais pas le temps, donc j'ai pris un taxi."},"1779706066035":{"ex":"비행기 표가 너무 비싸요.","exFr":"Le billet d'avion est trop cher."},"1779706066038":{"ex":"영화 표 두 장 주세요.","exFr":"Deux billets de cinéma, s'il vous plaît.","note":"Compteur : 장 (두 장 = deux billets)"},"1779706066039":{"ex":"교통카드가 없어서 표를 샀어요.","exFr":"Je n'avais pas de carte de transport, donc j'ai acheté un billet.","note":"교통 = transport / circulation"},"1779706066040":{"ex":"아침마다 버스를 타고 학교에 가요.","exFr":"Tous les matins, je prends le bus pour aller à l'école.","note":"버스를 타다 : avec 을/를, pas 에","conj":"타요 · 탔어요"},"1779706066041":{"ex":"우리는 다음 역에서 내려요.","exFr":"Nous descendons à la prochaine station.","note":"버스에서 내리다 (avec 에서). Aussi : tomber (pluie, neige)","conj":"내려요 · 내렸어요"},"1779706066042":{"ex":"다음 역에서 버스로 갈아타요.","exFr":"À la prochaine station, je change pour le bus.","note":"갈다 (changer) + 타다 (monter)","conj":"갈아타요 · 갈아탔어요"},"1779706066043":{"ex":"이 길로 똑바로 가세요.","exFr":"Suivez cette rue tout droit.","conj":"똑바로 가요 · 똑바로 갔어요"},"1779706066044":{"ex":"은행 앞에서 오른쪽으로 가세요.","exFr":"Devant la banque, allez à droite.","note":"-(으)로 = vers (direction)","conj":"오른쪽으로 가요 · 오른쪽으로 갔어요"},"1779706066045":{"ex":"학교 앞에서 왼쪽으로 가세요.","exFr":"Devant l'école, allez à gauche.","conj":"왼쪽으로 가요 · 왼쪽으로 갔어요"},"1779706066046":{"ex":"저기 신호등에서 길을 건너세요.","exFr":"Traversez la rue au feu, là-bas.","note":"길을 건너다 = traverser la rue","conj":"건너요 · 건넜어요"},"1779706066104":{"ex":"오늘은 날씨가 정말 좋아요.","exFr":"Aujourd'hui, il fait vraiment beau."},"1779706066105":{"ex":"비가 와서 집에 있었어요.","exFr":"Il pleuvait, donc je suis resté à la maison.","note":"= 비가 내리다","conj":"비가 와요 · 비가 왔어요"},"1779706066106":{"ex":"겨울에는 눈이 많이 와요.","exFr":"En hiver, il neige beaucoup.","note":"눈 = neige ET yeux (homonyme)","conj":"눈이 와요 · 눈이 왔어요"},"1779706066108":{"ex":"여름에 한국은 아주 더워요.","exFr":"En été, il fait très chaud en Corée.","note":"Météo ; ≠ 뜨겁다 (chaud au toucher)","conj":"더워요 · 더웠어요"},"1779706066109":{"ex":"오늘은 바람이 불어서 추워요.","exFr":"Aujourd'hui, il y a du vent, donc il fait froid.","note":"Météo ; ≠ 차갑다 (froid au toucher)","conj":"추워요 · 추웠어요"},"1779706066110":{"ex":"따뜻한 차를 마시고 싶어요.","exFr":"Je veux boire un thé chaud.","note":"Chaleur agréable (météo, boisson, personne)","conj":"따뜻해요 · 따뜻했어요"},"1779706066111":{"ex":"이 물은 너무 차가워요.","exFr":"Cette eau est très froide.","note":"Objet / boisson ; ≠ 춥다 (météo)","conj":"차가워요 · 차가웠어요"},"1779706066112":{"ex":"오늘은 하늘이 아주 맑아요.","exFr":"Aujourd'hui, le ciel est très dégagé.","note":"≠ 흐리다 (nuageux)","conj":"맑아요 · 맑았어요"},"1779706066113":{"ex":"오전에는 흐리고 오후에는 맑아요.","exFr":"Le matin c'est nuageux, l'après-midi c'est dégagé.","note":"≠ 맑다 (dégagé)","conj":"흐려요 · 흐렸어요"},"1763107082010":{"ex":"우리 가족은 모두 네 명이에요.","exFr":"Ma famille compte quatre personnes en tout.","note":"우리 가족 : le coréen dit « notre famille », pas « ma »"},"1763265512428":{"ex":"사촌이 다음 주에 우리 집에 와요.","exFr":"Mon cousin vient chez nous la semaine prochaine.","note":"cousin ET cousine. ≠ 삼촌 (oncle)"},"1763266291560":{"ex":"이제 집에 가야 해요.","exFr":"Maintenant, je dois rentrer à la maison.","note":"≠ 지금 (à l'instant même) — 이제 marque un changement"},"1763266903048":{"ex":"동생은 눈이 정말 커요.","exFr":"Mon petit frère a de très grands yeux.","note":"눈 = œil ET neige (homonymes)"},"1779641695674":{"ex":"나중에 커피 한잔 같이 해요.","exFr":"Prenons un café ensemble plus tard.","note":"≠ 이따가 (plus tard dans la même journée)"},"1779706065977":{"ex":"오늘 날씨가 정말 좋아요.","exFr":"Il fait vraiment beau aujourd'hui."},"1779706065978":{"ex":"어제 비가 많이 왔어요.","exFr":"Hier, il a beaucoup plu."},"1779706065979":{"ex":"내일 한국어 시험이 있어요.","exFr":"Demain, j'ai un examen de coréen.","note":"≠ 매일 (chaque jour)"},"1779706065980":{"ex":"그저께 친구하고 영화를 봤어요.","exFr":"Avant-hier, j'ai vu un film avec un ami.","note":"forme courte : 그제"},"1779706065981":{"ex":"모레 부산에 여행 가요.","exFr":"Après-demain, je pars en voyage à Busan.","note":"≠ 모래 (sable)"},"1779706065982":{"ex":"저는 아침에 일찍 일어나요.","exFr":"Le matin, je me lève tôt.","note":"aussi : petit-déjeuner (아침을 먹다)"},"1779706065983":{"ex":"점심에 뭐 먹을 거예요?","exFr":"Qu'est-ce que tu manges à midi ?","note":"aussi : déjeuner (점심을 먹다)"},"1779706065984":{"ex":"저녁에 가족하고 밥을 먹어요.","exFr":"Le soir, je dîne avec ma famille.","note":"aussi : dîner (저녁을 먹다)"},"1779706065985":{"ex":"밤에 별이 정말 예뻐요.","exFr":"La nuit, les étoiles sont vraiment belles.","note":"≠ 밥 (riz/repas). 밤 = aussi châtaigne"},"1779706065986":{"ex":"저는 일주일에 두 번 운동해요.","exFr":"Je fais du sport deux fois par semaine.","note":"이번 주 = cette semaine, 다음 주 = la semaine prochaine"},"1779706065987":{"ex":"이번 주말에 뭐 할 거예요?","exFr":"Qu'est-ce que tu fais ce week-end ?"},"1779706065988":{"ex":"주말에 친구들하고 축구를 해요.","exFr":"Le week-end, je joue au foot avec des amis."},"1779706065989":{"ex":"월요일부터 다시 회사에 가요.","exFr":"À partir de lundi, je retourne au travail.","note":"jours = hanja + 요일 : 월화수목금토일"},"1779706065990":{"ex":"화요일에 한국어 수업이 있어요.","exFr":"Mardi, j'ai un cours de coréen."},"1779706065991":{"ex":"이번 수요일에 친구를 만나요.","exFr":"Ce mercredi, je vois un ami."},"1779706065992":{"ex":"목요일에 병원에 가야 해요.","exFr":"Jeudi, je dois aller à l'hôpital.","note":"≠ 목 (cou/gorge)"},"1779706065993":{"ex":"금요일 저녁에 영화를 봐요.","exFr":"Vendredi soir, je regarde un film."},"1779706065994":{"ex":"토요일 아침에는 늦게까지 자요.","exFr":"Le samedi matin, je dors tard."},"1779706065995":{"ex":"일요일마다 공원에서 산책을 해요.","exFr":"Chaque dimanche, je me promène au parc."},"1779706065996":{"ex":"일월에는 눈이 많이 와요.","exFr":"En janvier, il neige beaucoup.","note":"mois = nombre sino + 월. Irréguliers : 유월 (juin), 시월 (oct.)"},"1779706065997":{"ex":"이월은 다른 달보다 짧아요.","exFr":"Février est plus court que les autres mois."},"1779706065998":{"ex":"삼월에 새 학기가 시작돼요.","exFr":"En mars, le nouveau semestre commence.","note":"l'année scolaire coréenne commence en mars"},"1779706065999":{"ex":"사월에는 벚꽃이 예쁘게 피어요.","exFr":"En avril, les cerisiers fleurissent joliment."},"1779706066000":{"ex":"오월에는 날씨가 아주 따뜻해요.","exFr":"En mai, il fait très doux."},"1779706066001":{"ex":"유월에는 비가 자주 와요.","exFr":"En juin, il pleut souvent.","note":"irrégulier : 육 + 월 → 유월"},"1779706066002":{"ex":"칠월에 여름 방학이 시작돼요.","exFr":"En juillet, les vacances d'été commencent."},"1779706066003":{"ex":"팔월에는 날씨가 정말 더워요.","exFr":"En août, il fait vraiment chaud."},"1779706066004":{"ex":"구월에도 날씨가 아직 더워요.","exFr":"En septembre, il fait encore chaud."},"1779706066005":{"ex":"시월에 단풍이 정말 예뻐요.","exFr":"En octobre, les feuilles d'automne sont magnifiques.","note":"irrégulier : 십 + 월 → 시월"},"1779706066006":{"ex":"십일월에는 바람이 많이 불어요.","exFr":"En novembre, il y a beaucoup de vent."},"1779706066007":{"ex":"십이월에 가족하고 여행을 가요.","exFr":"En décembre, je pars en voyage avec ma famille."},"1779706066008":{"ex":"십 분만 기다려 주세요.","exFr":"Attendez dix minutes, s'il vous plaît.","note":"aussi : personne (honorifique) — 이분 = cette personne"},"1779706066009":{"ex":"두 시간 동안 공부했어요.","exFr":"J'ai étudié pendant deux heures.","note":"durée. Heure fixe = 시 : 세 시 = 3 h"},"1779706066010":{"ex":"삼십 분 후에 도착해요.","exFr":"J'arrive dans trente minutes.","note":"= 반 (demie) : 세 시 반 = 3 h 30"},"1779706066091":{"ex":"오늘 머리가 조금 아파요.","exFr":"Aujourd'hui, j'ai un peu mal à la tête.","note":"aussi : cheveux (머리를 자르다 = se couper les cheveux)"},"1779706066092":{"ex":"아기 얼굴이 정말 귀여워요.","exFr":"Le visage du bébé est vraiment mignon."},"1779706066093":{"ex":"코끼리는 코가 아주 길어요.","exFr":"L'éléphant a une très longue trompe.","note":"코가 막히다 = avoir le nez bouché"},"1779706066094":{"ex":"매운 음식을 먹어서 입이 아파요.","exFr":"J'ai mangé épicé, j'ai mal à la bouche.","note":"≠ 잎 (feuille), même prononciation"},"1779706066095":{"ex":"음악 소리가 커서 귀가 아파요.","exFr":"La musique est forte, j'ai mal aux oreilles."},"1779706066096":{"ex":"밥 먹기 전에 손을 씻어요.","exFr":"Je me lave les mains avant de manger.","note":"손가락 = doigt, 손님 = client/invité"},"1779706066097":{"ex":"새 신발 때문에 발이 아파요.","exFr":"J'ai mal aux pieds à cause de mes nouvelles chaussures.","note":"≠ 팔 (bras)"},"1779706066098":{"ex":"배가 고파서 밥을 먹었어요.","exFr":"J'avais faim, alors j'ai mangé.","note":"aussi : poire, bateau. 배가 고프다 = avoir faim"},"1779706066100":{"ex":"지난주에 심한 감기에 걸렸어요.","exFr":"La semaine dernière, j'ai attrapé un gros rhume.","note":"감기에 걸리다 = attraper un rhume"},"1779706066101":{"ex":"하루에 세 번 약을 먹어요.","exFr":"Je prends des médicaments trois fois par jour.","note":"약을 먹다 (litt. « manger »), jamais 마시다"},"1779706066103":{"ex":"너무 피곤해서 집에서 쉬었어요.","exFr":"J'étais très fatigué, alors je me suis reposé à la maison.","note":"푹 쉬세요 = reposez-vous bien","conj":"쉬어요 · 쉬었어요"},"1779724539673":{"ex":"아버지는 지금 회사에서 일하세요.","exFr":"Mon père travaille au bureau en ce moment.","note":"familier : 아빠 (papa)"},"1779724539674":{"ex":"어머니는 요리를 정말 잘하세요.","exFr":"Ma mère cuisine vraiment bien.","note":"familier : 엄마 (maman)"},"1779724539675":{"ex":"형은 저보다 두 살 많아요.","exFr":"Mon grand frère a deux ans de plus que moi.","note":"dit par un HOMME. Une femme dit 오빠"},"1779724539676":{"ex":"우리 오빠는 대학교에 다녀요.","exFr":"Mon grand frère va à l'université.","note":"dit par une FEMME. Un homme dit 형"},"1779724539677":{"ex":"누나는 서울에서 회사에 다녀요.","exFr":"Ma grande sœur travaille dans une entreprise à Séoul.","note":"dit par un HOMME. Une femme dit 언니"},"1779724539678":{"ex":"언니하고 같이 쇼핑을 했어요.","exFr":"J'ai fait du shopping avec ma grande sœur.","note":"dit par une FEMME. Un homme dit 누나"},"1779724539679":{"ex":"제 동생은 아직 학생이에요.","exFr":"Mon petit frère est encore étudiant.","note":"남동생 = petit frère, 여동생 = petite sœur"},"1779724539680":{"ex":"주말에 부모님을 만나러 가요.","exFr":"Le week-end, je vais voir mes parents.","note":"-님 = marque de respect, toujours incluse"},"1779724539681":{"ex":"제 남편은 은행에서 일해요.","exFr":"Mon mari travaille dans une banque."},"1779724539682":{"ex":"아내가 저녁을 준비하고 있어요.","exFr":"Ma femme prépare le dîner.","note":"l'épouse d'autrui (poli) : 부인"},"1780695436464":{"ex":"할아버지는 올해 여든 살이세요.","exFr":"Mon grand-père a quatre-vingts ans cette année."},"1780695436465":{"ex":"방학에 할머니 집에 가요.","exFr":"Pendant les vacances, je vais chez ma grand-mère."},"1780695436466":{"ex":"우리 삼촌은 부산에 살아요.","exFr":"Mon oncle habite à Busan.","note":"≠ 사촌 (cousin). Oncle maternel : 외삼촌"},"1780695436467":{"ex":"이모가 맛있는 김치를 만들어요.","exFr":"Ma tante fait un très bon kimchi.","note":"sœur de la MÈRE. Sœur du père : 고모"},"1780695436468":{"ex":"우리 고모는 학교 선생님이에요.","exFr":"Ma tante est professeure.","note":"sœur du PÈRE. Sœur de la mère : 이모"},"1780695436469":{"ex":"아들이 내년에 학교에 가요.","exFr":"Mon fils entre à l'école l'année prochaine."},"1780695436470":{"ex":"제 딸이 피아노를 배워요.","exFr":"Ma fille apprend le piano.","note":"≠ 달 (lune / mois)"},"1780695436471":{"ex":"아이가 공원에서 놀고 있어요.","exFr":"L'enfant joue dans le parc.","note":"forme contractée : 애. 아이들 = les enfants"},"1780695436472":{"ex":"할머니는 손자를 정말 사랑하세요.","exFr":"La grand-mère aime beaucoup son petit-fils.","note":"≠ 손 (main). Petite-fille : 손녀"},"1780695436473":{"ex":"할아버지가 손녀 사진을 보세요.","exFr":"Le grand-père regarde la photo de sa petite-fille."},"1780695436479":{"ex":"어느 계절을 제일 좋아해요?","exFr":"Quelle saison préfères-tu ?","note":"사계절 = les quatre saisons"},"1780695436480":{"ex":"봄에 꽃이 많이 피어요.","exFr":"Au printemps, beaucoup de fleurs éclosent."},"1780695436481":{"ex":"여름에 바다에 자주 가요.","exFr":"En été, je vais souvent à la mer."},"1780695436482":{"ex":"가을 날씨를 정말 좋아해요.","exFr":"J'aime beaucoup le temps d'automne."},"1780695436483":{"ex":"겨울에 스키를 타러 가요.","exFr":"En hiver, je vais faire du ski."},"1780695436484":{"ex":"감기 때문에 목이 아파요.","exFr":"À cause du rhume, j'ai mal à la gorge.","note":"cou ET gorge. 목이 마르다 = avoir soif"},"1780695436486":{"ex":"팔이 아파서 가방을 못 들어요.","exFr":"J'ai mal au bras, je ne peux pas porter le sac.","note":"aussi : huit (8)"},"1780695436487":{"ex":"오래 걸어서 다리가 아파요.","exFr":"J'ai mal aux jambes d'avoir marché longtemps.","note":"aussi : pont"},"1780695436488":{"ex":"어제 넘어져서 무릎을 다쳤어요.","exFr":"Hier, je suis tombé et je me suis blessé au genou.","note":"prononcé [무릅]"},"1780695436489":{"ex":"등이 아파서 잘 못 잤어요.","exFr":"J'avais mal au dos, j'ai mal dormi.","note":"aussi : « etc. » (사과, 배 등)"},"1780695436490":{"ex":"오래 앉아 있으면 허리가 아파요.","exFr":"Si je reste assis longtemps, j'ai mal aux reins.","note":"bas du dos / reins. Haut du dos : 등"},"1780695436491":{"ex":"손가락에 예쁜 반지를 꼈어요.","exFr":"Je porte une jolie bague au doigt."},"1780695436492":{"ex":"발가락을 다쳐서 못 걸어요.","exFr":"Je me suis blessé à l'orteil, je ne peux pas marcher."},"1780695436494":{"ex":"머리카락이 너무 길어서 잘랐어요.","exFr":"Mes cheveux étaient trop longs, alors je les ai coupés.","note":"머리 seul suffit souvent"},"1780695436541":{"ex":"학교까지 반 시간 정도 걸려요.","exFr":"Il faut environ une demi-heure jusqu'à l'école.","note":"plus courant : 삼십 분"},"1763107206765":{"ex":"요즘 한국 드라마를 자주 봐요.","exFr":"Ces temps-ci, je regarde souvent des séries coréennes.","note":"Emprunt à l'anglais « drama » = série télé"},"1763263585543":{"ex":"이 도서관은 정말 조용해요.","exFr":"Cette bibliothèque est vraiment calme.","note":"Personne : réservé, discret ; lieu : silencieux","conj":"조용해요 · 조용했어요"},"1763263625684":{"ex":"제 친구는 정말 말이 많아요.","exFr":"Mon ami est vraiment bavard.","note":"Litt. « avoir beaucoup de paroles »","conj":"말이 많아요 · 말이 많았어요"},"1763263652312":{"ex":"우리 아버지는 말이 없어요.","exFr":"Mon père est taciturne.","note":"Contraire de 말이 많다 (bavard)","conj":"말이 없어요 · 말이 없었어요"},"1763263712224":{"ex":"제 동생은 아주 활발해요.","exFr":"Mon petit frère est très dynamique.","conj":"활발해요 · 활발했어요"},"1763263776331":{"ex":"저는 주말에 조금 게을러요.","exFr":"Le week-end, je suis un peu paresseux.","note":"르 irrégulier : 게을러요","conj":"게을러요 · 게을렀어요"},"1763263804544":{"ex":"이 영화는 정말 재미없어요.","exFr":"Ce film est vraiment ennuyeux.","conj":"재미없어요 · 재미없었어요"},"1763263829317":{"ex":"한국어 공부는 정말 재미있어요.","exFr":"Étudier le coréen est vraiment intéressant.","conj":"재미있어요 · 재미있었어요"},"1763263882172":{"ex":"그 아이는 아주 얌전해요.","exFr":"Cet enfant est très sage.","conj":"얌전해요 · 얌전했어요"},"1763263907958":{"ex":"제 여동생은 정말 똑똑해요.","exFr":"Ma petite sœur est vraiment intelligente.","conj":"똑똑해요 · 똑똑했어요"},"1763263998342":{"ex":"저는 키가 조금 작아요.","exFr":"Je suis un peu petit.","note":"키 = la taille ; sans 키, 작다 = petit (objet)","conj":"키가 작아요 · 키가 작았어요"},"1763264016503":{"ex":"제 형은 키가 아주 커요.","exFr":"Mon grand frère est très grand.","note":"크다 est irrégulier : 커요, 컸어요","conj":"키가 커요 · 키가 컸어요"},"1763264039889":{"ex":"그 배우는 아주 날씬해요.","exFr":"Cet acteur est très mince.","note":"Positif (svelte) ; 마르다 = maigre (plutôt négatif)","conj":"날씬해요 · 날씬했어요"},"1763264058525":{"ex":"그 아기는 통통하고 귀여워요.","exFr":"Ce bébé est potelé et mignon.","note":"Affectueux ; moins fort que 뚱뚱하다 (gros)","conj":"통통해요 · 통통했어요"},"1763264106708":{"ex":"이 강아지는 정말 귀여워요.","exFr":"Ce chiot est vraiment mignon.","note":"ㅂ irrégulier : 귀여워요, 귀여웠어요","conj":"귀여워요 · 귀여웠어요"},"1763264158785":{"ex":"그 배우는 정말 멋있어요.","exFr":"Cet acteur a vraiment la classe.","note":"≠ 맛있다 (délicieux) ! Une syllabe change tout","conj":"멋있어요 · 멋있었어요"},"1763264199156":{"ex":"그 남자 배우는 좀 못생겼어요.","exFr":"Cet acteur est un peu laid.","note":"Forme passée à sens présent : 못생겼어요 = il est laid","conj":"못생겼어요 · 못생겼어요"},"1763264244332":{"ex":"제 친구는 정말 잘생겼어요.","exFr":"Mon ami est vraiment beau.","note":"Forme passée à sens présent ; contraire : 못생겼다","conj":"잘생겼어요 · 잘생겼어요"},"1763264266171":{"ex":"우리 고양이는 조금 뚱뚱해요.","exFr":"Notre chat est un peu gros.","note":"Assez direct pour une personne ; 통통하다 est plus doux","conj":"뚱뚱해요 · 뚱뚱했어요"},"1763264524282":{"ex":"저는 지수하고 아주 친해요.","exFr":"Je suis très proche de Jisoo.","note":"≠ 친절하다 (gentil, aimable)","conj":"친해요 · 친했어요"},"1763264776998":{"ex":"어제 친구들하고 노래방에 갔어요.","exFr":"Hier, je suis allé au karaoké avec des amis.","note":"노래 (chanson) + 방 (salle)"},"1763264906465":{"ex":"그 이야기가 정말 웃겨요.","exFr":"Cette histoire est vraiment drôle.","note":"웃다 = rire ; 웃기다 = faire rire, être drôle","conj":"웃겨요 · 웃겼어요"},"1763265703951":{"ex":"저는 아침마다 공원에서 운동해요.","exFr":"Je fais de l'exercice au parc tous les matins.","conj":"운동해요 · 운동했어요"},"1763265747210":{"ex":"제 동생은 아직 학생이에요.","exFr":"Mon petit frère est encore étudiant.","note":"대학생 = étudiant à l'université"},"1763266263823":{"ex":"제 삼촌은 유명한 변호사예요.","exFr":"Mon oncle est un avocat célèbre.","note":"-사 : suffixe de métiers (의사, 요리사, 간호사)"},"1763266322884":{"ex":"의사 선생님, 머리가 너무 아파요.","exFr":"Docteur, j'ai très mal à la tête.","note":"On s'adresse au médecin par 의사 선생님"},"1763266347918":{"ex":"저는 그 가수의 팬이에요.","exFr":"Je suis fan de ce chanteur."},"1763266915695":{"ex":"주말에 동생하고 게임을 해요.","exFr":"Le week-end, je joue à des jeux vidéo avec mon petit frère.","note":"게임하다 = jouer à un jeu (vidéo)"},"1765435938082":{"ex":"한국어 교과서를 매일 읽어요.","exFr":"Je lis mon manuel de coréen tous les jours."},"1765436356686":{"ex":"우리 선생님은 아주 친절해요.","exFr":"Notre professeur est très gentil.","note":"-님 honorifique ; aussi titre poli pour un inconnu"},"1779724539683":{"ex":"아버지는 큰 회사에서 일해요.","exFr":"Mon père travaille dans une grande entreprise.","note":"회사에 다녀요 = je travaille en entreprise (usuel)"},"1779724539684":{"ex":"그 직원이 저를 많이 도와줬어요.","exFr":"Cet employé m'a beaucoup aidé."},"1779724539686":{"ex":"오후 두 시에 회의가 있어요.","exFr":"Il y a une réunion à deux heures de l'après-midi.","note":"≠ 회사 (entreprise) ; 회의하다 = être en réunion"},"1779724539691":{"ex":"저는 한국 음악을 자주 들어요.","exFr":"J'écoute souvent de la musique coréenne.","note":"음악을 듣다 → 들어요 (ㄷ irrégulier)"},"1779724539692":{"ex":"노래방에서 한국 노래를 불렀어요.","exFr":"J'ai chanté des chansons coréennes au karaoké.","note":"노래를 부르다 = chanter une chanson"},"1779724539694":{"ex":"무슨 스포츠를 제일 좋아해요?","exFr":"Quel sport préférez-vous ?","note":"Pratiquer : plutôt 운동(하다) ; regarder : 스포츠"},"1780695436495":{"ex":"저는 회사원이고 서울에서 일해요.","exFr":"Je suis employé de bureau et je travaille à Séoul.","note":"회사 (entreprise) + 원 (membre)"},"1780695436496":{"ex":"제 친구는 병원에서 간호사로 일해요.","exFr":"Mon amie travaille comme infirmière à l'hôpital."},"1780695436497":{"ex":"경찰관이 길을 가르쳐 줬어요.","exFr":"Le policier m'a indiqué le chemin.","note":"Souvent abrégé en 경찰"},"1780695436498":{"ex":"그 식당 요리사는 아주 유명해요.","exFr":"Le cuisinier de ce restaurant est très célèbre."},"1780695436499":{"ex":"그 가수는 노래를 정말 잘해요.","exFr":"Ce chanteur chante vraiment bien."},"1780695436500":{"ex":"버스 운전사가 문을 열어 줬어요.","exFr":"Le chauffeur du bus m'a ouvert la porte.","note":"운전기사(님) est plus poli ; 운전하다 = conduire"},"1780695436501":{"ex":"점원한테 옷 사이즈를 물어봤어요.","exFr":"J'ai demandé la taille du vêtement au vendeur.","note":"Employé de magasin ; plus général : 직원"},"1780695436502":{"ex":"제 사촌은 지금 군인이에요.","exFr":"Mon cousin est actuellement militaire.","note":"Service militaire obligatoire en Corée → mot très courant"},"1763106836914":{"ex":"안녕하세요, 요즘 잘 지냈어요?","exFr":"Bonjour, vous allez bien ces derniers temps ?"},"1763107123324":{"ex":"한국어를 조금 할 수 있어요.","exFr":"Je sais parler un peu coréen.","note":"Forme contractée à l'oral : 좀"},"1763264462134":{"ex":"주말에 혼자 있으면 심심해요.","exFr":"Le week-end, quand je suis seul, je m'ennuie.","note":"S'ennuyer (rien à faire) ≠ 지루하다 (qqch est ennuyeux)","conj":"심심해요 · 심심했어요"},"1763264670423":{"ex":"그 아이는 미소가 정말 예뻐요.","exFr":"Cet enfant a un très joli sourire.","note":"微笑. 미소를 짓다 = sourire (verbe). ≠ 웃다 (rire)"},"1763265087096":{"ex":"매일 한국어를 열심히 공부해요.","exFr":"J'étudie le coréen sérieusement tous les jours."},"1763266607347":{"ex":"새 운동화를 신고 공원에서 뛰었어요.","exFr":"J'ai couru au parc avec mes nouvelles baskets.","note":"運動靴 : 운동 (sport) + 화 (chaussure). Avec 신다"},"1763266756138":{"ex":"엄마 생일에 꽃을 샀어요.","exFr":"J'ai acheté des fleurs pour l'anniversaire de maman.","note":"꽃이 피다 = fleurir. Prononcé [꼳]"},"1764056874528":{"ex":"동생은 야채를 싫어해요.","exFr":"Mon petit frère n'aime pas les légumes.","note":"≠ 싫다 : 저는 야채가 싫어요 (même sens, autre structure)","conj":"싫어해요 · 싫어했어요"},"1764057708329":{"ex":"전화번호 좀 가르쳐 주세요.","exFr":"Donnez-moi votre numéro de téléphone, s'il vous plaît.","note":"番號. 전화번호 = numéro de téléphone"},"1765763755913":{"ex":"아빠는 항상 일찍 일어나요.","exFr":"Papa se lève toujours tôt.","note":"恒常. = 늘, 언제나"},"1779561510761":{"ex":"가게에서 계산하고 영수증을 받았어요.","exFr":"J'ai payé au magasin et reçu le ticket.","note":"領收證"},"1779561565090":{"ex":"우리는 계산을 따로 했어요.","exFr":"Nous avons payé séparément.","note":"≠ 같이 (ensemble)"},"1779561613981":{"ex":"딸에게 곰 인형을 사 줬어요.","exFr":"J'ai acheté un ours en peluche à ma fille.","note":"人形. 곰 인형 = peluche"},"1779561925954":{"ex":"이 상품은 지금 할인 중이에요.","exFr":"Ce produit est en promotion en ce moment.","note":"商品"},"1779641064974":{"ex":"동물원에서 코끼리를 처음 봤어요.","exFr":"J'ai vu un éléphant pour la première fois au zoo."},"1779641121409":{"ex":"늦어서 정말 미안해요.","exFr":"Je suis vraiment désolé d'être en retard.","note":"Plus formel : 죄송하다","conj":"미안해요 · 미안했어요"},"1779706066047":{"ex":"지갑에 돈이 하나도 없어요.","exFr":"Je n'ai pas un sou dans mon portefeuille.","note":"돈을 벌다 = gagner de l'argent"},"1779706066048":{"ex":"여기 카드로 계산해도 돼요?","exFr":"Je peux payer par carte ici ?","note":"카드로 = par carte (particule -로)"},"1779706066049":{"ex":"현금이 없어서 카드로 냈어요.","exFr":"Je n'avais pas d'espèces, alors j'ai payé par carte.","note":"現金. 내다 = payer"},"1779706066050":{"ex":"어제 버스에서 지갑을 잃어버렸어요.","exFr":"Hier, j'ai perdu mon portefeuille dans le bus."},"1779706066051":{"ex":"이 가방은 너무 비싸요.","exFr":"Ce sac est trop cher.","note":"≠ 싸다 (bon marché)","conj":"비싸요 · 비쌌어요"},"1779706066052":{"ex":"시장 과일이 마트보다 싸요.","exFr":"Les fruits du marché sont moins chers qu'au supermarché.","note":"≠ 비싸다. Aussi : emballer (짐을 싸다)","conj":"싸요 · 쌌어요"},"1779706066053":{"ex":"학생은 할인을 받을 수 있어요.","exFr":"Les étudiants peuvent bénéficier d'une réduction.","note":"割引. 할인하다 = faire une remise"},"1779706066055":{"ex":"이 바지를 입어 봐도 돼요?","exFr":"Je peux essayer ce pantalon ?","note":"V-아/어 보다 = essayer de faire","conj":"입어 봐요 · 입어 봤어요"},"1779706066056":{"ex":"다 먹었어요. 계산해 주세요.","exFr":"On a terminé. L'addition, s'il vous plaît.","note":"計算. Littéralement « calculer »","conj":"계산해요 · 계산했어요"},"1779706066152":{"ex":"지금 못 가요. 왜냐하면 일이 있기 때문이에요.","exFr":"Je ne peux pas venir maintenant, parce que j'ai du travail.","note":"Se termine par -기 때문이에요 ou -(으)니까요"},"1779706066153":{"ex":"학교까지 버스 또는 지하철을 타세요.","exFr":"Prenez le bus ou le métro jusqu'à l'école.","note":"Plutôt écrit. À l'oral : -(이)나"},"1779706066154":{"ex":"먼저 손을 씻고 밥을 먹어요.","exFr":"D'abord on se lave les mains, puis on mange."},"1779706066156":{"ex":"그 영화가 좋아서 또 봤어요.","exFr":"Ce film m'a plu, alors je l'ai regardé encore une fois.","note":"≠ 더 (plus, davantage)"},"1779706066158":{"ex":"실례합니다, 화장실이 어디에 있어요?","exFr":"Excusez-moi, où sont les toilettes ?","note":"Pour aborder qqn. ≠ 죄송합니다 (s'excuser d'une faute)"},"1779706066159":{"ex":"괜찮아요, 큰 문제가 아니에요.","exFr":"Ce n'est pas grave, ce n'est pas un gros problème.","note":"Aussi : « ça va » et refus poli (« non merci »)"},"1779706066160":{"ex":"너무 빨라서 이해 못 해요.","exFr":"C'est trop rapide, je ne comprends pas."},"1779706066162":{"ex":"잘 못 들었어요. 천천히 말해 주세요.","exFr":"Je n'ai pas bien entendu. Parlez lentement, s'il vous plaît."},"1779706066163":{"ex":"죄송해요, 그 사람 이름을 몰라요.","exFr":"Désolé, je ne connais pas le nom de cette personne.","note":"Dictionnaire : 모르다 (르 irrég. : 몰라요/몰랐어요)"},"1779706066164":{"ex":"네, 그 가게를 잘 알아요.","exFr":"Oui, je connais bien ce magasin.","note":"Dictionnaire : 알다. ≠ 몰라요"},"1779706066165":{"ex":"선생님, 질문이 하나 있어요.","exFr":"Professeur, j'ai une question.","note":"質問. ≠ 문제 (problème)"},"1780695436366":{"ex":"백화점에서 옷을 많이 샀어요.","exFr":"J'ai acheté beaucoup de vêtements au grand magasin.","note":"옷을 입다 = s'habiller. Prononcé [옫]"},"1780695436367":{"ex":"이 바지는 저한테 좀 길어요.","exFr":"Ce pantalon est un peu long pour moi.","note":"반바지 = short"},"1780695436368":{"ex":"여름에는 치마를 자주 입어요.","exFr":"En été, je porte souvent des jupes."},"1780695436369":{"ex":"오늘은 흰색 티셔츠를 입었어요.","exFr":"Aujourd'hui, j'ai mis un tee-shirt blanc."},"1780695436370":{"ex":"회사에 갈 때 셔츠를 입어요.","exFr":"Je mets une chemise pour aller au travail.","note":"≠ 티셔츠 (tee-shirt)"},"1780695436371":{"ex":"겨울에는 따뜻한 코트가 필요해요.","exFr":"En hiver, il faut un manteau chaud."},"1780695436372":{"ex":"좀 추워서 재킷을 입었어요.","exFr":"Il faisait un peu froid, alors j'ai mis une veste."},"1780695436373":{"ex":"햇빛이 강해서 모자를 썼어요.","exFr":"Le soleil tapait fort, j'ai mis un chapeau.","note":"帽子. Avec le verbe 쓰다"},"1780695436374":{"ex":"추워서 두꺼운 양말을 신었어요.","exFr":"Il faisait froid, j'ai mis des chaussettes épaisses.","note":"洋襪. Avec le verbe 신다"},"1780695436375":{"ex":"집에 들어갈 때 신발을 벗어요.","exFr":"On enlève ses chaussures en entrant dans la maison.","note":"Avec 신다 / 벗다"},"1780695436379":{"ex":"파티에서 예쁜 원피스를 입었어요.","exFr":"J'ai porté une jolie robe à la fête.","note":"Konglish « one-piece »"},"1780695436380":{"ex":"주말에는 편한 청바지를 입어요.","exFr":"Le week-end, je porte un jean confortable.","note":"청 (bleu 靑) + 바지 (pantalon)"},"1780695436381":{"ex":"추워서 코트를 입었어요.","exFr":"Il faisait froid, j'ai mis un manteau.","note":"Vêtements sur le corps. Tête : 쓰다, pieds : 신다","conj":"입어요 · 입었어요"},"1780695436382":{"ex":"더워서 재킷을 벗었어요.","exFr":"J'avais chaud, j'ai enlevé ma veste.","note":"Contraire de 입다, 신다, 쓰다 et 끼다","conj":"벗어요 · 벗었어요"},"1780695436383":{"ex":"오늘은 새 운동화를 신었어요.","exFr":"Aujourd'hui, j'ai mis mes nouvelles baskets.","note":"Chaussures, chaussettes. ≠ 신나다 (être excité)","conj":"신어요 · 신었어요"},"1780695436384":{"ex":"밖에 나갈 때 모자를 써요.","exFr":"Je mets un chapeau quand je sors.","note":"Aussi : écrire, utiliser. 으 irrég. : 써요","conj":"써요 · 썼어요"},"1780695436385":{"ex":"추워서 장갑을 꼈어요.","exFr":"Il faisait froid, j'ai mis des gants.","note":"Gants, bague ; lunettes : 끼다 ou 쓰다","conj":"껴요 · 꼈어요"},"1780695436387":{"ex":"영화가 슬퍼서 많이 울었어요.","exFr":"Le film était triste, j'ai beaucoup pleuré.","note":"으 irrég. : 슬퍼요","conj":"슬퍼요 · 슬펐어요"},"1780695436388":{"ex":"가족하고 같이 있으면 행복해요.","exFr":"Je suis heureux quand je suis avec ma famille.","note":"幸福","conj":"행복해요 · 행복했어요"},"1780695436389":{"ex":"친구가 약속을 안 지켜서 화났어요.","exFr":"Je me suis fâché parce que mon ami n'a pas tenu sa promesse.","note":"화(가) 나다. Souvent au passé : 화났어요","conj":"화나요 · 화났어요"},"1780695436390":{"ex":"밤에 혼자 걸으면 무서워요.","exFr":"J'ai peur quand je marche seul la nuit.","note":"ㅂ irrég. ≠ 무겁다 (lourd)","conj":"무서워요 · 무서웠어요"},"1780695436391":{"ex":"엄마는 항상 제 건강을 걱정해요.","exFr":"Maman s'inquiète toujours pour ma santé.","note":"걱정하지 마세요 = ne vous inquiétez pas","conj":"걱정해요 · 걱정했어요"},"1780695436400":{"ex":"나는 매일 아침 커피를 마셔.","exFr":"Moi, je bois un café tous les matins.","note":"Informel (phrase en 반말). En poli : 저. 나 + 가 → 내가"},"1780695436401":{"ex":"저는 프랑스에서 왔어요.","exFr":"Je viens de France.","note":"≠ 저 (ce...là-bas). 저 + 가 → 제가"},"1780695436402":{"ex":"너는 지금 어디에 있어?","exFr":"Toi, tu es où en ce moment ?","note":"반말 uniquement (phrase en 반말). 너 + 가 → 네가 [니가]"},"1780695436403":{"ex":"우리 내일 같이 점심 먹어요.","exFr":"Déjeunons ensemble demain.","note":"Aussi possessif affectif : 우리 엄마, 우리 집"},"1780695436404":{"ex":"저희 가게에 어서 오세요.","exFr":"Bienvenue dans notre boutique.","note":"Forme humble de 우리 (envers client, supérieur)"},"1780695436405":{"ex":"이 책은 정말 재미있어요.","exFr":"Ce livre-ci est vraiment intéressant.","note":"Proche du locuteur. Toujours suivi d'un nom"},"1780695436406":{"ex":"그 사람을 잘 알아요?","exFr":"Vous connaissez bien cette personne ?","note":"Proche de l'interlocuteur, ou déjà mentionné"},"1780695436407":{"ex":"저 건물이 우리 학교예요.","exFr":"Ce bâtiment là-bas, c'est notre école.","note":"Loin des deux. ≠ 저 (je, poli)"},"1780695436408":{"ex":"이거 하나 주세요. 얼마예요?","exFr":"Donnez-moi celui-ci. C'est combien ?","note":"Contraction orale de 이것"},"1780695436409":{"ex":"그거 어디에서 샀어요?","exFr":"Tu as acheté ça où ?","note":"Contraction orale de 그것"},"1780695436410":{"ex":"저거 좀 보여 주세요.","exFr":"Montrez-moi celui-là-bas, s'il vous plaît.","note":"Contraction orale de 저것"},"1780695436411":{"ex":"죄송하지만 여기에 앉아도 돼요?","exFr":"Excusez-moi, je peux m'asseoir ici ?"},"1780695436412":{"ex":"거기 날씨는 요즘 어때요?","exFr":"Quel temps fait-il là-bas ces jours-ci ?","note":"Près de l'interlocuteur / lieu déjà mentionné"},"1780695436413":{"ex":"화장실은 저기 문 옆에 있어요.","exFr":"Les toilettes sont là-bas, à côté de la porte.","note":"저기요! = pour appeler un serveur, un inconnu"},"1780695436414":{"ex":"책이 책상 위에 있어요.","exFr":"Le livre est sur le bureau."},"1780695436415":{"ex":"가방은 의자 아래에 있어요.","exFr":"Le sac est sous la chaise.","note":"≈ 밑에"},"1780695436416":{"ex":"고양이가 침대 밑에 있어요.","exFr":"Le chat est sous le lit.","note":"≈ 아래에, plutôt « juste en dessous »"},"1780695436417":{"ex":"학교 앞에서 친구를 기다렸어요.","exFr":"J'ai attendu mon ami devant l'école."},"1780695436418":{"ex":"집 뒤에 작은 공원이 있어요.","exFr":"Il y a un petit parc derrière la maison."},"1780695436419":{"ex":"은행은 병원 옆에 있어요.","exFr":"La banque est à côté de l'hôpital."},"1780695436420":{"ex":"지갑은 가방 안에 있어요.","exFr":"Le portefeuille est dans le sac."},"1780695436421":{"ex":"아이들이 밖에서 놀고 있어요.","exFr":"Les enfants sont en train de jouer dehors.","note":"≠ N + 밖에 + négation (= seulement)"},"1780695436422":{"ex":"은행은 학교와 병원 사이에 있어요.","exFr":"La banque est entre l'école et l'hôpital."},"1780695436424":{"ex":"집 근처에 큰 공원이 있어요.","exFr":"Il y a un grand parc près de chez moi.","note":"近處"},"1780695436425":{"ex":"우리 집 개는 아주 커요.","exFr":"Notre chien est très grand.","note":"≠ 개 (compteur d'objets : 한 개)"},"1780695436426":{"ex":"고양이가 소파 위에서 자요.","exFr":"Le chat dort sur le canapé."},"1780695436427":{"ex":"아침에 새 소리를 들었어요.","exFr":"Le matin, j'ai entendu les oiseaux chanter.","note":"≠ 새 (nouveau : 새 옷)"},"1780695436428":{"ex":"바다에는 물고기가 많아요.","exFr":"Il y a beaucoup de poissons dans la mer.","note":"[물꼬기]. ≠ 생선 (poisson comme aliment)"},"1780695436429":{"ex":"작년에 제주도에서 말을 탔어요.","exFr":"L'année dernière, j'ai fait du cheval à Jeju.","note":"≠ 말 (parole). 말을 타다 = monter à cheval"},"1780695436430":{"ex":"소가 풀을 먹고 있어요.","exFr":"La vache est en train de brouter.","note":"소고기 = bœuf (viande)"},"1780695436431":{"ex":"농장에 돼지가 세 마리 있어요.","exFr":"Il y a trois cochons à la ferme.","note":"돼지고기 = porc. ≠ 강아지 (chiot)"},"1780695436432":{"ex":"시골에서는 닭이 아침마다 울어요.","exFr":"À la campagne, le coq chante tous les matins.","note":"Prononcé [닥]. 닭고기 = poulet (viande)"},"1780695436433":{"ex":"토끼는 귀가 아주 길어요.","exFr":"Le lapin a de très longues oreilles."},"1780695436434":{"ex":"산에서 곰을 만나면 정말 위험해요.","exFr":"Rencontrer un ours en montagne, c'est vraiment dangereux.","note":"곰 인형 = ours en peluche"},"1780695436435":{"ex":"호랑이는 한국에서 유명한 동물이에요.","exFr":"Le tigre est un animal célèbre en Corée."},"1780695436452":{"ex":"주말에 보통 뭐 해요?","exFr":"Que faites-vous d'habitude le week-end ?","note":"普通. Aussi adjectif : ordinaire, moyen"},"1780695436454":{"ex":"저는 술을 전혀 안 마셔요.","exFr":"Je ne bois pas du tout d'alcool.","note":"Toujours avec une négation (안, 못, 없다…)"},"1780695436455":{"ex":"이 영화는 별로 재미없어요.","exFr":"Ce film n'est pas très intéressant.","note":"Avec négation. Seul, à l'oral : « bof »"},"1780695436457":{"ex":"오늘은 날씨가 매우 추워요.","exFr":"Aujourd'hui, il fait très froid.","note":"Plus formel/écrit que 아주, 너무"},"1780695436458":{"ex":"물 좀 더 주세요.","exFr":"Encore un peu d'eau, s'il vous plaît.","note":"≠ 덜 (moins). 더 크다 = plus grand"},"1780695436459":{"ex":"과일 중에서 사과를 제일 좋아해요.","exFr":"Parmi les fruits, c'est la pomme que je préfère.","note":"第一. = 가장"},"1780695436460":{"ex":"어제 저녁을 너무 많이 먹었어요.","exFr":"Hier, j'ai trop mangé au dîner.","note":"Adverbe de 많다. Prononcé [마니]"},"1780695436461":{"ex":"시간이 없어요. 빨리 오세요!","exFr":"On n'a pas le temps. Venez vite !","note":"Adverbe de 빠르다. 빨리빨리! = vite vite !"},"1780695436463":{"ex":"어젯밤에 늦게 잤어요.","exFr":"Hier soir, je me suis couché tard.","note":"≠ 일찍 (tôt). De 늦다"},"1780695436475":{"ex":"감기에 걸려서 학교에 못 갔어요.","exFr":"J'avais un rhume, je n'ai pas pu aller à l'école.","note":"Incapacité. ≠ 안 (choix de ne pas faire)"},"1780695436529":{"ex":"내일 친구하고 약속이 있어요.","exFr":"Demain, j'ai un rendez-vous avec un ami.","note":"約束. 약속을 지키다 = tenir sa promesse"},"1780695436533":{"ex":"지난 주말에 친구를 만났어요.","exFr":"J'ai vu un ami le week-end dernier.","note":"親舊. 친한 친구 = ami proche"},"1780695436534":{"ex":"이 문제는 너무 어려워요.","exFr":"Ce problème est trop difficile.","note":"問題. Aussi : question d'exercice, d'examen"},"1780695436535":{"ex":"이 질문의 답을 알아요?","exFr":"Tu connais la réponse à cette question ?","note":"答. 대답하다 = répondre"},"1780695436536":{"ex":"선생님 말을 잘 들으세요.","exFr":"Écoutez bien ce que dit le professeur.","note":"≠ 말 (cheval). 말하다 = parler"},"1780695436538":{"ex":"이것은 제 것이 아니에요.","exFr":"Ceci n'est pas à moi.","note":"Oral : 거. 제 것 = le mien"},"1780695436539":{"ex":"어릴 때 부산에 살았어요.","exFr":"Quand j'étais petit, j'habitais à Busan.","note":"V-(으)ㄹ 때 = quand, au moment où"},"pack-65a1d5a7":{"ex":"저는 제 아들이 정말 자랑스러워요.","exFr":"Je suis très fier de mon fils.","conj":"자랑스러워요 · 자랑스러웠어요","note":"≠ 자랑하다 (se vanter, du deck) : ici on ressent la fierté. Irrégulier ㅂ."},"pack-2cbea727":{"ex":"동생이 형을 많이 질투해요.","exFr":"Le petit frère est très jaloux de son grand frère.","conj":"질투해요 · 질투했어요","note":"Jalousie hostile ; ≠ 부럽다 (du deck), envie sans hostilité."},"pack-c131d6e0":{"ex":"어제 도와줘서 정말 고마워요.","exFr":"Merci beaucoup pour ton aide d'hier.","conj":"고마워요 · 고마웠어요","note":"Plus chaleureux que 감사하다 mais toujours poli en -요 ; irrégulier ㅂ."},"pack-d6257cc6":{"ex":"저는 미워하는 사람이 없어요.","exFr":"Je ne déteste personne.","conj":"미워해요 · 미워했어요","note":"Pour les personnes ; ≠ 싫어하다 (du deck) pour choses/activités."},"pack-6625e79e":{"ex":"친구가 연락이 없어서 서운했어요.","exFr":"J'étais vexé que mon ami ne donne pas de nouvelles.","conj":"서운해요 · 서운했어요","note":"Déception affective envers un proche ; ≠ 실망하다 (du deck)."},"pack-9d782896":{"ex":"시험을 못 봐서 너무 속상해요.","exFr":"Je suis très contrarié d'avoir raté l'examen.","conj":"속상해요 · 속상했어요","note":"Peine causée par une situation ; 서운하다 = déçu par une personne."},"pack-dbd22206":{"ex":"길에서 넘어져서 정말 창피했어요.","exFr":"J'ai eu très honte de tomber dans la rue.","conj":"창피해요 · 창피했어요","note":"Honte publique ; ≠ 부끄럽다 (du deck), timidité/gêne intérieure."},"pack-2b1e88da":{"ex":"제 잘못이 아니라서 억울해요.","exFr":"Ce n'est pas ma faute, c'est injuste.","conj":"억울해요 · 억울했어요","note":"Sentiment très coréen : être traité ou accusé injustement."},"pack-0f56ef2b":{"ex":"여행 전날이라서 마음이 설레요.","exFr":"C'est la veille du voyage, j'ai le cœur qui bat.","conj":"설레요 · 설렜어요","note":"설레다 est la forme standard — 설레이다/설레여요 est une faute fréquente."},"pack-b68453b9":{"ex":"그 사람을 보자마자 반했어요.","exFr":"Je suis tombé sous le charme dès que je l'ai vu.","conj":"반해요 · 반했어요","note":"Se construit avec 에게/한테 ; 첫눈에 반하다 = coup de foudre au premier regard."},"pack-c77cd378":{"ex":"주말 여행을 정말 기대하고 있어요.","exFr":"J'attends vraiment le voyage du week-end avec impatience.","conj":"기대해요 · 기대했어요","note":"기대돼요 = « j'ai hâte », très courant à l'oral."},"pack-d43eb2c5":{"ex":"비가 와서 기분이 우울해요.","exFr":"Il pleut, je me sens déprimé.","conj":"우울해요 · 우울했어요","note":"hanja 憂鬱 ; 우울증 = dépression (maladie)."},"pack-eb309195":{"ex":"두 사람은 사귄 지 일 년 됐어요.","exFr":"Ça fait un an qu'ils sortent ensemble.","conj":"사귀어요 · 사귀었어요","note":"Aussi se faire des amis : 친구를 사귀다. 사귀어요 ne se contracte pas (사겨요 est fautif)."},"pack-a7ea4baf":{"ex":"두 사람은 지난달에 헤어졌어요.","exFr":"Ils se sont séparés le mois dernier.","conj":"헤어져요 · 헤어졌어요","note":"Aussi se quitter en fin de rencontre, selon le contexte."},"pack-a5a44dd1":{"ex":"언니가 내년 봄에 결혼해요.","exFr":"Ma grande sœur se marie au printemps prochain.","conj":"결혼해요 · 결혼했어요","note":"결혼했어요 = aussi « je suis marié » (état)."},"pack-7935c6d6":{"ex":"그 부부는 작년에 이혼했어요.","exFr":"Ce couple a divorcé l'année dernière.","conj":"이혼해요 · 이혼했어요"},"pack-065ce56c":{"ex":"친구를 집에 초대하고 싶어요.","exFr":"Je veux inviter un ami à la maison.","conj":"초대해요 · 초대했어요"},"pack-f9e25cb2":{"ex":"싸운 친구와 어제 화해했어요.","exFr":"Je me suis réconcilié hier avec l'ami avec qui je m'étais disputé.","conj":"화해해요 · 화해했어요"},"pack-a7e4a518":{"ex":"우리는 친구의 결혼을 축하해 줬어요.","exFr":"Nous avons félicité notre ami pour son mariage.","conj":"축하해요 · 축하했어요","note":"Féliciter un événement ; ≠ 칭찬하다 (du deck), complimenter. Souvent 축하해 주다."},"pack-3f16eed5":{"ex":"제가 먼저 친구에게 사과했어요.","exFr":"Je me suis excusé le premier auprès de mon ami.","conj":"사과해요 · 사과했어요","note":"Homonyme de 사과 pomme (du deck) — hanja 謝過."},"pack-a99ad3ec":{"ex":"이번 한 번만 용서해 주세요.","exFr":"Pardonnez-moi juste pour cette fois.","conj":"용서해요 · 용서했어요"},"pack-97e22c7f":{"ex":"우는 친구를 따뜻하게 위로해 줬어요.","exFr":"J'ai réconforté chaleureusement mon ami qui pleurait.","conj":"위로해요 · 위로했어요","note":"Souvent au bénéfactif : 위로해 주다."},"pack-3152c04b":{"ex":"어제 좋아하는 사람한테 고백했어요.","exFr":"Hier, j'ai avoué mes sentiments à la personne qui me plaît.","conj":"고백해요 · 고백했어요","note":"고백받다 = recevoir une déclaration."},"pack-7392fa5d":{"ex":"친구에게 제 동생을 소개했어요.","exFr":"J'ai présenté mon petit frère à mon ami.","conj":"소개해요 · 소개했어요","note":"≠ 소개팅 (du deck), rencontre arrangée entre célibataires."},"pack-696c5550":{"ex":"한국에 도착하면 바로 연락할게요.","exFr":"Je te contacte dès que j'arrive en Corée.","conj":"연락해요 · 연락했어요","note":"연락할게요 = je te tiens au courant. Prononcé [열라카다]."},"pack-355b937c":{"ex":"회사 선배가 점심을 사 줬어요.","exFr":"Un aîné de mon entreprise m'a offert le déjeuner.","note":"hanja 先輩 ; relation clé en Corée (école, travail)."},"pack-e2e453d6":{"ex":"오늘 후배들과 같이 저녁을 먹었어요.","exFr":"Aujourd'hui j'ai dîné avec mes cadets.","note":"Contraire de 선배 ; hanja 後輩."},"pack-0be36396":{"ex":"애인이랑 같이 여행을 가고 싶어요.","exFr":"Je veux partir en voyage avec mon amoureux.","note":"Neutre ; les jeunes disent plutôt 남자 친구 / 여자 친구."},"pack-51c6244c":{"ex":"그 부부는 정말 행복해 보여요.","exFr":"Ce couple a l'air vraiment heureux.","note":"hanja 夫婦 ; 신혼부부 = jeunes mariés."},"pack-11a42896":{"ex":"저는 회사 동료들과 잘 어울려요.","exFr":"Je m'entends bien avec mes collègues.","conj":"어울려요 · 어울렸어요","note":"Aussi « aller bien » : 이 옷이 잘 어울려요."},"pack-893b73d3":{"ex":"작은 일로 친구와 다퉜어요.","exFr":"Je me suis disputé avec un ami pour une petite chose.","conj":"다퉈요 · 다퉜어요","note":"Dispute verbale légère ; 싸우다 (du deck) est plus fort."},"pack-5b4a76fe":{"ex":"언니가 항상 저를 잘 챙겨 줘요.","exFr":"Ma grande sœur prend toujours bien soin de moi.","conj":"챙겨요 · 챙겼어요","note":"Aussi prendre (ne pas oublier) : 우산 챙기세요! = n'oublie pas ton parapluie."},"pack-029f07be":{"note":"En retrouvant quelqu'un ; présent 보고 싶어요 = tu me manques."},"pack-5fe75dde":{"note":"Se dit après une première rencontre sympathique ; aussi 앞으로 친하게 지내요."},"pack-fae51070":{"note":"사다 = offrir (payer) ; 밥 살게요 = je t'invite à manger."},"pack-970676ea":{"note":"말을 놓다 = passer au 반말 ; à l'oral souvent contracté en 말 놔도 돼요?"},"pack-d7facf33":{"ex":"저는 공항에서 돈을 환전했어요.","exFr":"J'ai changé de l'argent à l'aéroport.","conj":"환전해요 · 환전했어요","note":"Hanja 換錢 ; 환전소 = bureau de change."},"pack-c443d5f9":{"ex":"오늘 환율이 어떻게 돼요?","exFr":"Quel est le taux de change aujourd'hui ?","note":"Prononcé [화뉼]."},"pack-c29ee147":{"ex":"편의점 현금인출기에서 돈을 찾았어요.","exFr":"J'ai retiré de l'argent au distributeur de la supérette.","note":"En Corée, on dit aussi simplement ATM ; 돈을 찾다 = retirer de l'argent."},"pack-76897e2c":{"ex":"오만 원짜리 지폐 있어요?","exFr":"Vous avez un billet de 50 000 wons ?","note":"≠ 표 (billet de spectacle/transport, dans le deck) ; -짜리 = « de la valeur de »."},"pack-c2367923":{"ex":"주머니에 동전이 많이 있어요.","exFr":"J'ai beaucoup de pièces dans ma poche."},"pack-fa7ff697":{"ex":"죄송하지만 지금 잔돈이 없어요.","exFr":"Désolé, je n'ai pas de monnaie sur moi.","note":"S'emploie aussi pour la monnaie rendue : 잔돈은 됐어요 = gardez la monnaie."},"pack-34f036ed":{"ex":"여기는 환전 수수료가 얼마예요?","exFr":"Ici, à combien s'élèvent les frais de change ?"},"pack-dda3e012":{"ex":"은행에서 새 계좌를 만들었어요.","exFr":"J'ai ouvert un nouveau compte à la banque.","note":"계좌 이체 = virement bancaire."},"pack-64f279d3":{"ex":"저기 3번 창구로 가세요.","exFr":"Allez au guichet numéro 3 là-bas."},"pack-a03d55e5":{"ex":"번호표를 뽑고 자리에 앉았어요.","exFr":"J'ai pris un ticket et me suis assis.","note":"번호표를 뽑다 = prendre un ticket (banque, mairie...)."},"pack-9d9dc6f0":{"ex":"사람들이 줄을 서서 기다려요.","exFr":"Les gens attendent en faisant la queue.","conj":"줄을 서요 · 줄을 섰어요","note":"줄 = file d'attente ; ≠ 줄다 (diminuer, dans le deck)."},"pack-dcaf814f":{"ex":"드디어 제 차례가 됐어요.","exFr":"C'est enfin mon tour.","note":"차례를 기다리다 = attendre son tour."},"pack-dc4cc2de":{"ex":"신분증 좀 보여 주시겠어요?","exFr":"Pourriez-vous me montrer votre pièce d'identité ?"},"pack-1e9f1e2d":{"ex":"이 서류에 서명해 주세요.","exFr":"Signez ce document, s'il vous plaît.","conj":"서명해요 · 서명했어요","note":"À l'oral, on dit souvent 사인하다."},"pack-0e134df6":{"ex":"이 신청서를 작성해 주세요.","exFr":"Remplissez ce formulaire, s'il vous plaît.","conj":"작성해요 · 작성했어요","note":"신청서 = formulaire de demande."},"pack-f46803d7":{"ex":"어제 새 카드를 발급받았어요.","exFr":"Hier, on m'a délivré une nouvelle carte.","conj":"발급받아요 · 발급받았어요","note":"L'administration 발급하다 (délivre), l'usager 발급받다 (reçoit)."},"pack-538a7ced":{"ex":"교통사고를 보고 경찰에 신고했어요.","exFr":"J'ai vu un accident de la route et je l'ai signalé à la police.","conj":"신고해요 · 신고했어요","note":"경찰에 신고하다 = prévenir la police."},"pack-8b2f4f88":{"ex":"짐을 물품 보관함에 넣었어요.","exFr":"J'ai mis mes bagages à la consigne.","note":"Casiers en libre-service dans les gares et le métro."},"pack-41344122":{"ex":"분실물 센터에 전화해 보세요.","exFr":"Appelez le bureau des objets trouvés.","note":"분실물 센터 = bureau des objets trouvés (dans le métro, souvent 유실물 센터)."},"pack-abb46777":{"ex":"우체국에서 우표를 두 장 샀어요.","exFr":"J'ai acheté deux timbres à la poste."},"pack-6239c6bd":{"ex":"프랑스로 소포를 보내고 싶어요.","exFr":"Je voudrais envoyer un colis en France.","note":"Colis envoyé par la poste ; ≠ 택배 (livraison à domicile)."},"pack-06a5309a":{"ex":"택배가 아직 안 왔어요.","exFr":"Le colis n'est pas encore arrivé.","note":"Omniprésent en Corée ; 택배 기사 = livreur."},"pack-5ac82d2f":{"ex":"어제 우체국에서 편지를 부쳤어요.","exFr":"Hier, j'ai posté une lettre au bureau de poste.","conj":"부쳐요 · 부쳤어요","note":"Homophone de 붙이다 (coller) — attention à l'orthographe."},"pack-5968efb3":{"ex":"지도를 보고 길을 찾았어요.","exFr":"J'ai trouvé le chemin en regardant le plan."},"pack-d3487038":{"ex":"시청 앞에서 친구를 만났어요.","exFr":"J'ai retrouvé un ami devant la mairie.","note":"Aussi le nom d'une station de métro centrale à Séoul."},"pack-e95aab63":{"ex":"이 근처에 경찰서가 있어요?","exFr":"Y a-t-il un commissariat près d'ici ?","note":"경찰서 = le lieu ; 경찰관 (deck) = le policier."},"pack-2f7b196e":{"ex":"여권을 잃어버리면 대사관에 가세요.","exFr":"Si vous perdez votre passeport, allez à l'ambassade."},"pack-ff7e5667":{"ex":"관광 안내소에서 지도를 받았어요.","exFr":"J'ai reçu un plan au bureau d'information touristique."},"pack-94c21ffd":{"ex":"횡단보도에서 길을 건너야 해요.","exFr":"Il faut traverser la rue au passage piéton."},"pack-f5df4812":{"ex":"신호등이 파란불로 바뀌면 건너세요.","exFr":"Traversez quand le feu passe au vert.","note":"파란불 = feu vert (litt. « bleu ») ; 빨간불 = feu rouge."},"pack-c15b3b4d":{"ex":"충전기를 호텔에 두고 왔어요.","exFr":"J'ai laissé mon chargeur à l'hôtel.","note":"충전하다 + -기 « appareil », comme 번역기."},"pack-535f9b87":{"ex":"지금 배터리를 충전해야 돼요.","exFr":"Je dois recharger la batterie maintenant.","conj":"충전해요 · 충전했어요","note":"Sert aussi pour recharger une carte de transport (T-money)."},"pack-4143f257":{"ex":"이 방에 콘센트가 있어요?","exFr":"Il y a une prise dans cette chambre ?","note":"Konglish — en anglais on dit « outlet »."},"pack-3a7c4e8c":{"ex":"이 케이블이 너무 짧아요.","exFr":"Ce câble est trop court.","note":"충전 케이블 = câble de charge."},"pack-43c786f1":{"ex":"휴대폰 화면이 너무 어두워요.","exFr":"L'écran du téléphone est trop sombre.","note":"L'écran du téléphone se dit 화면 ; 스크린 = écran de cinéma."},"pack-053d5241":{"ex":"지도 앱을 자주 써요.","exFr":"J'utilise souvent l'application de cartes.","note":"Abréviation de 애플리케이션 ; à l'oral aussi 어플."},"pack-615212b2":{"ex":"어제 새 계정을 만들었어요.","exFr":"J'ai créé un nouveau compte hier.","note":"Compte internet ; le compte bancaire se dit 계좌."},"pack-81973897":{"ex":"비밀번호를 또 잊어버렸어요.","exFr":"J'ai encore oublié mon mot de passe.","note":"비밀 (secret) + 번호 (numéro) ; aussi le code PIN."},"pack-5671f790":{"ex":"먼저 이 앱에 로그인하세요.","exFr":"Connectez-vous d'abord à cette application.","conj":"로그인해요 · 로그인했어요","note":"Contraire : 로그아웃하다."},"pack-16c2d1de":{"ex":"이 앱을 무료로 다운받았어요.","exFr":"J'ai téléchargé cette application gratuitement.","conj":"다운받아요 · 다운받았어요","note":"Le plus courant à l'oral ; plus formel : 다운로드하다."},"pack-0c6de345":{"ex":"이번 달 데이터를 다 썼어요.","exFr":"J'ai utilisé toutes mes données ce mois-ci.","note":"En Corée, désigne surtout l'internet mobile du forfait."},"pack-cc22c352":{"ex":"공항에서 새 유심을 샀어요.","exFr":"J'ai acheté une nouvelle carte SIM à l'aéroport.","note":"De « USIM » ; on dit aussi 유심 칩."},"pack-32fba427":{"ex":"큐알 코드를 찍으면 메뉴가 나와요.","exFr":"Si on scanne le code QR, le menu apparaît.","note":"Souvent écrit « QR 코드 » ; scanner = 찍다, comme pour une photo."},"pack-8f020225":{"ex":"인터넷에서 좋은 식당을 검색했어요.","exFr":"J'ai cherché un bon restaurant sur internet.","conj":"검색해요 · 검색했어요"},"pack-2f24b754":{"ex":"와이파이에 연결할 수 없어요.","exFr":"Je n'arrive pas à me connecter au wifi.","conj":"연결해요 · 연결했어요"},"pack-b80b76da":{"ex":"어제 번역 앱을 설치했어요.","exFr":"J'ai installé une application de traduction hier.","conj":"설치해요 · 설치했어요"},"pack-4af23872":{"ex":"사진을 실수로 다 삭제했어요.","exFr":"J'ai supprimé toutes les photos par erreur.","conj":"삭제해요 · 삭제했어요","note":"À l'oral on dit souvent 지우다 (effacer)."},"pack-1461445f":{"ex":"제 전화번호를 저장해 주세요.","exFr":"Enregistrez mon numéro de téléphone, s'il vous plaît.","conj":"저장해요 · 저장했어요"},"pack-9b319be2":{"ex":"어제 휴대폰이 고장 났어요.","exFr":"Mon téléphone est tombé en panne hier.","conj":"고장 나요 · 고장 났어요","note":"Surtout au passé : 고장 났어요 = c'est en panne."},"pack-0f2b8f13":{"ex":"이 화면을 고칠 수 있어요?","exFr":"Pouvez-vous réparer cet écran ?","conj":"고쳐요 · 고쳤어요","note":"Aussi : corriger (une erreur, une habitude)."},"pack-03be7d4a":{"ex":"시작하려면 이 버튼을 누르세요.","exFr":"Pour commencer, appuyez sur ce bouton.","conj":"눌러요 · 눌렀어요","note":"Irrégulier 르."},"pack-f565c713":{"ex":"부모님하고 영상 통화를 했어요.","exFr":"J'ai fait un appel vidéo avec mes parents.","note":"통화 = appel téléphonique ; verbe : 영상 통화하다."},"pack-d82acd5c":{"ex":"번역기로 한국어 메뉴를 읽었어요.","exFr":"J'ai lu le menu coréen avec un traducteur.","note":"번역 = traduction (écrit) ; 통역 = interprétation (oral)."},"pack-e29d147e":{"ex":"밤에는 알림을 다 꺼요.","exFr":"La nuit, je coupe toutes les notifications.","note":"De 알리다 (faire savoir) ; 알림을 끄다 = couper les notifs."},"pack-00f190c0":{"note":"돼요 = ça marche / c'est disponible ; tournure très courante."},"pack-6c78ed73":{"note":"안 되다 = ne pas fonctionner ; ≠ 인터넷이 느려요 (lent)."},"pack-f4be02d1":{"ex":"넘어져서 무릎에서 피가 나요.","exFr":"Je suis tombé et mon genou saigne.","note":"피가 나다 = saigner. ≠ 피부 (peau)."},"pack-83f54f2f":{"ex":"겨울에는 피부가 너무 건조해요.","exFr":"En hiver, ma peau est très sèche."},"pack-91e4b0dc":{"ex":"무릎에 작은 상처가 났어요.","exFr":"Je me suis fait une petite plaie au genou.","note":"상처가 나다 = se faire une plaie."},"pack-7480c473":{"ex":"뜨거운 물에 손을 데었어요.","exFr":"Je me suis brûlé la main avec de l'eau chaude.","conj":"데어요 · 데었어요","note":"'데였어요', courant à l'oral, est fautif — la forme correcte est 데었어요."},"pack-b95f56e3":{"ex":"어제부터 발목이 많이 부었어요.","exFr":"Ma cheville est très gonflée depuis hier.","conj":"부어요 · 부었어요","note":"Irrégulier ㅅ : le ㅅ tombe devant voyelle → 부어요. Homonyme de 붓다 (verser), même irrégularité."},"pack-5101c310":{"ex":"알약을 하루에 두 번 먹어요.","exFr":"Je prends des comprimés deux fois par jour.","note":"알 = grain. ≠ 약 (médicament en général). Prononcé [알략]."},"pack-c350b884":{"ex":"상처에 연고를 발랐어요.","exFr":"J'ai mis de la pommade sur la plaie.","note":"S'applique avec 바르다 (irrégulier 르) : 연고를 발라요."},"pack-197947a3":{"ex":"다친 손가락에 반창고를 붙였어요.","exFr":"J'ai mis un pansement sur mon doigt blessé.","note":"À l'oral souvent 밴드 (de Band-Aid). Se met avec 붙이다 (coller)."},"pack-715a6fb2":{"ex":"지하철에서는 마스크를 꼭 써요.","exFr":"Dans le métro, je porte toujours un masque.","note":"Se porte avec 쓰다, comme les lunettes."},"pack-c5253240":{"ex":"간호사가 제 체온을 쟀어요.","exFr":"L'infirmière a pris ma température.","note":"Hanja 體溫. 체온을 재다 = prendre la température (재다 → 쟀어요)."},"pack-15189549":{"ex":"출발 전에 여행자 보험에 들었어요.","exFr":"J'ai pris une assurance voyage avant de partir.","note":"보험에 들다 = souscrire une assurance. 여행자 보험 = assurance voyage, 건강 보험 = assurance maladie."},"pack-b45ccec2":{"ex":"먼지 때문에 계속 재채기해요.","exFr":"J'éternue sans arrêt à cause de la poussière.","conj":"재채기해요 · 재채기했어요","note":"Aussi très courant : 재채기가 나다."},"pack-b0ec68a1":{"ex":"아침부터 두통이 너무 심해요.","exFr":"J'ai un fort mal de tête depuis ce matin.","note":"Hanja 頭痛. À l'oral plutôt 머리가 아파요 ; 두통 sur les boîtes de médicaments (두통약)."},"pack-61c31c42":{"ex":"몸살이 나서 회사에 못 갔어요.","exFr":"J'avais un état grippal, je n'ai pas pu aller au travail.","note":"Fatigue + courbatures, concept très coréen. 몸살이 나다 ; souvent combiné : 몸살감기."},"pack-c7c86bed":{"ex":"감기에 걸려서 콧물이 나요.","exFr":"J'ai un rhume et le nez qui coule.","note":"콧물이 나다 = avoir le nez qui coule. 코 + ㅅ + 물, prononcé [콘물]."},"pack-be67aac9":{"ex":"병원에서 주사를 한 대 맞았어요.","exFr":"J'ai reçu une piqûre à l'hôpital.","note":"주사를 맞다 = recevoir une piqûre (litt. « se faire frapper »). Classificateur : 한 대."},"pack-444c5c14":{"ex":"배탈이 나서 아무것도 못 먹어요.","exFr":"J'ai le ventre dérangé, je ne peux rien manger.","note":"배탈이 나다 = avoir l'estomac dérangé (souvent après avoir mal mangé)."},"pack-165ca56c":{"ex":"버스에서 멀미가 나서 힘들었어요.","exFr":"J'ai eu le mal des transports dans le bus, c'était dur.","note":"멀미가 나다. 차멀미 (voiture), 뱃멀미 (bateau)."},"pack-332ba882":{"ex":"모기에 물려서 다리가 가려워요.","exFr":"Je me suis fait piquer par un moustique et ma jambe me démange.","conj":"가려워요 · 가려웠어요","note":"Irrégulier ㅂ : 가려워요. 모기에 물리다 = se faire piquer par un moustique."},"pack-9672aa9e":{"ex":"계단에서 넘어져서 발목을 삐었어요.","exFr":"Je suis tombé dans l'escalier et me suis foulé la cheville.","conj":"삐어요 · 삐었어요","note":"발목을 삐다 = se fouler la cheville."},"pack-6243a8e4":{"ex":"스키를 타다가 팔이 부러졌어요.","exFr":"Je me suis cassé le bras en faisant du ski.","conj":"부러져요 · 부러졌어요","note":"Intransitif : 팔이 부러졌어요 (mon bras s'est cassé)."},"pack-3d7bff1b":{"ex":"밤에 너무 아파서 응급실에 갔어요.","exFr":"J'avais très mal la nuit, je suis allé aux urgences."},"pack-e03e0774":{"ex":"병원에 환자가 정말 많았어요.","exFr":"Il y avait vraiment beaucoup de patients à l'hôpital."},"pack-3c1691b9":{"ex":"약국에서 약사에게 증상을 말했어요.","exFr":"À la pharmacie, j'ai décrit mes symptômes au pharmacien.","note":"≠ 약국 (la pharmacie, le lieu)."},"pack-e8379e03":{"note":"목 = le cou, mais aussi la gorge."},"pack-3802f9c2":{"note":"Les médicaments se « mangent » : 약을 먹다."},"pack-ea11f28d":{"note":"속 = l'intérieur (du corps) ; expression très courante. ≠ 배탈 (vrai dérangement intestinal)."},"pack-768e5d7a":{"note":"En Corée, le 119 = pompiers et ambulance."},"pack-6d059180":{"ex":"여름에는 날씨가 아주 습해요.","exFr":"En été, le temps est très humide.","conj":"습해요 · 습했어요","note":"≠ 건조하다 (sec) ; l'été coréen est chaud et humide"},"pack-fe58c588":{"ex":"겨울에는 공기가 아주 건조해요.","exFr":"En hiver, l'air est très sec.","conj":"건조해요 · 건조했어요","note":"≠ 습하다 (humide) ; pour l'air, la peau, le climat"},"pack-254e8d37":{"ex":"오늘 아침에 안개가 많이 꼈어요.","exFr":"Ce matin, il y avait beaucoup de brouillard.","note":"안개가 끼다 = il y a du brouillard (꼈어요 = 끼었어요 contracté)"},"pack-70e2e69d":{"ex":"천둥소리 때문에 잠을 못 잤어요.","exFr":"Je n'ai pas pu dormir à cause du tonnerre.","note":"천둥이 치다 = le tonnerre gronde ; 천둥소리 = bruit du tonnerre (soudé)"},"pack-4c2786f1":{"ex":"번개가 쳐서 정말 무서웠어요.","exFr":"Il y a eu des éclairs, j'ai eu très peur.","note":"번개가 치다 = il y a des éclairs"},"pack-e70debe2":{"ex":"비 온 뒤에 무지개가 떴어요.","exFr":"Après la pluie, un arc-en-ciel est apparu.","note":"무지개가 뜨다 = un arc-en-ciel apparaît"},"pack-9cd67a95":{"ex":"더워서 그늘에서 좀 쉬었어요.","exFr":"Il faisait chaud, je me suis reposé à l'ombre.","note":"Coin frais sans soleil ; ombre projetée (silhouette) = 그림자"},"pack-c8b58a7d":{"ex":"오늘은 햇빛이 너무 강해요.","exFr":"Aujourd'hui, la lumière du soleil est très forte.","note":"햇빛 = la lumière ; 햇볕 = la chaleur du soleil"},"pack-c6e98792":{"ex":"폭염 때문에 밖에 못 나가요.","exFr":"À cause de la canicule, je ne peux pas sortir.","note":"Hanja 暴炎 ; 폭염주의보 = alerte canicule"},"pack-5ed2015d":{"ex":"오후에 갑자기 소나기가 내렸어요.","exFr":"L'après-midi, une averse est soudain tombée.","note":"Pluie d'été soudaine et brève"},"pack-208085a9":{"ex":"가을에는 단풍이 정말 예뻐요.","exFr":"En automne, les feuilles colorées sont vraiment belles.","note":"단풍이 들다 = les feuilles se colorent ; 단풍 구경 = admirer les feuilles ; pic fin octobre"},"pack-a6fb7d1e":{"ex":"장마 때는 비가 매일 와요.","exFr":"Pendant la mousson, il pleut tous les jours.","note":"Fin juin–juillet en Corée ; 장마철 = période des pluies"},"pack-38fd921c":{"ex":"하늘에 구름이 하나도 없어요.","exFr":"Il n'y a aucun nuage dans le ciel.","note":"구름이 끼다 = le ciel se couvre"},"pack-c3c6d557":{"ex":"비가 오니까 우산을 가져가세요.","exFr":"Comme il pleut, prenez un parapluie.","note":"우산을 쓰다 = s'abriter sous son parapluie"},"pack-2ffcbcd3":{"ex":"오늘은 미세먼지가 아주 심해요.","exFr":"Aujourd'hui, les particules fines sont très fortes.","note":"Mot du quotidien en Corée, affiché dans toute appli météo"},"pack-919218ea":{"ex":"아침저녁으로 날씨가 좀 쌀쌀해요.","exFr":"Matin et soir, le temps est un peu frisquet.","conj":"쌀쌀해요 · 쌀쌀했어요","note":"Moins fort que 춥다 ; typique de l'automne"},"pack-43942b11":{"ex":"커피에 얼음을 넣어 주세요.","exFr":"Mettez des glaçons dans le café, s'il vous plaît.","note":"Dérivé de 얼다 (geler)"},"pack-f3b3cc88":{"ex":"길이 얼어서 아주 미끄러워요.","exFr":"La route est gelée et très glissante.","conj":"얼어요 · 얼었어요","note":"Verbe en ㄹ : le ㄹ tombe devant ㄴ/ㅂ/ㅅ (업니다, 어는) ; 길이/물이 얼다"},"pack-8b78f2f1":{"ex":"눈이 벌써 다 녹았어요.","exFr":"La neige a déjà entièrement fondu.","conj":"녹아요 · 녹았어요","note":"Intransitif ; faire fondre = 녹이다"},"pack-694d1a6d":{"ex":"눈이 와서 길이 미끄러워요.","exFr":"Il a neigé, la route est glissante.","conj":"미끄러워요 · 미끄러웠어요","note":"Irrégulier ㅂ, comme 춥다/덥다"},"pack-c9acceb6":{"ex":"비가 그치면 나갈 거예요.","exFr":"Quand la pluie s'arrêtera, je sortirai.","conj":"그쳐요 · 그쳤어요","note":"Surtout pour pluie, neige, larmes"},"pack-1b7a4fa1":{"ex":"오늘은 바람이 많이 불어요.","exFr":"Aujourd'hui, le vent souffle fort.","conj":"불어요 · 불었어요","note":"바람이 불다 = le vent souffle ; verbe en ㄹ (붑니다, 부는)"},"pack-d49b0c95":{"ex":"약속에 늦을 것 같아서 서둘렀어요.","exFr":"Je risquais d'être en retard au rendez-vous, alors je me suis dépêché.","conj":"서둘러요 · 서둘렀어요","note":"Irrégulier 르."},"pack-3a5a9631":{"ex":"오늘 아침에 학교에 늦었어요.","exFr":"Ce matin, je suis arrivé en retard à l'école.","conj":"늦어요 · 늦었어요","note":"늦게 = tard (adverbe)."},"pack-88aaee9d":{"ex":"출발 전에 표를 확인하세요.","exFr":"Vérifiez votre billet avant le départ.","conj":"확인해요 · 확인했어요","note":"Hanja 確認."},"pack-f5f65890":{"ex":"돈을 원으로 바꾸고 싶어요.","exFr":"Je voudrais changer de l'argent en wons.","conj":"바꿔요 · 바꿨어요","note":"Transitif. ≠ 바뀌다 (changer de soi-même)."},"pack-8d259b13":{"ex":"어제 지하철에서 지갑을 잃어버렸어요.","exFr":"Hier, j'ai perdu mon portefeuille dans le métro.","conj":"잃어버려요 · 잃어버렸어요","note":"≠ 잊어버리다 (oublier une information)."},"pack-b4e8a00e":{"ex":"친구 이름을 또 잊어버렸어요.","exFr":"J'ai encore oublié le nom de mon ami.","conj":"잊어버려요 · 잊어버렸어요","note":"≠ 잃어버리다 (perdre un objet)."},"pack-aa558a24":{"ex":"빌린 책을 내일 돌려줄게요.","exFr":"Je te rends demain le livre emprunté.","conj":"돌려줘요 · 돌려줬어요","note":"Rendre ce qu'on a emprunté (빌리다)."},"pack-6c5847bc":{"ex":"저는 약속을 꼭 지켜요.","exFr":"Je tiens toujours mes promesses.","conj":"지켜요 · 지켰어요","note":"약속을 지키다 ; aussi : protéger."},"pack-57f918b2":{"ex":"이 문은 미세요, 당기지 마세요.","exFr":"Cette porte, poussez-la, ne tirez pas.","conj":"밀어요 · 밀었어요","note":"Sur les portes : 미세요 = poussez (le ㄹ tombe devant -세요)."},"pack-8ec7f733":{"ex":"문이 안 열리면 당겨 보세요.","exFr":"Si la porte ne s'ouvre pas, essayez de tirer.","conj":"당겨요 · 당겼어요","note":"Sur les portes : 당기세요 = tirez."},"pack-8c10d668":{"ex":"우리 팀이 어제 경기에서 이겼어요.","exFr":"Notre équipe a gagné le match hier.","conj":"이겨요 · 이겼어요","note":"Contraire : 지다 (perdre un match)."},"pack-71483f5f":{"ex":"시합에서 져서 너무 슬펐어요.","exFr":"On a perdu le match, alors j'étais très triste.","conj":"져요 · 졌어요","note":"Contraire : 이기다. ≠ 잃어버리다 (perdre un objet)."},"pack-ce207cba":{"ex":"기사님, 여기서 세워 주세요.","exFr":"Monsieur, arrêtez-vous ici, s'il vous plaît.","conj":"세워요 · 세웠어요","note":"Indispensable en taxi ; aussi : garer."},"pack-8d9ef912":{"ex":"버스가 사람들로 가득 찼어요.","exFr":"Le bus était plein de monde.","conj":"가득 차요 · 가득 찼어요","note":"Souvent au passé : 가득 찼어요 = c'est plein."},"pack-407bef28":{"ex":"이 자리 비어 있어요?","exFr":"Cette place est-elle libre ?","conj":"비어요 · 비었어요","note":"État : 비어 있어요 = c'est vide/libre."},"pack-d819d53d":{"ex":"이 가방은 너무 무거워요.","exFr":"Ce sac est trop lourd.","conj":"무거워요 · 무거웠어요","note":"Irrégulier ㅂ. Contraire : 가볍다."},"pack-3cf114a1":{"ex":"이 노트북은 아주 가벼워요.","exFr":"Cet ordinateur portable est très léger.","conj":"가벼워요 · 가벼웠어요","note":"Irrégulier ㅂ. Contraire : 무겁다."},"pack-92377861":{"ex":"겨울에는 두꺼운 옷을 입어요.","exFr":"En hiver, on porte des vêtements épais.","conj":"두꺼워요 · 두꺼웠어요","note":"Irrégulier ㅂ. Contraire : 얇다."},"pack-92e5daa1":{"ex":"이 책은 얇아서 금방 읽을 수 있어요.","exFr":"Ce livre est fin, donc on peut le lire rapidement.","conj":"얇아요 · 얇았어요","note":"Régulier. Contraire : 두껍다 (épais)."},"pack-911e167f":{"ex":"이 방은 창문이 커서 밝아요.","exFr":"Cette chambre est claire car la fenêtre est grande.","conj":"밝아요 · 밝았어요","note":"Contraire : 어둡다 (sombre)."},"pack-baca6b00":{"ex":"새 집은 방이 아주 넓어요.","exFr":"Dans la nouvelle maison, la chambre est très spacieuse.","conj":"넓어요 · 넓었어요","note":"Contraire : 좁다 (étroit)."},"pack-05b39276":{"ex":"이 길은 좁아서 운전하기 어려워요.","exFr":"Cette rue est étroite, donc c'est difficile de conduire.","conj":"좁아요 · 좁았어요","note":"Contraire : 넓다 (spacieux)."},"pack-0990d1e0":{"ex":"호텔 방이 정말 깨끗했어요.","exFr":"La chambre d'hôtel était vraiment propre.","conj":"깨끗해요 · 깨끗했어요","note":"Contraire : 더럽다 (sale)."},"pack-287343db":{"ex":"그 식당 화장실이 좀 더러웠어요.","exFr":"Les toilettes de ce restaurant étaient un peu sales.","conj":"더러워요 · 더러웠어요","note":"Irrégulier ㅂ. Contraire : 깨끗하다."},"pack-6af7cceb":{"ex":"밖이 시끄러워서 잠을 못 잤어요.","exFr":"C'était bruyant dehors, alors je n'ai pas pu dormir.","conj":"시끄러워요 · 시끄러웠어요","note":"Irrégulier ㅂ. Contraire : 조용하다 (calme)."},"pack-8066dcb6":{"ex":"서울 지하철은 밤에도 안전해요.","exFr":"Le métro de Séoul est sûr même la nuit.","conj":"안전해요 · 안전했어요","note":"Hanja 安全. Contraire : 위험하다."},"pack-74319f04":{"ex":"밤에 혼자 다니면 위험해요.","exFr":"C'est dangereux de sortir seul la nuit.","conj":"위험해요 · 위험했어요","note":"Contraire : 안전하다 (sûr)."},"pack-52c419b2":{"ex":"이 의자는 너무 불편해요.","exFr":"Cette chaise est vraiment inconfortable.","conj":"불편해요 · 불편했어요","note":"Contraire : 편하다. Aussi : mal à l'aise."},"pack-39fc77ce":{"ex":"이 빵은 정말 부드러워요.","exFr":"Ce pain est vraiment moelleux.","conj":"부드러워요 · 부드러웠어요","note":"Irrégulier ㅂ ; aussi : moelleux, tendre."},"pack-32ab5071":{"ex":"호텔 침대가 너무 딱딱했어요.","exFr":"Le lit de l'hôtel était trop dur.","conj":"딱딱해요 · 딱딱했어요","note":"Contraire : 부드럽다 (doux)."},"pack-b9351c8e":{"ex":"형은 부지런해서 일찍 일어나요.","exFr":"Mon grand frère est assidu, il se lève tôt.","conj":"부지런해요 · 부지런했어요","note":"Contraire : 게으르다 (paresseux)."},"pack-268c5440":{"note":"제 생각에는… = « à mon avis » ; se place en tête de phrase."},"pack-96dd82ec":{"note":"동의하다 = être d'accord ; se construit avec ~에 (의견에 동의해요). Registre un peu plus formel que 저도 그렇게 생각해요."},"pack-fca5f1ad":{"note":"Désaccord poli très courant, plus doux que 반대예요."},"pack-67f4d498":{"note":"Refus adouci très parlé : 좀 + 아닌 것 같아요."},"pack-1000c645":{"note":"Contraire : 찬성이에요 (je suis pour)."},"pack-ecbbda03":{"note":"낫다 « être mieux » : irrégulier ㅅ (나아요) ; homonyme de 낫다 « guérir » du deck. 저거 = forme parlée de 저것."},"pack-19dc038a":{"note":"N1보다 N2가 더 좋아요 = je préfère N2 à N1."},"pack-8e991022":{"note":"V-는 게 어때요? = suggestion « et si on… ? »."},"pack-82e55e96":{"note":"N + 어때요? = demander un avis sur une chose (vs V-는 게 어때요? pour suggérer une action)."},"pack-60c78112":{"note":"-는 게 좋겠어요 = conseil doux : « il vaudrait mieux… »."},"pack-948fbf0e":{"note":"V-(으)ㄹ 만하다 = « valoir le coup de » : 가 볼 만해요, 먹어 볼 만해요."},"pack-f5c64b53":{"note":"Réponse passe-partout ; variante : 경우에 따라 달라요."},"pack-7b6741e3":{"note":"-(으)ㄹ지 고민이에요 = « je me demande quoi/si… » ; cf. 고민하다 du deck."},"pack-b264e708":{"note":"N(으)로 = « comme, en tant que » ici ; -(으)ㄹ까요? = sollicite l'avis."},"pack-7068b5ce":{"note":"글쎄요 = hésitation polie (« eh bien… je ne sais pas trop »)."},"pack-1c367981":{"note":"아마 + -(으)ㄹ 거예요 = probabilité (« sans doute, probablement »)."},"pack-b5bdabad":{"note":"-죠 (= -지요) : évidence partagée ; réponse type à une question évidente."},"pack-6cf06cfb":{"note":"Concession : on admet le point de l'autre avant de nuancer."},"pack-f3944c0b":{"note":"생각보다 = « que prévu, que je ne pensais »."},"pack-8dc9fa23":{"note":"별로 s'emploie normalement avec négation ; 별로예요 seul = « bof » (parlé)."},"pack-16cda8a7":{"note":"-지 않다 = négation longue ; jugement positif modéré."},"pack-12aa81c8":{"note":"마음에 들다 litt. « entrer dans le cœur » ; négation : 마음에 안 들어요."},"pack-877c4437":{"note":"아무거나 = n'importe lequel ; réponse fréquente à « tu veux manger quoi ? »."},"pack-7f8433ad":{"note":"솔직히 말하면 = « pour être honnête / franchement »."},"pack-bfd360c3":{"ex":"실례지만 어느 나라에서 왔어요?","exFr":"Excusez-moi, de quel pays venez-vous ?"},"pack-99e60e2e":{"ex":"조금 천천히 말씀해 주세요.","exFr":"Parlez un peu lentement, s'il vous plaît."},"pack-d4103ce9":{"ex":"이 국은 맛이 정말 좋아요.","exFr":"Cette soupe a vraiment bon goût.","note":"맛을 보다 = goûter ; 맛있다/맛없다 en dérivent."},"pack-e9247e79":{"ex":"밖에서 큰 소리가 났어요.","exFr":"Il y a eu un grand bruit dehors.","note":"소리가 나다 = faire du bruit ; 목소리 = voix. C'est le nom de l'app !"},"pack-67a1a230":{"ex":"부엌에서 좋은 냄새가 나요.","exFr":"Une bonne odeur vient de la cuisine.","note":"냄새가 나다 = ça sent ; 냄새를 맡다 = sentir (avec le nez)."},"pack-18751458":{"ex":"이 케이크는 모양이 예뻐요.","exFr":"Ce gâteau a une jolie forme.","note":"별 모양 = en forme d'étoile."},"pack-d22a806f":{"ex":"조용한 곳에서 쉬고 싶어요.","exFr":"Je veux me reposer dans un endroit calme.","note":"이곳 / 그곳 / 저곳 = ici / là / là-bas."},"pack-c4d9a41d":{"ex":"길에 사람이 정말 많아요.","exFr":"Il y a vraiment beaucoup de monde dans la rue.","note":"길을 잃다 = se perdre ; 길이 막히다 = il y a des bouchons."},"pack-8fcd1645":{"ex":"시계가 없어서 몇 시인지 몰라요.","exFr":"Comme je n'ai pas de montre, je ne sais pas quelle heure il est.","note":"손목시계 = montre-bracelet."},"pack-0f61a159":{"ex":"새 달력을 하나 샀어요.","exFr":"J'ai acheté un nouveau calendrier."},"pack-9928a7bc":{"ex":"친구에게 편지를 자주 써요.","exFr":"J'écris souvent des lettres à mon ami.","note":"편지를 쓰다 / 보내다 / 받다 = écrire / envoyer / recevoir une lettre."},"pack-9c52d809":{"ex":"이거 제 생일 선물이에요.","exFr":"C'est mon cadeau d'anniversaire.","note":"선물하다 = offrir ; 선물을 주다/받다 = donner/recevoir un cadeau."},"pack-e0d8b86a":{"ex":"카메라로 사진을 많이 찍었어요.","exFr":"J'ai pris beaucoup de photos avec l'appareil."},"pack-ba7e7e02":{"ex":"할아버지는 매일 신문을 읽으세요.","exFr":"Mon grand-père lit le journal tous les jours."},"pack-59debe59":{"ex":"어젯밤에 이상한 꿈을 꿨어요.","exFr":"J'ai fait un rêve étrange cette nuit.","note":"꿈을 꾸다 = faire un rêve ; aussi : rêve, ambition."},"pack-ef089ef7":{"ex":"요즘 힘이 하나도 없어요.","exFr":"Ces temps-ci, je n'ai aucune énergie.","note":"힘내세요! = Courage ! ; 힘들다 (être dur) en dérive."},"pack-749d1d3f":{"ex":"요즘 몸이 안 좋아요.","exFr":"Ces temps-ci, je ne suis pas en forme.","note":"몸이 안 좋다 = ne pas être bien (santé)."},"pack-3f45761d":{"ex":"지금은 마음이 아주 편해요.","exFr":"Maintenant, je me sens très serein.","note":"마음에 들다 = plaire ; 마음이 편하다 = être serein."},"pack-bde3fe0b":{"ex":"그 가수는 목소리가 좋아요.","exFr":"Ce chanteur a une belle voix.","note":"목 (gorge) + 소리 (son)."},"pack-10f776d3":{"ex":"다음 주 금요일이 제 생일이에요.","exFr":"Vendredi prochain, c'est mon anniversaire.","note":"생신 = anniversaire (honorifique, pour les aînés)."},"pack-a29c7fb4":{"ex":"저 남자는 키가 아주 커요.","exFr":"Cet homme est très grand.","note":"남자 친구 = petit ami."},"pack-e75d4ba8":{"ex":"그 여자는 머리가 길어요.","exFr":"Cette femme a les cheveux longs.","note":"여자 친구 = petite amie."},"pack-0e1241d2":{"ex":"어른 표 두 장 주세요.","exFr":"Deux billets adulte, s'il vous plaît.","note":"Désigne aussi les aînés qu'on respecte (어른들께 인사하세요)."},"pack-06e1cbe5":{"ex":"아저씨, 공항까지 가 주세요.","exFr":"Monsieur, à l'aéroport s'il vous plaît.","note":"Pour interpeller un homme mûr (commerçant) ; familier mais courant. Au taxi, 기사님 est plus poli."},"pack-63e6927e":{"ex":"아주머니, 이거 하나 얼마예요?","exFr":"Madame, combien coûte celui-ci ?","note":"아줌마 = plus familier ; au restaurant on dit souvent 이모님."},"pack-f7aa9bd9":{"ex":"오늘은 가게에 손님이 많아요.","exFr":"Aujourd'hui, il y a beaucoup de clients dans la boutique.","note":"Au taxi ou au magasin, on vous appellera 손님."},"pack-c9274950":{"ex":"가게 주인이 정말 친절해요.","exFr":"Le patron de la boutique est vraiment aimable.","note":"Pour s'adresser à lui directement, on dit 사장님."},"pack-5bd804b7":{"ex":"한국에는 요즘 외국인이 많아요.","exFr":"En Corée, il y a beaucoup d'étrangers ces temps-ci.","note":"외국 = pays étranger ; 외국어 = langue étrangère."},"pack-fb0483e3":{"ex":"제 취미는 사진 찍기예요.","exFr":"Mon passe-temps, c'est la photo.","note":"취미가 뭐예요? = quel est ton hobby ?"},"pack-e6cc255f":{"ex":"어제 친구랑 영화를 봤어요.","exFr":"Hier, j'ai vu un film avec un ami.","note":"영화를 보다 = voir un film ; 영화관 = cinéma."},"pack-8a512aa8":{"ex":"동생은 그림을 잘 그려요.","exFr":"Mon petit frère dessine bien.","note":"그림을 그리다 = dessiner / peindre."},"pack-4529c258":{"ex":"일요일마다 친구들과 축구를 해요.","exFr":"Tous les dimanches, je joue au foot avec des amis.","note":"축구하다 = jouer au foot."},"pack-e9a37b8b":{"ex":"주말에 가족과 등산을 갔어요.","exFr":"Le week-end, je suis allé en randonnée avec ma famille.","note":"Passe-temps national en Corée ; 등산하다 / 등산(을) 가다 = randonner."},"pack-a0264f75":{"ex":"여행 계획을 세우고 있어요.","exFr":"Je suis en train de faire des projets de voyage.","note":"계획을 세우다 = établir un plan."},"pack-14fac550":{"ex":"이 음식은 처음 먹어 봐요.","exFr":"C'est la première fois que je goûte ce plat.","note":"처음 뵙겠습니다 = enchanté (à la première rencontre)."},"pack-117bab80":{"ex":"여기에 주소를 써 주세요.","exFr":"Écrivez l'adresse ici, s'il vous plaît."},"pack-eaad482a":{"ex":"이 가게는 물건이 싸요.","exFr":"Dans ce magasin, les articles sont bon marché."},"pack-142a3028":{"ex":"가방 안에 책이 많아요.","exFr":"Il y a beaucoup de livres dans le sac."},"pack-06191684":{"ex":"매일 새 단어를 외워요.","exFr":"Chaque jour, j'apprends de nouveaux mots par cœur.","note":"단어를 외우다 = mémoriser un mot."},"pack-375263d4":{"ex":"이 말은 무슨 뜻이에요?","exFr":"Que veut dire ce mot ?","note":"무슨 뜻이에요? = qu'est-ce que ça veut dire ? (phrase de survie)."},"pack-05fd4f2e":{"ex":"학생이 선생님 질문에 대답해요.","exFr":"L'élève répond à la question du professeur.","conj":"대답해요 · 대답했어요","note":"질문에 대답하다 : « répondre à » se construit avec 에."},"pack-870d7d96":{"ex":"젓가락 좀 더 주세요.","exFr":"Des baguettes en plus, s'il vous plaît."},"pack-8db47c51":{"ex":"한국에서는 숟가락으로 밥을 먹어요.","exFr":"En Corée, on mange le riz à la cuillère.","note":"수저 = les couverts (cuillère + baguettes)."},"pack-99c4e647":{"ex":"내일 오전에 시간이 있어요?","exFr":"Tu as du temps demain matin ?","note":"오전 9시 = 9 h du matin ; opposé : 오후."},"pack-d2cf9622":{"ex":"오후 세 시에 만나요.","exFr":"On se voit à trois heures de l'après-midi."},"pack-3cab15cd":{"note":"Plus poli (à un aîné/inconnu) : 성함이 어떻게 되세요?"},"pack-f8073b89":{"note":"Littéralement « content de vous rencontrer » ; standard à la première rencontre. Plus formel : 만나서 반갑습니다."},"pack-d8992d83":{"note":"Formule figée formelle (entretien, présentation professionnelle) ; 뵙다 = forme humble de « rencontrer »."},"pack-06a4c246":{"note":"Intraduisible ; clôt une présentation ou une demande. Version douce : 잘 부탁해요."},"pack-a562ef7a":{"note":"Attention à l'orthographe : 오랜만 (pas 오랫만). Variante complète : 오래간만이에요."},"pack-c04057fb":{"note":"Au passé : demande des nouvelles depuis la dernière rencontre. À un aîné : 잘 지내셨어요?"},"pack-f02b26c6":{"note":"Réponse type à 잘 지냈어요? — au passé pour faire écho à la question. 덕분에 = « grâce à vous »."},"pack-c70b7f51":{"note":"LA réponse orale réelle à 감사합니다. Le 천만에요 des manuels ne se dit presque jamais dans la vraie vie."},"pack-921d651d":{"note":"실례지만 = formule polie pour aborder un inconnu. 뭐 좀 adoucit la demande."},"pack-cecb87d9":{"note":"À quelqu'un qui part ; variante 조심해서 가세요. Ne s'emploie que si l'autre s'en va."},"pack-4a371484":{"note":"Pour appeler un serveur ou un inconnu ; au restaurant on dit aussi 여기요! (« ici ! »)."},"pack-440fee91":{"note":"뜻 = sens, signification. Pour un mot précis : 이 단어가 무슨 뜻이에요?"},"pack-18f8fd21":{"note":"한국어로 = « en coréen » (particule -로 : moyen/langue). Avec l'objet : 이거 한국어로 뭐라고 해요?"},"pack-75215a66":{"note":"Adieu léger entre connaissances ; à l'oral très courant aussi : 다음에 또 봐요."},"pack-74a76afe":{"ex":"지금 상황이 조금 어려워요.","exFr":"La situation est un peu difficile en ce moment."},"pack-479ab3e8":{"ex":"이 일은 조건이 아주 좋아요.","exFr":"Ce travail a de très bonnes conditions.","note":"Prononcé [조껀]."},"pack-39b300c7":{"ex":"고를 때 기준이 뭐예요?","exFr":"Quel est ton critère quand tu choisis ?"},"pack-6bf537cb":{"ex":"이 수업의 대상은 아이들이에요.","exFr":"Le public de ce cours, ce sont les enfants.","note":"Souvent en composé : 초보자 대상 = destiné aux débutants."},"pack-e83ee00e":{"ex":"결과보다 과정이 더 중요해요.","exFr":"Le processus est plus important que le résultat."},"pack-e16b130b":{"ex":"사고의 원인을 아직 몰라요.","exFr":"On ne connaît pas encore la cause de l'accident.","note":"Cause objective d'un fait ; ≠ 이유 (raison, motif)."},"pack-ce49decb":{"ex":"이 약은 효과가 빨라요.","exFr":"Ce médicament fait vite effet.","note":"효과가 있다/없다 = être efficace / ne pas l'être. Prononcé [효과] ou [효꽈]."},"pack-1970ef0e":{"ex":"이 책은 읽을 가치가 있어요.","exFr":"Ce livre vaut la peine d'être lu.","note":"-(으)ㄹ 가치가 있다 = valoir la peine de."},"pack-2fbea43b":{"ex":"올해 목표는 한국어 공부예요.","exFr":"Mon objectif cette année, c'est étudier le coréen.","note":"Cible concrète à atteindre ; ≠ 목적 (intention)."},"pack-7467bef8":{"ex":"제 한국어 수준은 아직 낮아요.","exFr":"Mon niveau de coréen est encore bas."},"pack-feccdc2e":{"ex":"회의 전에 자료를 준비했어요.","exFr":"J'ai préparé les documents avant la réunion."},"pack-032e3f1f":{"ex":"인터넷에서 여행 정보를 찾았어요.","exFr":"J'ai cherché des infos de voyage sur Internet."},"pack-a7a073c6":{"ex":"그 나라는 교육 제도가 달라요.","exFr":"Le système éducatif de ce pays est différent."},"pack-9d7426d4":{"ex":"환경을 위한 새 정책이 필요해요.","exFr":"Il faut une nouvelle politique pour l'environnement.","note":"Mesures concrètes ; ≠ 정치 (la politique en général)."},"pack-08258474":{"ex":"부모님 세대는 생각이 달라요.","exFr":"La génération de mes parents pense différemment.","note":"세대 차이 = fossé des générations."},"pack-70fec2b5":{"ex":"이 지역은 겨울에 눈이 많이 와요.","exFr":"Dans cette région, il neige beaucoup en hiver."},"pack-b4de61be":{"ex":"이 호텔은 시설이 아주 좋아요.","exFr":"Cet hôtel a de très bons équipements."},"pack-5ab9da94":{"ex":"새 제품이 다음 달에 나와요.","exFr":"Le nouveau produit sort le mois prochain."},"pack-bf3949b6":{"ex":"기술이 정말 빨리 발전해요.","exFr":"La technologie progresse vraiment vite."},"pack-af309ab9":{"ex":"모든 사람은 쉴 권리가 있어요.","exFr":"Tout le monde a le droit de se reposer.","note":"-(으)ㄹ 권리가 있다 = avoir le droit de. Prononcé [궐리]."},"pack-64e030fa":{"ex":"세금을 내는 것은 국민의 의무예요.","exFr":"Payer les impôts est un devoir du citoyen."},"pack-f3f4087e":{"ex":"부모님의 역할이 정말 중요해요.","exFr":"Le rôle des parents est vraiment important.","note":"Prononcé [여칼]. 역할을 하다 = jouer un rôle."},"pack-5ba0495f":{"ex":"우리 회사에 큰 변화가 있었어요.","exFr":"Il y a eu un grand changement dans notre entreprise."},"pack-f4b6e42a":{"ex":"이 도시의 특징은 오래된 건물이 많다는 거예요.","exFr":"La particularité de cette ville, c'est qu'il y a beaucoup de vieux bâtiments."},"pack-64f6bb4e":{"ex":"책을 읽으면 지식이 늘어요.","exFr":"Lire des livres fait grandir les connaissances."},"pack-e4fa098a":{"ex":"게임을 시작하기 전에 규칙을 먼저 알아야 해요.","exFr":"Avant de commencer le jeu, il faut d'abord connaître les règles.","note":"규칙적으로 = régulièrement."},"pack-2926977b":{"ex":"차 상태가 아직 좋아요.","exFr":"La voiture est encore en bon état.","note":"État d'une chose/personne ; ≠ 상황 (circonstances)."},"pack-0fa1a4c6":{"ex":"한국의 전통 문화를 배우고 싶어요.","exFr":"Je veux apprendre la culture traditionnelle coréenne."},"pack-7a040b64":{"ex":"개인 정보를 잘 지켜야 해요.","exFr":"Il faut bien protéger ses données personnelles.","note":"개인 정보 = données personnelles ; 개인적으로 = personnellement."},"pack-98499364":{"ex":"어떤 분야에서 일하고 싶어요?","exFr":"Dans quel domaine veux-tu travailler ?"},"pack-7c3068b6":{"ex":"대통령은 국민의 말을 들어야 해요.","exFr":"Le président doit écouter le peuple.","note":"Citoyens d'un pays ; 시민 = citoyen d'une ville, civil. Prononcé [궁민]."},"pack-e84d8277":{"ex":"친구와 작은 갈등이 있었어요.","exFr":"J'ai eu un petit conflit avec un ami.","note":"Prononcé [갈뜽]."},"pack-a6902299":{"ex":"인터넷으로 기차 시간을 알아봤어요.","exFr":"J'ai vérifié les horaires de train sur Internet.","conj":"알아봐요 · 알아봤어요","note":"Aussi 'reconnaître qqn' : 저 알아보시겠어요?"},"pack-46ebf601":{"ex":"선생님 말씀을 다 알아들었어요.","exFr":"J'ai tout compris ce que le professeur a dit.","conj":"알아들어요 · 알아들었어요","note":"Irrégulier ㄷ (듣다 → 들어요). Très courant en négatif : 못 알아듣다."},"pack-52636988":{"ex":"제 실수를 뒤늦게 알아차렸어요.","exFr":"Je me suis rendu compte de mon erreur trop tard.","conj":"알아차려요 · 알아차렸어요","note":"Synonyme courant : 눈치채다 (deviner à des indices)."},"pack-e4221971":{"ex":"10년 만에 만난 친구를 몰라봤어요.","exFr":"Je n'ai pas reconnu mon ami que je revoyais après dix ans.","conj":"몰라봐요 · 몰라봤어요","note":"몰라보게 변했네요 = tu es méconnaissable (souvent un compliment)."},"pack-a25311bf":{"ex":"모르는 단어를 사전에서 찾아봤어요.","exFr":"J'ai cherché le mot inconnu dans le dictionnaire.","conj":"찾아봐요 · 찾아봤어요"},"pack-69689dc9":{"ex":"내일 제가 사무실로 찾아갈게요.","exFr":"Demain, je passerai vous voir au bureau.","conj":"찾아가요 · 찾아갔어요","note":"Honorifique très courant : 찾아뵙겠습니다 (je viendrai vous voir)."},"pack-72cc0ca7":{"ex":"친구가 갑자기 집에 찾아왔어요.","exFr":"Un ami est venu me voir à l'improviste.","conj":"찾아와요 · 찾아왔어요"},"pack-bd81b867":{"ex":"휴가 때 부산에 다녀왔어요.","exFr":"Pendant les vacances, j'ai fait un tour à Busan.","conj":"다녀와요 · 다녀왔어요","note":"다녀오겠습니다! = formule en quittant la maison."},"pack-a38dcb03":{"ex":"아픈 아이를 병원에 데려갔어요.","exFr":"J'ai emmené l'enfant malade à l'hôpital.","conj":"데려가요 · 데려갔어요","note":"Personnes/animaux ; pour un objet : 가져가다."},"pack-5a5357f3":{"ex":"어제 친구를 집에 데려왔어요.","exFr":"Hier, j'ai amené un ami à la maison.","conj":"데려와요 · 데려왔어요"},"pack-6c07bc5c":{"ex":"밤에 친구를 역까지 데려다줬어요.","exFr":"Le soir, j'ai raccompagné mon ami jusqu'à la gare.","conj":"데려다줘요 · 데려다줬어요","note":"집에 데려다줄게요 = je te raccompagne (très courant)."},"pack-5d6686eb":{"ex":"물 한 잔 가져다주시겠어요?","exFr":"Pourriez-vous m'apporter un verre d'eau ?","conj":"가져다줘요 · 가져다줬어요","note":"À l'oral souvent contracté en 갖다주다."},"pack-b16933ff":{"ex":"내년에 고향에 돌아갈 거예요.","exFr":"Je retournerai dans ma région natale l'an prochain.","conj":"돌아가요 · 돌아갔어요","note":"돌아가시다 = décéder (honorifique)."},"pack-a2ab5fbc":{"ex":"아빠가 밤늦게 집에 돌아왔어요.","exFr":"Papa est rentré tard le soir à la maison.","conj":"돌아와요 · 돌아왔어요"},"pack-9a6a0ca5":{"ex":"이 노래 한번 들어보세요.","exFr":"Écoutez donc cette chanson.","conj":"들어봐요 · 들어봤어요","note":"V + -아/어 보다 = essayer de faire. Base 듣다 (ㄷ irrégulier) : 들어-."},"pack-e06d11a6":{"ex":"모르는 게 있으면 물어보세요.","exFr":"Si vous avez une question, demandez-moi.","conj":"물어봐요 · 물어봤어요","note":"Plus doux que 묻다 ; standard à l'oral."},"pack-872e0339":{"ex":"출발 전에 지도를 잘 살펴봤어요.","exFr":"J'ai bien étudié la carte avant de partir.","conj":"살펴봐요 · 살펴봤어요"},"pack-594bf76e":{"ex":"가게에 들어가서 천천히 둘러봤어요.","exFr":"Je suis entré dans la boutique et j'ai fait le tour.","conj":"둘러봐요 · 둘러봤어요","note":"그냥 둘러볼게요 = je regarde seulement (en boutique)."},"pack-a3a1e725":{"ex":"버스가 방금 집 앞을 지나갔어요.","exFr":"Le bus vient de passer devant la maison.","conj":"지나가요 · 지나갔어요","note":"시간이 빨리 지나가요 = le temps passe vite. Le lieu traversé prend 을/를."},"pack-91cc264b":{"ex":"핸드폰을 보다가 내릴 역을 지나쳤어요.","exFr":"Je regardais mon téléphone et j'ai raté ma station.","conj":"지나쳐요 · 지나쳤어요","note":"지나치게 = trop, excessivement (de l'adjectif 지나치다)."},"pack-8ad93776":{"ex":"어려운 문제는 그냥 넘어갔어요.","exFr":"J'ai sauté les questions difficiles.","conj":"넘어가요 · 넘어갔어요","note":"그냥 넘어가요 = passons, laissons tomber."},"pack-ab4a3cf9":{"ex":"음식이 아직 안 나왔어요.","exFr":"Les plats ne sont pas encore arrivés.","conj":"나와요 · 나왔어요","note":"영화에 나오다 = apparaître dans un film."},"pack-0fed66f7":{"ex":"엘리베이터 대신 계단으로 내려갔어요.","exFr":"Je suis descendu par l'escalier au lieu de l'ascenseur.","conj":"내려가요 · 내려갔어요","note":"Paire : 내려오다 (descendre vers soi)."},"pack-ae3eac48":{"ex":"지난 주말에 산에 올라갔어요.","exFr":"Le week-end dernier, je suis monté à la montagne.","conj":"올라가요 · 올라갔어요","note":"값이 올라가요 = les prix montent. Paire : 올라오다."},"pack-1dacf2b8":{"ex":"집에 가는 길에 마트에 들렀어요.","exFr":"Je suis passé au supermarché en rentrant.","conj":"들러요 · 들렀어요","note":"Chute du ㅡ : 들러요/들렀어요. Ne pas confondre avec 들리다 (être entendu : 들려요) ni 듣다 (들어요)."},"pack-440cfbfd":{"ex":"제가 길을 모르니까 따라갈게요.","exFr":"Je ne connais pas le chemin, donc je vous suis.","conj":"따라가요 · 따라갔어요","note":"Paire : 따라오다 (suivre vers soi)."},"pack-0507e3d2":{"ex":"강아지가 집까지 계속 따라왔어요.","exFr":"Le chiot m'a suivi jusqu'à la maison.","conj":"따라와요 · 따라왔어요","note":"저를 따라오세요 = suivez-moi."},"pack-88668d30":{"ex":"시험이 점점 다가오고 있어요.","exFr":"L'examen approche petit à petit.","conj":"다가와요 · 다가왔어요"},"pack-9afcb512":{"ex":"집에 와서 옷을 갈아입었어요.","exFr":"En rentrant, je me suis changé.","conj":"갈아입어요 · 갈아입었어요","note":"갈아- = changer de : 갈아타다 (transport), 갈아입다 (habits)."},"pack-91dcda73":{"ex":"제가 공항에 마중 나갈게요.","exFr":"J'irai t'accueillir à l'aéroport.","conj":"마중 나가요 · 마중 나갔어요","note":"마중 s'écrit séparé du verbe. Contraire : 배웅하다 (accompagner au départ)."},"pack-5bf76e5c":{"ex":"기차역까지 친구를 배웅해 줬어요.","exFr":"J'ai accompagné mon ami jusqu'à la gare pour son départ.","conj":"배웅해요 · 배웅했어요","note":"Contraire : 마중 나가다 (aller accueillir). ≠ 데려다주다 (déposer qqn à destination)."},"pack-91709556":{"ex":"냉장고에서 물을 꺼내 주세요.","exFr":"Sors l'eau du frigo, s'il te plaît.","conj":"꺼내요 · 꺼냈어요","note":"이야기를 꺼내다 = aborder un sujet."},"pack-f3741a82":{"ex":"제 친구는 눈이 정말 높아요.","exFr":"Mon ami est vraiment exigeant.","conj":"눈이 높아요 · 눈이 높았어요","note":"Litt. « yeux hauts » — critères trop élevés, en amour ou dans ses goûts."},"pack-c74b11fb":{"ex":"할머니는 손이 커서 음식을 항상 많이 하세요.","exFr":"Grand-mère voit grand, elle prépare toujours beaucoup à manger.","conj":"손이 커요 · 손이 컸어요","note":"Litt. « grandes mains » — cuisine/donne toujours en grande quantité."},"pack-a97ee3f1":{"ex":"걱정 마세요, 저는 입이 무거워요.","exFr":"Ne vous inquiétez pas, je sais garder un secret.","conj":"입이 무거워요 · 입이 무거웠어요","note":"Litt. « bouche lourde » — discret. Contraire : 입이 가볍다."},"pack-0e2bc152":{"ex":"그 사람은 입이 가벼워서 비밀을 말하면 안 돼요.","exFr":"Il ne tient pas sa langue, ne lui dites pas de secret.","conj":"입이 가벼워요 · 입이 가벼웠어요","note":"Litt. « bouche légère » — indiscret, répète tout."},"pack-bff0e522":{"ex":"그 선배는 회사에서 발이 넓어요.","exFr":"Ce sunbae connaît tout le monde dans l'entreprise.","conj":"발이 넓어요 · 발이 넓었어요","note":"Litt. « pied large » — beaucoup de relations, bien introduit."},"pack-49d2ed3c":{"ex":"어제 두 시간이나 기다렸는데 바람을 맞았어요.","exFr":"Hier j'ai attendu deux heures : on m'a posé un lapin.","conj":"바람을 맞아요 · 바람을 맞았어요","note":"Litt. « recevoir le vent » — attendre pour rien. Poser un lapin à qqn = 바람을 맞히다."},"pack-f81fbdf6":{"ex":"요즘 일이 많아서 정신이 없어요.","exFr":"En ce moment j'ai trop de travail, je suis débordé.","conj":"정신이 없어요 · 정신이 없었어요","note":"Tête à l'envers, chaos ambiant — plus large que 눈코 뜰 새 없다 (pur manque de temps). Très courant : 정신없이 바빠요."},"pack-4bfaa609":{"ex":"제 동생은 눈치가 정말 빨라요.","exFr":"Mon petit frère capte tout très vite.","conj":"눈치가 빨라요 · 눈치가 빨랐어요","note":"눈치 = lire l'ambiance, concept clé coréen. Contraire : 눈치가 없다."},"pack-2942fc96":{"ex":"저는 회사에서 상사 눈치를 봐요.","exFr":"Au bureau, je guette l'humeur de mon chef.","conj":"눈치를 봐요 · 눈치를 봤어요","note":"Agir prudemment en surveillant la réaction/l'humeur des autres."},"pack-63c7c999":{"ex":"책을 읽느라 시간 가는 줄 몰랐어요.","exFr":"En lisant, je n'ai pas vu le temps passer.","conj":"시간 가는 줄 몰라요 · 시간 가는 줄 몰랐어요","note":"S'emploie presque toujours au passé, souvent avec -느라 : -느라 시간 가는 줄 몰랐어요."},"pack-e0313b60":{"ex":"동생은 귀가 얇아서 광고를 다 믿어요.","exFr":"Mon petit frère est influençable, il croit toutes les pubs.","conj":"귀가 얇아요 · 귀가 얇았어요","note":"Litt. « oreilles fines » — se laisse convaincre facilement."},"pack-72242c93":{"ex":"생일이니까 오늘은 제가 한턱낼게요.","exFr":"C'est mon anniversaire, aujourd'hui je régale.","conj":"한턱내요 · 한턱냈어요","note":"S'écrit en un mot (dictionnaire). Régaler pour fêter une bonne nouvelle. Fam. proche : 제가 쏠게요."},"pack-ff5363bd":{"ex":"어제 시장에서 바가지를 쓴 것 같아요.","exFr":"Je crois que je me suis fait arnaquer hier au marché.","conj":"바가지를 써요 · 바가지를 썼어요","note":"Litt. « se coiffer d'une calebasse » — payer bien trop cher. Arnaquer qqn = 바가지를 씌우다."},"pack-5a9fa96d":{"ex":"이번 주는 눈코 뜰 새 없이 바빠요.","exFr":"Cette semaine je suis débordé du matin au soir.","conj":"눈코 뜰 새 없어요 · 눈코 뜰 새 없었어요","note":"Litt. « pas le temps d'ouvrir yeux et nez » — pur manque de temps. Souvent : 눈코 뜰 새 없이 바빠요."},"pack-39d0631a":{"ex":"이 요리는 손이 많이 가요.","exFr":"Ce plat demande beaucoup de travail.","conj":"손이 많이 가요 · 손이 많이 갔어요","note":"Litt. « la main y va beaucoup » — exige temps et soin."},"pack-14d79aab":{"ex":"새 일을 맡아서 어깨가 무거워요.","exFr":"On m'a confié un nouveau travail, la responsabilité est lourde.","conj":"어깨가 무거워요 · 어깨가 무거웠어요","note":"Litt. « épaules lourdes » — le poids des responsabilités. Souvent avec 맡다 (se voir confier)."},"pack-b4a6ce1e":{"ex":"그 사람은 정말 얼굴이 두꺼워요.","exFr":"Cette personne a vraiment du culot.","conj":"얼굴이 두꺼워요 · 얼굴이 두꺼웠어요","note":"Litt. « visage épais » — effronté, insensible à la honte. Variante : 낯이 두껍다."},"pack-b413968f":{"ex":"하루 종일 일해서 파김치가 됐어요.","exFr":"J'ai travaillé toute la journée, je suis lessivé.","conj":"파김치가 돼요 · 파김치가 됐어요","note":"Litt. « devenir kimchi de ciboules » (tout ramolli par la saumure) — épuisé, vidé."},"pack-2a1a528d":{"ex":"이번 시험에서 미역국을 먹었어요.","exFr":"J'ai raté l'examen cette fois-ci.","conj":"미역국을 먹어요 · 미역국을 먹었어요","note":"La soupe d'algues est glissante — on « glisse » (미끄러지다 = échouer) à l'examen, au concours."},"pack-249e58b7":{"ex":"소풍을 가려고 했는데 비가 와서 김이 샜어요.","exFr":"On voulait pique-niquer mais il a plu, ça a cassé l'ambiance.","conj":"김이 새요 · 김이 샜어요","note":"Litt. « la vapeur s'échappe » — enthousiasme retombé, effet gâché. Fam. : 김샜어."},"pack-6ec66005":{"ex":"저 가방은 저한테 그림의 떡이에요.","exFr":"Ce sac, pour moi, c'est inaccessible.","note":"Litt. « le tteok du tableau » — beau mais hors de portée. S'emploie avec -이다 : 그림의 떡이에요."},"pack-02ba4803":{"ex":"이 문제는 식은 죽 먹기예요.","exFr":"Ce problème, c'est du gâteau.","note":"Litt. « manger du juk refroidi » — aucun effort. S'emploie avec -이다. Syn. 누워서 떡 먹기."},"pack-9aaf3a25":{"note":"-아/어 버리다 : action complète, nuance de regret ou de soulagement"},"pack-acfd5366":{"note":"-아/어 버리다 : action complète, nuance de regret ou de soulagement"},"pack-1e52de0f":{"note":"-게 하다 : causatif « faire faire / laisser faire »"},"pack-e6032df8":{"note":"-게 하다 : causatif « faire faire / laisser faire »"},"pack-a2152a46":{"note":"-(으)ㄹ 뻔했다 : « avoir failli » (l'action ne s'est pas produite)"},"pack-547bffbf":{"note":"-(으)ㄹ 뻔했다 : « avoir failli » — avec 잊다, les natifs disent presque toujours 잊어버리다"},"pack-874b9430":{"note":"-던 : souvenir du passé, action habituelle ou restée inachevée"},"pack-6d3f24aa":{"note":"마시던 : action commencée puis interrompue (le café n'est pas fini)"},"pack-0b47fd05":{"note":"-다가 : action interrompue par une autre en cours de route"},"pack-701a069f":{"note":"-다가 : action interrompue par une autre en cours de route"},"pack-58401b30":{"note":"-(으)ㄴ 채로 : « en l'état », l'état précédent se maintient"},"pack-e1164073":{"note":"-(으)ㄴ 채로 : « en l'état » — 열다 → 연 (chute du ㄹ devant ㄴ)"},"pack-abd671b2":{"note":"팔리다 : passif de 팔다 — « se vendre, être vendu »"},"pack-0a6ce499":{"note":"잠기다 : passif de 잠그다 — « être verrouillé »"},"pack-3eb7ede5":{"note":"-(으)면서도 : « tout en..., pourtant » — contraste fort"},"pack-54151c55":{"note":"-(으)면서도 : « tout en..., pourtant » — contraste fort"},"pack-33e31b24":{"note":"-기는 하지만 : concession « certes..., mais » — avec 은/는 de contraste sur le sujet"},"pack-39895334":{"note":"-기는 하지만 : concession « certes..., mais » (oral : souvent contracté en -긴 하지만)"},"pack-1c0f66f4":{"note":"-(으)ㄹ 수밖에 없다 : « ne pas avoir d'autre choix que de » — 수밖에 s'écrit attaché (밖에 = particule)"},"pack-f653cb54":{"note":"-(으)ㄹ 수밖에 없다 : « ne pas avoir d'autre choix que de »"},"pack-c22628d8":{"note":"-나 보다 : supposition d'après un indice observé (« il semble que ») — verbes en -나, adjectifs en -(으)ㄴ가"},"pack-2720c5de":{"note":"-나 보다 : supposition d'après un indice — 맛있다 contient 있다, donc prend -나 (맛있나 봐요), pas -(으)ㄴ가"}};
